/**
 * Bedrock Structure Studio for Blockbench
 * =======================================
 *
 * A dependency-free Blockbench plugin plus a reusable little-endian NBT and
 * Minecraft Bedrock .mcstructure codec. The codec contains two layers:
 *
 * 1. LittleEndianNBTReader
 *    Parses the complete classic NBT tag set using Bedrock's little-endian encoding.
 *
 * 2. MinecraftBedrockStructure
 *    Validates and exposes the semantic contents of a Bedrock .mcstructure file:
 *    dimensions, block layers, palettes, block states, block entities, scheduled
 *    ticks, entities, coordinate conversion, iteration, statistics, and helpers
 *    suitable for importing blocks into Blockbench.
 *
 * No external libraries are required.
 *
 * Runtime requirements:
 * - Modern Chromium / Blockbench
 * - Node.js 12+ (BigInt and TextDecoder support are preferred)
 *
 * @license MIT-0
 */

const BedrockStructureParser = (() => {
    'use strict';

    /** @enum {number} */
    const NBT_TAG = Object.freeze({
        End: 0,
        Byte: 1,
        Short: 2,
        Int: 3,
        Long: 4,
        Float: 5,
        Double: 6,
        ByteArray: 7,
        String: 8,
        List: 9,
        Compound: 10,
        IntArray: 11,
        LongArray: 12,
    });

    const NBT_TAG_NAME = Object.freeze([
        'End',
        'Byte',
        'Short',
        'Int',
        'Long',
        'Float',
        'Double',
        'ByteArray',
        'String',
        'List',
        'Compound',
        'IntArray',
        'LongArray',
    ]);

    const DEFAULT_LIMITS = Object.freeze({
        maxDepth: 512,
        maxStringBytes: 16 * 1024 * 1024,
        maxCollectionLength: 64 * 1024 * 1024,
        maxVolume: 64 * 1024 * 1024,
    });
    const NBT_INT_MIN = -2147483648;
    const NBT_INT_MAX = 2147483647;

    /**
     * Error thrown for malformed or unsupported NBT data.
     */
    class NBTParseError extends Error {
        /**
         * @param {string} message
         * @param {{offset?: number, path?: string, code?: string, cause?: unknown}} [details]
         */
        constructor(message, details = {}) {
            const suffix = [
                Number.isInteger(details.offset) ? `offset ${details.offset}` : '',
                details.path ? `path ${details.path}` : '',
            ].filter(Boolean).join(', ');

            super(suffix ? `${message} (${suffix})` : message);
            this.name = 'NBTParseError';
            this.code = details.code || 'NBT_PARSE_ERROR';
            this.offset = Number.isInteger(details.offset) ? details.offset : null;
            this.path = details.path || null;
            if (details.cause !== undefined) this.cause = details.cause;
        }
    }

    /**
     * Error thrown when the NBT is valid but the .mcstructure schema is invalid.
     */
    class MCStructureParseError extends Error {
        /**
         * @param {string} message
         * @param {{path?: string, code?: string, cause?: unknown}} [details]
         */
        constructor(message, details = {}) {
            super(details.path ? `${message} (path ${details.path})` : message);
            this.name = 'MCStructureParseError';
            this.code = details.code || 'MCSTRUCTURE_PARSE_ERROR';
            this.path = details.path || null;
            if (details.cause !== undefined) this.cause = details.cause;
        }
    }

    /**
     * Convert all supported binary inputs into a Uint8Array without corrupting
     * Buffer byte offsets or sliced typed arrays.
     *
     * @param {ArrayBuffer|SharedArrayBuffer|ArrayBufferView} input
     * @returns {Uint8Array}
     */
    function toUint8Array(input) {
        if (input instanceof Uint8Array) {
            return new Uint8Array(input.buffer, input.byteOffset, input.byteLength);
        }

        if (typeof ArrayBuffer !== 'undefined' && input instanceof ArrayBuffer) {
            return new Uint8Array(input);
        }

        if (typeof SharedArrayBuffer !== 'undefined' && input instanceof SharedArrayBuffer) {
            return new Uint8Array(input);
        }

        if (typeof ArrayBuffer !== 'undefined' && ArrayBuffer.isView(input)) {
            return new Uint8Array(input.buffer, input.byteOffset, input.byteLength);
        }

        throw new TypeError(
            'Expected an ArrayBuffer, SharedArrayBuffer, Buffer, Uint8Array, or another ArrayBuffer view.'
        );
    }

    /**
     * Decode UTF-8 in browsers, Blockbench, and Node.js.
     *
     * @param {Uint8Array} bytes
     * @returns {string}
     */
    const sharedTextDecoder = typeof TextDecoder !== 'undefined'
        ? new TextDecoder('utf-8', {fatal: false})
        : null;
    const sharedTextEncoder = typeof TextEncoder !== 'undefined'
        ? new TextEncoder()
        : null;

    function decodeUtf8(bytes) {
        if (typeof TextDecoder !== 'undefined') {
            // fatal:false matches the forgiving behavior most NBT readers use.
            return sharedTextDecoder.decode(bytes);
        }

        if (typeof Buffer !== 'undefined') {
            return Buffer.from(bytes.buffer, bytes.byteOffset, bytes.byteLength).toString('utf8');
        }

        // Conservative fallback for uncommon runtimes lacking TextDecoder.
        let binary = '';
        const chunkSize = 0x8000;
        for (let i = 0; i < bytes.length; i += chunkSize) {
            binary += String.fromCharCode(...bytes.subarray(i, i + chunkSize));
        }
        try {
            return decodeURIComponent(escape(binary));
        } catch {
            return binary;
        }
    }

    /**
     * Returns true for plain objects, including null-prototype dictionaries.
     *
     * @param {unknown} value
     * @returns {value is Record<string, any>}
     */
    function isObjectRecord(value) {
        return value !== null && typeof value === 'object' && !Array.isArray(value) && !ArrayBuffer.isView(value);
    }

    /**
     * Create a dictionary that cannot be affected by keys such as "__proto__".
     * This matters when parsing untrusted NBT compounds.
     *
     * @returns {Record<string, any>}
     */
    function createDictionary() {
        return Object.create(null);
    }

    /**
     * Safely multiply positive integer dimensions and reject overflow.
     *
     * @param {number} x
     * @param {number} y
     * @param {number} z
     * @param {number} maximum
     * @returns {number}
     */
    function checkedVolume(x, y, z, maximum) {
        if (![x, y, z].every(Number.isSafeInteger)) {
            throw new MCStructureParseError('Structure dimensions must be safe integers.', {
                path: 'size',
                code: 'INVALID_DIMENSIONS',
            });
        }
        if (x < 0 || y < 0 || z < 0) {
            throw new MCStructureParseError('Structure dimensions cannot be negative.', {
                path: 'size',
                code: 'INVALID_DIMENSIONS',
            });
        }

        const volume = x * y * z;
        if (!Number.isSafeInteger(volume)) {
            throw new MCStructureParseError('Structure volume exceeds JavaScript safe integer limits.', {
                path: 'size',
                code: 'VOLUME_OVERFLOW',
            });
        }
        if (volume > maximum) {
            throw new MCStructureParseError(
                `Structure volume ${volume.toLocaleString()} exceeds the configured maximum ${maximum.toLocaleString()}.`,
                {path: 'size', code: 'VOLUME_LIMIT_EXCEEDED'}
            );
        }
        return volume;
    }

    /**
     * A complete reader for classic NBT encoded with little-endian numbers.
     * Bedrock .mcstructure files use this encoding and are normally uncompressed.
     */
    class LittleEndianNBTReader {
        /**
         * @param {ArrayBuffer|SharedArrayBuffer|ArrayBufferView} input
         * @param {{
         *   preserveTypes?: boolean,
         *   longMode?: 'bigint'|'number'|'string',
         *   arrayMode?: 'typed'|'array',
         *   allowTrailingBytes?: boolean,
         *   maxDepth?: number,
         *   maxStringBytes?: number,
         *   maxCollectionLength?: number
         * }} [options]
         */
        constructor(input, options = {}) {
            this.bytes = toUint8Array(input);
            this.view = new DataView(this.bytes.buffer, this.bytes.byteOffset, this.bytes.byteLength);
            this.offset = 0;

            this.options = {
                preserveTypes: options.preserveTypes === true,
                longMode: options.longMode || 'bigint',
                arrayMode: options.arrayMode || 'typed',
                allowTrailingBytes: options.allowTrailingBytes === true,
                maxDepth: options.maxDepth ?? DEFAULT_LIMITS.maxDepth,
                maxStringBytes: options.maxStringBytes ?? DEFAULT_LIMITS.maxStringBytes,
                maxCollectionLength: options.maxCollectionLength ?? DEFAULT_LIMITS.maxCollectionLength,
            };

            if (!['bigint', 'number', 'string'].includes(this.options.longMode)) {
                throw new TypeError('longMode must be "bigint", "number", or "string".');
            }
            if (!['typed', 'array'].includes(this.options.arrayMode)) {
                throw new TypeError('arrayMode must be "typed" or "array".');
            }
        }

        /** @returns {number} */
        get remaining() {
            return this.bytes.byteLength - this.offset;
        }

        /**
         * Parse one named NBT root tag.
         *
         * @returns {{
         *   name: string,
         *   type: number,
         *   typeName: string,
         *   value: any,
         *   bytesRead: number,
         *   trailingBytes: number
         * }}
         */
        parse() {
            if (this.bytes.byteLength === 0) {
                throw this.error('The NBT input is empty.', '$', 'EMPTY_INPUT');
            }

            if (this.bytes[0] === 0x1f && this.bytes[1] === 0x8b) {
                throw this.error(
                    'Gzip-compressed NBT was supplied. Standard .mcstructure files are uncompressed; decompress it before parsing.',
                    '$',
                    'UNSUPPORTED_GZIP'
                );
            }

            const type = this.readTagType('$');
            if (type === NBT_TAG.End) {
                throw this.error('A named root tag cannot be TAG_End.', '$', 'INVALID_ROOT_TAG');
            }

            const name = this.readString('$<root-name>');
            const path = name ? `$[${JSON.stringify(name)}]` : '$';
            const value = this.readPayload(type, 0, path);
            const trailingBytes = this.remaining;

            if (trailingBytes !== 0 && !this.options.allowTrailingBytes) {
                throw this.error(
                    `Unexpected ${trailingBytes} trailing byte${trailingBytes === 1 ? '' : 's'} after the root tag.`,
                    '$',
                    'TRAILING_BYTES'
                );
            }

            return {
                name,
                type,
                typeName: NBT_TAG_NAME[type],
                value,
                bytesRead: this.offset,
                trailingBytes,
            };
        }

        /**
         * Convenience static API.
         *
         * @param {ArrayBuffer|SharedArrayBuffer|ArrayBufferView} input
         * @param {ConstructorParameters<typeof LittleEndianNBTReader>[1]} [options]
         */
        static parse(input, options = {}) {
            return new LittleEndianNBTReader(input, options).parse();
        }

        /**
         * Read an NBT payload of a known type.
         *
         * When preserveTypes is enabled, child tags are represented as objects:
         * `{type, typeName, value}`. Compound children additionally have `name`,
         * and list nodes expose `elementType` and `elementTypeName`.
         *
         * @param {number} type
         * @param {number} depth
         * @param {string} path
         * @returns {any}
         */
        readPayload(type, depth, path) {
            if (depth > this.options.maxDepth) {
                throw this.error(
                    `NBT nesting depth exceeds the configured maximum of ${this.options.maxDepth}.`,
                    path,
                    'MAX_DEPTH_EXCEEDED'
                );
            }

            switch (type) {
                case NBT_TAG.Byte:
                    return this.readInt8(path);
                case NBT_TAG.Short:
                    return this.readInt16(path);
                case NBT_TAG.Int:
                    return this.readInt32(path);
                case NBT_TAG.Long:
                    return this.convertLong(this.readBigInt64(path), path);
                case NBT_TAG.Float:
                    return this.readFloat32(path);
                case NBT_TAG.Double:
                    return this.readFloat64(path);
                case NBT_TAG.ByteArray:
                    return this.readByteArray(path);
                case NBT_TAG.String:
                    return this.readString(path);
                case NBT_TAG.List:
                    return this.readList(depth + 1, path);
                case NBT_TAG.Compound:
                    return this.readCompound(depth + 1, path);
                case NBT_TAG.IntArray:
                    return this.readIntArray(path);
                case NBT_TAG.LongArray:
                    return this.readLongArray(path);
                case NBT_TAG.End:
                    throw this.error('TAG_End cannot be used as a standalone payload.', path, 'UNEXPECTED_END_TAG');
                default:
                    throw this.error(`Unsupported NBT tag type ${type}.`, path, 'UNKNOWN_TAG_TYPE');
            }
        }

        /**
         * @param {number} depth
         * @param {string} path
         */
        readCompound(depth, path) {
            const compound = createDictionary();

            while (true) {
                const type = this.readTagType(path);
                if (type === NBT_TAG.End) break;

                const name = this.readString(`${path}<tag-name>`);
                const childPath = `${path}[${JSON.stringify(name)}]`;
                const childValue = this.readPayload(type, depth, childPath);

                compound[name] = this.options.preserveTypes
                    ? {name, type, typeName: NBT_TAG_NAME[type], value: childValue}
                    : childValue;
            }

            return compound;
        }

        /**
         * @param {number} depth
         * @param {string} path
         */
        readList(depth, path) {
            const elementType = this.readTagType(`${path}<element-type>`);
            const length = this.readLength(`${path}<length>`);

            if (elementType === NBT_TAG.End && length !== 0) {
                throw this.error('Only an empty list may use TAG_End as its element type.', path, 'INVALID_END_LIST');
            }

            // .mcstructure block_indices are enormous homogeneous TAG_Int lists.
            // Wrapping every integer in {type,typeName,value} can create millions of
            // short-lived objects before the semantic layer copies them to Int32Array.
            // Keep large Int lists compact while preserving their list-level NBT type.
            if (this.options.preserveTypes && this.options.arrayMode === 'typed'
                && elementType === NBT_TAG.Int && length >= 256) {
                const items = new Int32Array(length);
                const byteLength = length * 4;
                this.ensure(byteLength, path);
                let cursor = this.offset;
                for (let i = 0; i < length; i++, cursor += 4) items[i] = this.view.getInt32(cursor, true);
                this.offset += byteLength;
                return {
                    elementType,
                    elementTypeName: NBT_TAG_NAME[elementType],
                    items,
                    compactPrimitiveItems: true,
                };
            }

            const items = new Array(length);
            for (let i = 0; i < length; i++) {
                const itemPath = `${path}[${i}]`;
                const itemValue = this.readPayload(elementType, depth, itemPath);
                items[i] = this.options.preserveTypes
                    ? {type: elementType, typeName: NBT_TAG_NAME[elementType], value: itemValue}
                    : itemValue;
            }

            if (this.options.preserveTypes) {
                return {
                    elementType,
                    elementTypeName: NBT_TAG_NAME[elementType],
                    items,
                };
            }

            return items;
        }

        /** @param {string} path */
        readByteArray(path) {
            const length = this.readLength(`${path}<length>`);
            this.ensure(length, path);

            // NBT bytes are signed. Copy into a detached Int8Array so the result
            // does not retain the entire source file's ArrayBuffer.
            const result = new Int8Array(length);
            result.set(new Int8Array(this.bytes.buffer, this.bytes.byteOffset + this.offset, length));
            this.offset += length;

            return this.options.arrayMode === 'array' ? Array.from(result) : result;
        }

        /** @param {string} path */
        readIntArray(path) {
            const length = this.readLength(`${path}<length>`);
            const result = this.options.arrayMode === 'typed' ? new Int32Array(length) : new Array(length);
            for (let i = 0; i < length; i++) result[i] = this.readInt32(`${path}[${i}]`);
            return result;
        }

        /** @param {string} path */
        readLongArray(path) {
            const length = this.readLength(`${path}<length>`);
            const result = new Array(length);
            for (let i = 0; i < length; i++) {
                result[i] = this.convertLong(this.readBigInt64(`${path}[${i}]`), `${path}[${i}]`);
            }
            return result;
        }

        /** @param {bigint} value @param {string} path */
        convertLong(value, path) {
            switch (this.options.longMode) {
                case 'bigint':
                    return value;
                case 'string':
                    return value.toString();
                case 'number': {
                    const number = Number(value);
                    if (!Number.isSafeInteger(number)) {
                        throw this.error(
                            `NBT long ${value.toString()} cannot be represented safely as a JavaScript number.`,
                            path,
                            'UNSAFE_LONG'
                        );
                    }
                    return number;
                }
                default:
                    throw new TypeError(`Unknown longMode: ${this.options.longMode}`);
            }
        }

        /** @param {string} path */
        readTagType(path) {
            const type = this.readUint8(path);
            if (type < NBT_TAG.End || type > NBT_TAG.LongArray) {
                throw this.error(`Unknown NBT tag type ${type}.`, path, 'UNKNOWN_TAG_TYPE');
            }
            return type;
        }

        /** @param {string} path */
        readLength(path) {
            const length = this.readInt32(path);
            if (length < 0) {
                throw this.error(`Negative NBT collection length ${length}.`, path, 'NEGATIVE_LENGTH');
            }
            if (length > this.options.maxCollectionLength) {
                throw this.error(
                    `NBT collection length ${length.toLocaleString()} exceeds the configured maximum ${this.options.maxCollectionLength.toLocaleString()}.`,
                    path,
                    'COLLECTION_LIMIT_EXCEEDED'
                );
            }
            return length;
        }

        /** @param {string} path */
        readString(path) {
            const length = this.readUint16(path);
            if (length > this.options.maxStringBytes) {
                throw this.error(
                    `NBT string byte length ${length.toLocaleString()} exceeds the configured maximum ${this.options.maxStringBytes.toLocaleString()}.`,
                    path,
                    'STRING_LIMIT_EXCEEDED'
                );
            }
            this.ensure(length, path);
            const bytes = this.bytes.subarray(this.offset, this.offset + length);
            this.offset += length;
            return decodeUtf8(bytes);
        }

        /** @param {number} count @param {string} path */
        ensure(count, path) {
            if (!Number.isSafeInteger(count) || count < 0) {
                throw this.error(`Invalid byte count ${count}.`, path, 'INVALID_BYTE_COUNT');
            }
            if (this.offset + count > this.bytes.byteLength) {
                throw this.error(
                    `Unexpected end of input: requested ${count} byte${count === 1 ? '' : 's'}, but only ${this.remaining} remain.`,
                    path,
                    'UNEXPECTED_EOF'
                );
            }
        }

        /** @param {string} path */
        readUint8(path) {
            this.ensure(1, path);
            return this.view.getUint8(this.offset++);
        }

        /** @param {string} path */
        readInt8(path) {
            this.ensure(1, path);
            return this.view.getInt8(this.offset++);
        }

        /** @param {string} path */
        readUint16(path) {
            this.ensure(2, path);
            const value = this.view.getUint16(this.offset, true);
            this.offset += 2;
            return value;
        }

        /** @param {string} path */
        readInt16(path) {
            this.ensure(2, path);
            const value = this.view.getInt16(this.offset, true);
            this.offset += 2;
            return value;
        }

        /** @param {string} path */
        readInt32(path) {
            this.ensure(4, path);
            const value = this.view.getInt32(this.offset, true);
            this.offset += 4;
            return value;
        }

        /** @param {string} path */
        readBigInt64(path) {
            this.ensure(8, path);
            let value;

            if (typeof this.view.getBigInt64 === 'function') {
                value = this.view.getBigInt64(this.offset, true);
            } else {
                const low = BigInt(this.view.getUint32(this.offset, true));
                const high = BigInt(this.view.getInt32(this.offset + 4, true));
                value = (high << 32n) | low;
            }

            this.offset += 8;
            return value;
        }

        /** @param {string} path */
        readFloat32(path) {
            this.ensure(4, path);
            const value = this.view.getFloat32(this.offset, true);
            this.offset += 4;
            return value;
        }

        /** @param {string} path */
        readFloat64(path) {
            this.ensure(8, path);
            const value = this.view.getFloat64(this.offset, true);
            this.offset += 8;
            return value;
        }

        /**
         * @param {string} message
         * @param {string} path
         * @param {string} code
         */
        error(message, path, code) {
            return new NBTParseError(message, {offset: this.offset, path, code});
        }
    }


    /**
     * Error thrown when a JavaScript value cannot be encoded as valid NBT.
     */
    class NBTWriteError extends Error {
        /**
         * @param {string} message
         * @param {{path?: string, code?: string, cause?: unknown}} [details]
         */
        constructor(message, details = {}) {
            super(details.path ? `${message} (path ${details.path})` : message);
            this.name = 'NBTWriteError';
            this.code = details.code || 'NBT_WRITE_ERROR';
            this.path = details.path || null;
            if (details.cause !== undefined) this.cause = details.cause;
        }
    }

    /** Encode UTF-8 in browsers, Blockbench, and Node.js. */
    function encodeUtf8(value) {
        if (typeof value !== 'string') throw new TypeError('NBT strings must be JavaScript strings.');
        if (sharedTextEncoder) return sharedTextEncoder.encode(value);
        if (typeof Buffer !== 'undefined') return new Uint8Array(Buffer.from(value, 'utf8'));

        const encoded = unescape(encodeURIComponent(value));
        const bytes = new Uint8Array(encoded.length);
        for (let i = 0; i < encoded.length; i++) bytes[i] = encoded.charCodeAt(i);
        return bytes;
    }

    /** Resolve either a numeric tag id or a tag name such as "Int". */
    function normalizeNBTType(type) {
        if (Number.isInteger(type) && type >= NBT_TAG.End && type <= NBT_TAG.LongArray) return type;
        if (typeof type === 'string' && Object.prototype.hasOwnProperty.call(NBT_TAG, type)) return NBT_TAG[type];
        throw new TypeError(`Unknown NBT type ${JSON.stringify(type)}.`);
    }

    /** Return true when a value is a typed NBT node. */
    function isNBTNode(value) {
        return isObjectRecord(value)
            && Number.isInteger(value.type)
            && value.type >= NBT_TAG.End
            && value.type <= NBT_TAG.LongArray
            && Object.prototype.hasOwnProperty.call(value, 'value');
    }

    /** Create one mutable typed NBT node. */
    function createNBTNode(type, value, name) {
        const normalizedType = normalizeNBTType(type);
        const node = {type: normalizedType, typeName: NBT_TAG_NAME[normalizedType], value};
        if (name !== undefined) node.name = String(name);
        return node;
    }

    /** Deep-clone arbitrary values used by NBT nodes. */
    function cloneValue(value, options = {}) {
        if (typeof value === 'bigint' || value == null || typeof value !== 'object') return value;
        if (value instanceof DataView) {
            const copy = value.buffer.slice(value.byteOffset, value.byteOffset + value.byteLength);
            return new DataView(copy);
        }
        if (ArrayBuffer.isView(value)) return options.shareTypedArrays ? value : new value.constructor(value);
        if (value instanceof ArrayBuffer) return options.shareTypedArrays ? value : value.slice(0);
        if (Array.isArray(value)) return value.map(item => cloneValue(item, options));
        const result = Object.getPrototypeOf(value) === null ? createDictionary() : {};
        for (const key of Object.keys(value)) result[key] = cloneValue(value[key], options);
        return result;
    }

    /** Deep-clone a typed NBT node or complete root document. */
    function cloneNBT(value, options = {}) {
        return cloneValue(value, options);
    }

    /** Convert a typed NBT node into the plain representation used by the semantic parser. */
    function unwrapNBTNode(node, options = {}) {
        if (!isNBTNode(node)) throw new TypeError('unwrapNBTNode expects a typed NBT node.');
        const cloneTypedArrays = options.cloneTypedArrays !== false;
        switch (node.type) {
            case NBT_TAG.Compound: {
                const result = createDictionary();
                for (const key of Object.keys(node.value)) result[key] = unwrapNBTNode(node.value[key], options);
                return result;
            }
            case NBT_TAG.List:
                if (ArrayBuffer.isView(node.value.items)) {
                    return cloneTypedArrays ? new node.value.items.constructor(node.value.items) : node.value.items;
                }
                return node.value.items.map(item => unwrapNBTNode(item, options));
            case NBT_TAG.ByteArray:
                return node.value instanceof Int8Array
                    ? (cloneTypedArrays ? new Int8Array(node.value) : node.value)
                    : Int8Array.from(node.value);
            case NBT_TAG.IntArray:
                return node.value instanceof Int32Array
                    ? (cloneTypedArrays ? new Int32Array(node.value) : node.value)
                    : Int32Array.from(node.value);
            case NBT_TAG.LongArray:
                return Array.from(node.value);
            default:
                return node.value;
        }
    }

    /** Convert a complete typed root document into a plain root compound. */
    function unwrapNBTDocument(document, options = {}) {
        if (!document || !Number.isInteger(document.type)) {
            throw new TypeError('unwrapNBTDocument expects a parsed typed NBT document.');
        }
        return unwrapNBTNode(createNBTNode(document.type, document.value, document.name), options);
    }

    /** Infer a precise-enough NBT node from ordinary JavaScript data. */
    function inferNBTNode(value, options = {}) {
        if (isNBTNode(value)) return cloneNBT(value);
        if (value === null || value === undefined) {
            throw new NBTWriteError('NBT cannot encode null or undefined directly.', {
                path: options.path || '$',
                code: 'NULL_NOT_SUPPORTED',
            });
        }
        if (typeof value === 'boolean') return createNBTNode(NBT_TAG.Byte, value ? 1 : 0);
        if (typeof value === 'bigint') return createNBTNode(NBT_TAG.Long, value);
        if (typeof value === 'string') return createNBTNode(NBT_TAG.String, value);
        if (typeof value === 'number') {
            if (!Number.isFinite(value)) {
                throw new NBTWriteError('NBT numeric values must be finite.', {path: options.path || '$'});
            }
            if (Number.isInteger(value) && value >= -2147483648 && value <= 2147483647) {
                return createNBTNode(NBT_TAG.Int, value);
            }
            return createNBTNode(NBT_TAG.Double, value);
        }
        if (value instanceof Int8Array || value instanceof Uint8Array || value instanceof Uint8ClampedArray) {
            return createNBTNode(NBT_TAG.ByteArray, Int8Array.from(value));
        }
        if (value instanceof Int32Array || value instanceof Uint32Array) {
            return createNBTNode(NBT_TAG.IntArray, Int32Array.from(value));
        }
        if (Array.isArray(value)) {
            if (value.length === 0) {
                const elementType = options.emptyListType == null
                    ? NBT_TAG.End
                    : normalizeNBTType(options.emptyListType);
                return createNBTNode(NBT_TAG.List, {
                    elementType,
                    elementTypeName: NBT_TAG_NAME[elementType],
                    items: [],
                });
            }
            const items = value.map((item, index) => inferNBTNode(item, {
                ...options,
                path: `${options.path || '$'}[${index}]`,
            }));
            const elementType = items[0].type;
            if (!items.every(item => item.type === elementType)) {
                throw new NBTWriteError(
                    'NBT lists must contain exactly one payload type. Use explicit NBT factory nodes when values need narrower numeric types.',
                    {path: options.path || '$', code: 'HETEROGENEOUS_LIST'}
                );
            }
            return createNBTNode(NBT_TAG.List, {
                elementType,
                elementTypeName: NBT_TAG_NAME[elementType],
                items,
            });
        }
        if (isObjectRecord(value)) {
            const compound = createDictionary();
            for (const key of Object.keys(value)) {
                const child = inferNBTNode(value[key], {...options, path: `${options.path || '$'}.${key}`});
                child.name = key;
                compound[key] = child;
            }
            return createNBTNode(NBT_TAG.Compound, compound);
        }
        throw new NBTWriteError(`Unsupported JavaScript value ${Object.prototype.toString.call(value)}.`, {
            path: options.path || '$',
            code: 'UNSUPPORTED_VALUE',
        });
    }

    /**
     * Typed NBT node factories. Use these whenever exact numeric widths matter,
     * especially for entities, block entities, and custom extension tags.
     */
    const NBT = Object.freeze({
        node: createNBTNode,
        byte: value => createNBTNode(NBT_TAG.Byte, Number(value)),
        short: value => createNBTNode(NBT_TAG.Short, Number(value)),
        int: value => createNBTNode(NBT_TAG.Int, Number(value)),
        long: value => createNBTNode(NBT_TAG.Long, typeof value === 'bigint' ? value : BigInt(value)),
        float: value => createNBTNode(NBT_TAG.Float, Number(value)),
        double: value => createNBTNode(NBT_TAG.Double, Number(value)),
        byteArray: value => createNBTNode(NBT_TAG.ByteArray, Int8Array.from(value)),
        string: value => createNBTNode(NBT_TAG.String, String(value)),
        intArray: value => createNBTNode(NBT_TAG.IntArray, Int32Array.from(value)),
        longArray: value => createNBTNode(NBT_TAG.LongArray, Array.from(value, item => BigInt(item))),
        list(type, values = []) {
            const elementType = normalizeNBTType(type);
            const items = values.map((value, index) => {
                let node;
                if (isNBTNode(value)) node = cloneNBT(value);
                else if (elementType === NBT_TAG.Compound) node = NBT.compound(value);
                else if (elementType === NBT_TAG.List) {
                    const inferred = inferNBTNode(value, {path: `$[${index}]`});
                    if (inferred.type !== NBT_TAG.List) {
                        throw new TypeError(`List item ${index} is not an NBT list.`);
                    }
                    node = inferred;
                } else node = createNBTNode(elementType, cloneValue(value));
                if (node.type !== elementType) {
                    throw new TypeError(`List item ${index} is ${node.typeName}, expected ${NBT_TAG_NAME[elementType]}.`);
                }
                delete node.name;
                return node;
            });
            if (elementType === NBT_TAG.End && items.length !== 0) {
                throw new TypeError('Only an empty NBT list may use TAG_End.');
            }
            return createNBTNode(NBT_TAG.List, {
                elementType,
                elementTypeName: NBT_TAG_NAME[elementType],
                items,
            });
        },
        compactIntList(values) {
            const items = values instanceof Int32Array ? values : Int32Array.from(values);
            return createNBTNode(NBT_TAG.List, {
                elementType: NBT_TAG.Int,
                elementTypeName: NBT_TAG_NAME[NBT_TAG.Int],
                items,
                compactPrimitiveItems: true,
            });
        },
        compound(value = {}) {
            if (!isObjectRecord(value)) throw new TypeError('NBT.compound expects an object of typed nodes or values.');
            const compound = createDictionary();
            for (const key of Object.keys(value)) {
                const child = isNBTNode(value[key]) ? cloneNBT(value[key]) : inferNBTNode(value[key], {path: `$.${key}`});
                child.name = key;
                compound[key] = child;
            }
            return createNBTNode(NBT_TAG.Compound, compound);
        },
        fromJS: inferNBTNode,
        clone: cloneNBT,
        unwrap: unwrapNBTNode,
    });

    /** A dynamically growing byte sink used by the NBT writer. */
    class ByteWriter {
        constructor(initialCapacity = 1024) {
            this.bytes = new Uint8Array(Math.max(32, initialCapacity));
            this.view = new DataView(this.bytes.buffer);
            this.offset = 0;
        }

        ensure(extra) {
            const required = this.offset + extra;
            if (required <= this.bytes.length) return;
            let capacity = this.bytes.length;
            while (capacity < required) capacity = Math.max(capacity * 2, required);
            const replacement = new Uint8Array(capacity);
            replacement.set(this.bytes);
            this.bytes = replacement;
            this.view = new DataView(replacement.buffer);
        }

        uint8(value) { this.ensure(1); this.view.setUint8(this.offset, value); this.offset += 1; }
        int8(value) { this.ensure(1); this.view.setInt8(this.offset, value); this.offset += 1; }
        uint16(value) { this.ensure(2); this.view.setUint16(this.offset, value, true); this.offset += 2; }
        int16(value) { this.ensure(2); this.view.setInt16(this.offset, value, true); this.offset += 2; }
        int32(value) { this.ensure(4); this.view.setInt32(this.offset, value, true); this.offset += 4; }
        float32(value) { this.ensure(4); this.view.setFloat32(this.offset, value, true); this.offset += 4; }
        float64(value) { this.ensure(8); this.view.setFloat64(this.offset, value, true); this.offset += 8; }
        int64(value) {
            const bigint = typeof value === 'bigint' ? value : BigInt(value);
            if (bigint < -9223372036854775808n || bigint > 9223372036854775807n) {
                throw new RangeError(`NBT long ${bigint.toString()} is outside signed 64-bit range.`);
            }
            this.ensure(8);
            if (typeof this.view.setBigInt64 === 'function') {
                this.view.setBigInt64(this.offset, bigint, true);
            } else {
                const unsigned = BigInt.asUintN(64, bigint);
                this.view.setUint32(this.offset, Number(unsigned & 0xffffffffn), true);
                this.view.setUint32(this.offset + 4, Number((unsigned >> 32n) & 0xffffffffn), true);
            }
            this.offset += 8;
        }
        raw(value) {
            const bytes = toUint8Array(value);
            this.ensure(bytes.byteLength);
            this.bytes.set(bytes, this.offset);
            this.offset += bytes.byteLength;
        }
        finish() { return this.bytes.slice(0, this.offset); }
    }

    /**
     * Complete classic NBT writer using Bedrock's little-endian numeric encoding.
     * It writes the typed documents returned by LittleEndianNBTReader when
     * preserveTypes is enabled, enabling byte-identical round trips.
     */
    class LittleEndianNBTWriter {
        /**
         * @param {{initialCapacity?:number, maxDepth?:number, maxStringBytes?:number, maxCollectionLength?:number}} [options]
         */
        constructor(options = {}) {
            this.options = {
                initialCapacity: options.initialCapacity ?? 1024,
                maxDepth: options.maxDepth ?? DEFAULT_LIMITS.maxDepth,
                maxStringBytes: options.maxStringBytes ?? 65535,
                maxCollectionLength: options.maxCollectionLength ?? DEFAULT_LIMITS.maxCollectionLength,
            };
            this.output = new ByteWriter(this.options.initialCapacity);
        }

        /** Write one named root document and return a detached Uint8Array. */
        write(document) {
            if (!document || !Number.isInteger(document.type)) {
                throw new TypeError('LittleEndianNBTWriter.write expects a typed NBT root document.');
            }
            const root = isNBTNode(document)
                ? document
                : createNBTNode(document.type, document.value, document.name || '');
            if (root.type === NBT_TAG.End) {
                throw this.error('A named root tag cannot be TAG_End.', '$', 'INVALID_ROOT_TAG');
            }
            this.output.uint8(root.type);
            this.writeString(root.name || '', '$<root-name>');
            this.writePayload(root.type, root.value, 0, '$');
            return this.output.finish();
        }

        /** Convenience static API. */
        static write(document, options = {}) {
            return new LittleEndianNBTWriter(options).write(document);
        }

        /** Alias suitable for code that thinks in terms of serialization. */
        static serialize(document, options = {}) {
            return LittleEndianNBTWriter.write(document, options);
        }

        writePayload(type, value, depth, path) {
            if (depth > this.options.maxDepth) {
                throw this.error(`NBT nesting depth exceeds ${this.options.maxDepth}.`, path, 'MAX_DEPTH_EXCEEDED');
            }
            switch (type) {
                case NBT_TAG.Byte:
                    this.assertIntegerRange(value, -128, 127, path, 'byte');
                    this.output.int8(value);
                    break;
                case NBT_TAG.Short:
                    this.assertIntegerRange(value, -32768, 32767, path, 'short');
                    this.output.int16(value);
                    break;
                case NBT_TAG.Int:
                    this.assertIntegerRange(value, -2147483648, 2147483647, path, 'int');
                    this.output.int32(value);
                    break;
                case NBT_TAG.Long:
                    try { this.output.int64(value); } catch (error) {
                        throw this.error(error.message, path, 'INVALID_LONG', error);
                    }
                    break;
                case NBT_TAG.Float:
                    this.assertFinite(value, path);
                    this.output.float32(value);
                    break;
                case NBT_TAG.Double:
                    this.assertFinite(value, path);
                    this.output.float64(value);
                    break;
                case NBT_TAG.ByteArray: {
                    const values = value instanceof Int8Array ? value : Int8Array.from(value);
                    this.writeLength(values.length, path);
                    this.output.raw(new Uint8Array(values.buffer, values.byteOffset, values.byteLength));
                    break;
                }
                case NBT_TAG.String:
                    this.writeString(value, path);
                    break;
                case NBT_TAG.List:
                    this.writeList(value, depth + 1, path);
                    break;
                case NBT_TAG.Compound:
                    this.writeCompound(value, depth + 1, path);
                    break;
                case NBT_TAG.IntArray: {
                    const values = value instanceof Int32Array ? value : Int32Array.from(value);
                    this.writeLength(values.length, path);
                    for (let i = 0; i < values.length; i++) this.output.int32(values[i]);
                    break;
                }
                case NBT_TAG.LongArray: {
                    const values = Array.from(value);
                    this.writeLength(values.length, path);
                    for (let i = 0; i < values.length; i++) this.output.int64(values[i]);
                    break;
                }
                case NBT_TAG.End:
                    throw this.error('TAG_End cannot be written as a payload.', path, 'UNEXPECTED_END_TAG');
                default:
                    throw this.error(`Unknown NBT type ${type}.`, path, 'UNKNOWN_TAG_TYPE');
            }
        }

        writeCompound(value, depth, path) {
            if (!isObjectRecord(value)) throw this.error('TAG_Compound requires an object.', path, 'INVALID_COMPOUND');
            for (const key of Object.keys(value)) {
                const child = value[key];
                if (!isNBTNode(child)) {
                    throw this.error(`Compound child ${JSON.stringify(key)} is not a typed NBT node.`, path, 'UNTYPED_CHILD');
                }
                if (child.type === NBT_TAG.End) {
                    throw this.error('TAG_End cannot be a named compound child.', `${path}.${key}`, 'NAMED_END_TAG');
                }
                this.output.uint8(child.type);
                this.writeString(child.name == null ? key : child.name, `${path}<tag-name>`);
                this.writePayload(child.type, child.value, depth, `${path}[${JSON.stringify(key)}]`);
            }
            this.output.uint8(NBT_TAG.End);
        }

        writeList(value, depth, path) {
            const compactItems = isObjectRecord(value) && ArrayBuffer.isView(value.items) && !(value.items instanceof DataView);
            if (!isObjectRecord(value) || (!Array.isArray(value.items) && !compactItems)) {
                throw this.error('TAG_List requires {elementType, items}.', path, 'INVALID_LIST');
            }
            const elementType = normalizeNBTType(value.elementType);
            if (elementType === NBT_TAG.End && value.items.length !== 0) {
                throw this.error('Only an empty list may use TAG_End.', path, 'INVALID_END_LIST');
            }
            this.output.uint8(elementType);
            this.writeLength(value.items.length, path);
            for (let i = 0; i < value.items.length; i++) {
                const item = value.items[i];
                if (compactItems) {
                    this.writePayload(elementType, item, depth, `${path}[${i}]`);
                    continue;
                }
                if (!isNBTNode(item) || item.type !== elementType) {
                    throw this.error(
                        `List item ${i} must be a typed ${NBT_TAG_NAME[elementType]} node.`,
                        `${path}[${i}]`,
                        'INVALID_LIST_ITEM'
                    );
                }
                this.writePayload(elementType, item.value, depth, `${path}[${i}]`);
            }
        }

        writeString(value, path) {
            if (typeof value !== 'string') throw this.error('NBT string value must be a string.', path, 'INVALID_STRING');
            const bytes = encodeUtf8(value);
            const maximum = Math.min(65535, this.options.maxStringBytes);
            if (bytes.byteLength > maximum) {
                throw this.error(`NBT string uses ${bytes.byteLength} UTF-8 bytes; maximum is ${maximum}.`, path, 'STRING_TOO_LONG');
            }
            this.output.uint16(bytes.byteLength);
            this.output.raw(bytes);
        }

        writeLength(length, path) {
            if (!Number.isSafeInteger(length) || length < 0 || length > 2147483647) {
                throw this.error(`Invalid NBT collection length ${length}.`, path, 'INVALID_LENGTH');
            }
            if (length > this.options.maxCollectionLength) {
                throw this.error(`NBT collection length ${length} exceeds configured limit.`, path, 'COLLECTION_LIMIT_EXCEEDED');
            }
            this.output.int32(length);
        }

        assertIntegerRange(value, min, max, path, label) {
            if (!Number.isInteger(value) || value < min || value > max) {
                throw this.error(`NBT ${label} must be an integer from ${min} to ${max}.`, path, `INVALID_${label.toUpperCase()}`);
            }
        }

        assertFinite(value, path) {
            if (typeof value !== 'number' || !Number.isFinite(value)) {
                throw this.error('NBT floating-point values must be finite numbers.', path, 'INVALID_FLOAT');
            }
        }

        error(message, path, code, cause) {
            return new NBTWriteError(message, {path, code, cause});
        }
    }

    /**
     * Decode the integer stored in a block palette entry into its four component
     * bytes. Minecraft displays these as major.minor.patch.revision.
     *
     * @param {number} packedVersion
     * @returns {{major:number, minor:number, patch:number, revision:number, string:string, packed:number}}
     */
    function decodeBlockVersion(packedVersion) {
        const packed = packedVersion >>> 0;
        const major = (packed >>> 24) & 0xff;
        const minor = (packed >>> 16) & 0xff;
        const patch = (packed >>> 8) & 0xff;
        const revision = packed & 0xff;
        return {
            major,
            minor,
            patch,
            revision,
            string: `${major}.${minor}.${patch}.${revision}`,
            packed: packedVersion,
        };
    }

    /**
     * Produce a deterministic key for one block permutation.
     * Useful for material lookup, deduplication, caching, and texture resolvers.
     *
     * @param {{name:string, states?:Record<string, any>}} block
     * @returns {string}
     */
    function blockPermutationKey(block) {
        const states = block && isObjectRecord(block.states) ? block.states : createDictionary();
        const keys = Object.keys(states).sort();
        if (keys.length === 0) return block.name;

        const encoded = keys.map(key => {
            const value = states[key];
            const printable = typeof value === 'bigint' ? `${value.toString()}n` : JSON.stringify(value);
            return `${key}=${printable}`;
        });
        return `${block.name}[${encoded.join(',')}]`;
    }

    // Palette slot identity is stricter than renderer/material identity. Bedrock
    // stores a packed block version on every palette entry, so otherwise-identical
    // name/state permutations with different versions must remain separate slots.
    function palettePermutationKey(block) {
        const version = Number(block?.version);
        return `${blockPermutationKey(block)}|version=${Number.isInteger(version) ? version : '<unspecified>'}`;
    }

    /**
     * Convert values containing BigInt and typed arrays into JSON-compatible data.
     * Null-prototype compounds are converted to ordinary objects.
     *
     * @param {any} value
     * @param {{bigint?: 'string'|'number', typedArrays?: 'array'|'object'}} [options]
     * @returns {any}
     */
    function toJSONCompatible(value, options = {}) {
        const bigintMode = options.bigint || 'string';
        const typedArrayMode = options.typedArrays || 'array';

        if (typeof value === 'bigint') {
            if (bigintMode === 'number') {
                const number = Number(value);
                if (!Number.isSafeInteger(number)) {
                    throw new RangeError(`BigInt ${value.toString()} cannot be safely converted to a number.`);
                }
                return number;
            }
            return value.toString();
        }

        if (ArrayBuffer.isView(value) && !(value instanceof DataView)) {
            if (typedArrayMode === 'object') {
                return {type: value.constructor.name, values: Array.from(value, item => toJSONCompatible(item, options))};
            }
            return Array.from(value, item => toJSONCompatible(item, options));
        }

        if (Array.isArray(value)) {
            return value.map(item => toJSONCompatible(item, options));
        }

        if (isObjectRecord(value)) {
            const result = {};
            for (const key of Object.keys(value)) result[key] = toJSONCompatible(value[key], options);
            return result;
        }

        return value;
    }

    /**
     * High-level representation of a parsed Bedrock structure.
     */
    class MinecraftBedrockStructure {
        /**
         * @param {Record<string, any>} root
         * @param {{
         *   palette?: string,
         *   strict?: boolean,
         *   invalidIndexPolicy?: 'warn'|'error'|'keep',
         *   maxVolume?: number,
         *   sourceName?: string,
         *   nbtDocument?: any
         * }} [options]
         */
        constructor(root, options = {}) {
            this.options = {
                palette: options.palette || 'default',
                strict: options.strict !== false,
                invalidIndexPolicy: options.invalidIndexPolicy || 'warn',
                maxVolume: options.maxVolume ?? DEFAULT_LIMITS.maxVolume,
                sourceName: options.sourceName || null,
            };

            if (!['warn', 'error', 'keep'].includes(this.options.invalidIndexPolicy)) {
                throw new TypeError('invalidIndexPolicy must be "warn", "error", or "keep".');
            }

            this.raw = root;
            this.nbtDocument = options.nbtDocument || null;
            this.warnings = [];

            this.formatVersion = this.requireInteger(root.format_version, 'format_version');
            if (this.formatVersion !== 1) {
                const message = `Unsupported .mcstructure format_version ${this.formatVersion}; only version 1 is currently defined.`;
                if (this.options.strict) {
                    throw new MCStructureParseError(message, {
                        path: 'format_version',
                        code: 'UNSUPPORTED_FORMAT_VERSION',
                    });
                }
                this.warn('UNSUPPORTED_FORMAT_VERSION', 'format_version', message);
            }

            const size = this.requireIntegerList(root.size, 3, 'size');
            this.size = Object.freeze({x: size[0], y: size[1], z: size[2]});
            this.volume = checkedVolume(this.size.x, this.size.y, this.size.z, this.options.maxVolume);

            const worldOrigin = this.requireIntegerList(root.structure_world_origin, 3, 'structure_world_origin');
            this.worldOrigin = Object.freeze({x: worldOrigin[0], y: worldOrigin[1], z: worldOrigin[2]});

            const structure = this.requireRecord(root.structure, 'structure');
            const rawLayers = this.requireList(structure.block_indices, 'structure.block_indices');
            if (rawLayers.length !== 2) {
                throw new MCStructureParseError(
                    `Expected exactly two block index layers, received ${rawLayers.length}.`,
                    {path: 'structure.block_indices', code: 'INVALID_LAYER_COUNT'}
                );
            }

            this.blockIndices = rawLayers.map((layer, layerIndex) => {
                const path = `structure.block_indices[${layerIndex}]`;
                const values = this.requireList(layer, path);
                if (values.length !== this.volume) {
                    throw new MCStructureParseError(
                        `Block layer length ${values.length} does not match structure volume ${this.volume}.`,
                        {path, code: 'INVALID_LAYER_LENGTH'}
                    );
                }

                // Typed list payloads are immutable in the parsed structure. Keep
                // the reader-owned array instead of immediately duplicating both
                // multi-million-cell layers; edit() still creates mutable copies.
                if (values instanceof Int32Array) return values;
                const result = new Int32Array(values.length);
                for (let i = 0; i < values.length; i++) {
                    if (!Number.isInteger(values[i])) {
                        throw new MCStructureParseError(`Block palette index at position ${i} is not an integer.`, {
                            path: `${path}[${i}]`,
                            code: 'INVALID_BLOCK_INDEX_TYPE',
                        });
                    }
                    result[i] = values[i];
                }
                return result;
            });

            this.primaryLayer = this.blockIndices[0];
            this.secondaryLayer = this.blockIndices[1];
            this.entities = this.requireList(structure.entities, 'structure.entities');

            this.palettes = this.parsePalettes(this.requireRecord(structure.palette, 'structure.palette'));
            this.paletteName = this.options.palette;
            this.palette = this.palettes[this.paletteName];

            if (!this.palette) {
                throw new MCStructureParseError(`Palette ${JSON.stringify(this.paletteName)} does not exist.`, {
                    path: `structure.palette.${this.paletteName}`,
                    code: 'PALETTE_NOT_FOUND',
                });
            }

            this.blockPalette = this.palette.blockPalette;
            this.blockPositionData = this.palette.blockPositionData;

            this.validatePaletteIndices();
        }

        /**
         * Parse a complete .mcstructure file from binary data.
         *
         * @param {ArrayBuffer|SharedArrayBuffer|ArrayBufferView} input
         * @param {{
         *   palette?: string,
         *   strict?: boolean,
         *   invalidIndexPolicy?: 'warn'|'error'|'keep',
         *   maxVolume?: number,
         *   sourceName?: string,
         *   longMode?: 'bigint'|'number'|'string',
         *   maxDepth?: number,
         *   maxStringBytes?: number,
         *   maxCollectionLength?: number,
         *   allowTrailingBytes?: boolean
         * }} [options]
         * @returns {MinecraftBedrockStructure}
         */
        static parse(input, options = {}) {
            let document;
            try {
                document = LittleEndianNBTReader.parse(input, {
                    // Keep exact tag widths so the document can be written back
                    // without collapsing Byte/Short/Int or Float/Double values.
                    preserveTypes: true,
                    longMode: options.longMode || 'bigint',
                    arrayMode: 'typed',
                    allowTrailingBytes: options.allowTrailingBytes === true,
                    maxDepth: options.maxDepth,
                    maxStringBytes: options.maxStringBytes,
                    maxCollectionLength: options.maxCollectionLength,
                });
            } catch (error) {
                if (error instanceof NBTParseError) throw error;
                throw new NBTParseError('Failed to parse little-endian NBT.', {
                    offset: 0,
                    path: '$',
                    code: 'NBT_PARSE_FAILURE',
                    cause: error,
                });
            }

            if (document.type !== NBT_TAG.Compound) {
                throw new MCStructureParseError(
                    `The .mcstructure root must be TAG_Compound, received ${document.typeName}.`,
                    {path: '$', code: 'INVALID_ROOT_TYPE'}
                );
            }

            return new MinecraftBedrockStructure(unwrapNBTDocument(document, {cloneTypedArrays: false}), {
                ...options,
                nbtDocument: document,
            });
        }

        /**
         * Parse a browser File or Blob.
         *
         * @param {Blob} blob
         * @param {Parameters<typeof MinecraftBedrockStructure.parse>[1]} [options]
         */
        static async fromBlob(blob, options = {}) {
            if (!blob || typeof blob.arrayBuffer !== 'function') {
                throw new TypeError('fromBlob expects a browser File or Blob.');
            }
            const sourceName = options.sourceName || (typeof blob.name === 'string' ? blob.name : null);
            return MinecraftBedrockStructure.parse(await blob.arrayBuffer(), {...options, sourceName});
        }

        /**
         * Parse the `content` value returned by Blockbench.import/read with
         * `readtype: "buffer"`.
         *
         * @param {{content: ArrayBuffer|ArrayBufferView, name?: string, path?: string}} file
         * @param {Parameters<typeof MinecraftBedrockStructure.parse>[1]} [options]
         */
        static fromBlockbenchFile(file, options = {}) {
            if (!file || file.content == null) {
                throw new TypeError('Expected a Blockbench file object containing binary `content`.');
            }
            const sourceName = options.sourceName || file.name || file.path || null;
            return MinecraftBedrockStructure.parse(file.content, {...options, sourceName});
        }

        /**
         * @param {Record<string, any>} rawPalettes
         */
        parsePalettes(rawPalettes) {
            const result = createDictionary();
            const names = Object.keys(rawPalettes);

            if (names.length === 0) {
                throw new MCStructureParseError('The structure contains no palettes.', {
                    path: 'structure.palette',
                    code: 'EMPTY_PALETTE_CONTAINER',
                });
            }

            for (const paletteName of names) {
                const path = `structure.palette[${JSON.stringify(paletteName)}]`;
                const rawPalette = this.requireRecord(rawPalettes[paletteName], path);
                const rawBlockPalette = this.requireList(rawPalette.block_palette, `${path}.block_palette`);
                const rawPositionData = this.requireRecord(rawPalette.block_position_data, `${path}.block_position_data`);

                const blockPalette = rawBlockPalette.map((rawBlock, index) => {
                    const blockPath = `${path}.block_palette[${index}]`;
                    const block = this.requireRecord(rawBlock, blockPath);
                    const name = this.requireString(block.name, `${blockPath}.name`);
                    const states = this.requireRecord(block.states, `${blockPath}.states`);
                    const version = this.requireInteger(block.version, `${blockPath}.version`);
                    const namespaceSeparator = name.indexOf(':');

                    return Object.freeze({
                        index,
                        name,
                        namespace: namespaceSeparator >= 0 ? name.slice(0, namespaceSeparator) : '',
                        identifier: namespaceSeparator >= 0 ? name.slice(namespaceSeparator + 1) : name,
                        states,
                        version,
                        versionInfo: Object.freeze(decodeBlockVersion(version)),
                        key: blockPermutationKey({name, states}),
                        raw: block,
                    });
                });

                const blockPositionData = new Map();
                for (const indexKey of Object.keys(rawPositionData)) {
                    if (!/^(0|[1-9]\d*)$/.test(indexKey)) {
                        this.warn(
                            'INVALID_POSITION_DATA_KEY',
                            `${path}.block_position_data[${JSON.stringify(indexKey)}]`,
                            `Ignoring non-integer block position data key ${JSON.stringify(indexKey)}.`
                        );
                        continue;
                    }

                    const index = Number(indexKey);
                    if (!Number.isSafeInteger(index) || index < 0 || index >= this.volume) {
                        this.warn(
                            'POSITION_DATA_OUT_OF_BOUNDS',
                            `${path}.block_position_data[${JSON.stringify(indexKey)}]`,
                            `Ignoring block position data index ${indexKey}; valid range is 0-${Math.max(0, this.volume - 1)}.`
                        );
                        continue;
                    }

                    const rawData = this.requireRecord(
                        rawPositionData[indexKey],
                        `${path}.block_position_data[${JSON.stringify(indexKey)}]`
                    );
                    const position = this.indexToCoordinates(index);
                    const tickQueueData = rawData.tick_queue_data == null
                        ? []
                        : this.requireList(
                            rawData.tick_queue_data,
                            `${path}.block_position_data[${JSON.stringify(indexKey)}].tick_queue_data`
                        );

                    blockPositionData.set(index, Object.freeze({
                        index,
                        position: Object.freeze(position),
                        blockEntityData: rawData.block_entity_data ?? null,
                        tickQueueData,
                        raw: rawData,
                    }));
                }

                result[paletteName] = Object.freeze({
                    name: paletteName,
                    blockPalette,
                    blockPositionData,
                    raw: rawPalette,
                });
            }

            return result;
        }

        /** Validate palette references in both block layers. */
        validatePaletteIndices() {
            let invalidCount = 0;
            let firstInvalid = null;

            for (let layer = 0; layer < this.blockIndices.length; layer++) {
                const values = this.blockIndices[layer];
                for (let index = 0; index < values.length; index++) {
                    const paletteIndex = values[index];
                    if (paletteIndex < -1 || paletteIndex >= this.blockPalette.length) {
                        invalidCount++;
                        if (!firstInvalid) firstInvalid = {layer, index, paletteIndex};
                    }
                }
            }

            if (invalidCount === 0 || this.options.invalidIndexPolicy === 'keep') return;

            const message = `${invalidCount} block index value${invalidCount === 1 ? '' : 's'} reference an invalid palette entry. First invalid value: layer ${firstInvalid.layer}, flat index ${firstInvalid.index}, palette index ${firstInvalid.paletteIndex}.`;
            if (this.options.invalidIndexPolicy === 'error') {
                throw new MCStructureParseError(message, {
                    path: `structure.block_indices[${firstInvalid.layer}][${firstInvalid.index}]`,
                    code: 'INVALID_PALETTE_INDEX',
                });
            }

            this.warn('INVALID_PALETTE_INDEX', 'structure.block_indices', message);
        }

        /**
         * Convert relative block coordinates into the flat Z-fastest index used
         * by .mcstructure: index = Z + sizeZ * (Y + sizeY * X).
         *
         * @param {number} x
         * @param {number} y
         * @param {number} z
         * @param {{checkBounds?: boolean}} [options]
         * @returns {number}
         */
        coordinatesToIndex(x, y, z, options = {}) {
            if (![x, y, z].every(Number.isInteger)) {
                throw new TypeError('Block coordinates must be integers.');
            }
            if (options.checkBounds !== false && !this.contains(x, y, z)) {
                throw new RangeError(
                    `Coordinates (${x}, ${y}, ${z}) are outside structure bounds 0..${this.size.x - 1}, 0..${this.size.y - 1}, 0..${this.size.z - 1}.`
                );
            }
            return this.size.z * this.size.y * x + this.size.z * y + z;
        }

        /**
         * Convert a flat Z-fastest index into relative block coordinates.
         *
         * @param {number} index
         * @param {{checkBounds?: boolean}} [options]
         * @returns {{x:number, y:number, z:number}}
         */
        indexToCoordinates(index, options = {}) {
            if (!Number.isInteger(index)) throw new TypeError('Flat block index must be an integer.');
            if (options.checkBounds !== false && (index < 0 || index >= this.volume)) {
                throw new RangeError(`Flat block index ${index} is outside 0..${this.volume - 1}.`);
            }

            const yz = this.size.y * this.size.z;
            const x = Math.floor(index / yz);
            const remainder = index - x * yz;
            const y = Math.floor(remainder / this.size.z);
            const z = remainder - y * this.size.z;
            return {x, y, z};
        }

        /** @param {number} x @param {number} y @param {number} z */
        contains(x, y, z) {
            return Number.isInteger(x) && Number.isInteger(y) && Number.isInteger(z)
                && x >= 0 && x < this.size.x
                && y >= 0 && y < this.size.y
                && z >= 0 && z < this.size.z;
        }

        /**
         * Return one block layer cell. A palette index of -1 means structure void
         * / no block placement and therefore returns `block: null`.
         *
         * @param {number} x
         * @param {number} y
         * @param {number} z
         * @param {0|1} [layer]
         */
        getBlock(x, y, z, layer = 0) {
            this.assertLayer(layer);
            const index = this.coordinatesToIndex(x, y, z);
            return this.getBlockByIndex(index, layer);
        }

        /**
         * @param {number} index
         * @param {0|1} [layer]
         */
        getBlockByIndex(index, layer = 0) {
            this.assertLayer(layer);
            const position = this.indexToCoordinates(index);
            const paletteIndex = this.blockIndices[layer][index];
            const validPaletteIndex = paletteIndex >= 0 && paletteIndex < this.blockPalette.length;

            return {
                index,
                layer,
                position,
                paletteIndex,
                isVoid: paletteIndex === -1,
                isInvalid: paletteIndex < -1 || paletteIndex >= this.blockPalette.length,
                block: validPaletteIndex ? this.blockPalette[paletteIndex] : null,
                positionData: this.blockPositionData.get(index) || null,
            };
        }

        /**
         * Return additional data stored for a block position.
         *
         * @param {number} x
         * @param {number} y
         * @param {number} z
         */
        getPositionData(x, y, z) {
            return this.blockPositionData.get(this.coordinatesToIndex(x, y, z)) || null;
        }

        /**
         * Return block entity NBT at a relative coordinate, or null.
         *
         * @param {number} x
         * @param {number} y
         * @param {number} z
         */
        getBlockEntity(x, y, z) {
            return this.getPositionData(x, y, z)?.blockEntityData ?? null;
        }

        /**
         * Return an entity's position from its `Pos` list. Relative positions are
         * calculated by subtracting structure_world_origin from the saved absolute
         * entity position.
         *
         * @param {Record<string, any>} entity
         * @param {{relative?: boolean}} [options]
         * @returns {{x:number, y:number, z:number}|null}
         */
        getEntityPosition(entity, options = {}) {
            if (!entity || !Array.isArray(entity.Pos) || entity.Pos.length < 3) return null;
            const x = Number(entity.Pos[0]);
            const y = Number(entity.Pos[1]);
            const z = Number(entity.Pos[2]);
            if (![x, y, z].every(Number.isFinite)) return null;

            if (options.relative === false) return {x, y, z};
            return {
                x: x - this.worldOrigin.x,
                y: y - this.worldOrigin.y,
                z: z - this.worldOrigin.z,
            };
        }

        /**
         * Iterate blocks without allocating a giant intermediate array.
         *
         * @param {{
         *   layers?: 0|1|'both'|Array<0|1>,
         *   includeVoid?: boolean,
         *   includeAir?: boolean,
         *   airNames?: string[]|Set<string>,
         *   includeInvalid?: boolean
         * }} [options]
         * @returns {Generator<ReturnType<MinecraftBedrockStructure['getBlockByIndex']>>}
         */
        *blocks(options = {}) {
            const layers = this.normalizeLayers(options.layers ?? 0);
            const includeVoid = options.includeVoid === true;
            const includeAir = options.includeAir !== false;
            const includeInvalid = options.includeInvalid === true;
            const airNames = options.airNames instanceof Set
                ? options.airNames
                : new Set(options.airNames || ['minecraft:air', 'minecraft:cave_air', 'minecraft:void_air']);

            for (const layer of layers) {
                const indices = this.blockIndices[layer];
                for (let index = 0; index < indices.length; index++) {
                    const paletteIndex = indices[index];
                    if (paletteIndex === -1 && !includeVoid) continue;
                    if ((paletteIndex < -1 || paletteIndex >= this.blockPalette.length) && !includeInvalid) continue;

                    const cell = this.getBlockByIndex(index, layer);
                    if (!includeAir && cell.block && airNames.has(cell.block.name)) continue;
                    yield cell;
                }
            }
        }

        /**
         * Invoke a callback for every selected block cell.
         * Return `false` from the callback to stop early.
         *
         * @param {(cell: ReturnType<MinecraftBedrockStructure['getBlockByIndex']>, structure: MinecraftBedrockStructure) => void|boolean} callback
         * @param {Parameters<MinecraftBedrockStructure['blocks']>[0]} [options]
         * @returns {number} Number of visited cells.
         */
        forEachBlock(callback, options = {}) {
            if (typeof callback !== 'function') throw new TypeError('forEachBlock expects a callback function.');
            let count = 0;
            for (const cell of this.blocks(options)) {
                count++;
                if (callback(cell, this) === false) break;
            }
            return count;
        }

        /**
         * Find blocks by name, permutation key, state subset, or predicate.
         *
         * @param {string|{name?:string, key?:string, states?:Record<string, any>}|((cell:any)=>boolean)} query
         * @param {Parameters<MinecraftBedrockStructure['blocks']>[0]} [options]
         * @returns {Array<ReturnType<MinecraftBedrockStructure['getBlockByIndex']>>}
         */
        findBlocks(query, options = {}) {
            let predicate;

            if (typeof query === 'function') {
                predicate = query;
            } else if (typeof query === 'string') {
                predicate = cell => cell.block && (cell.block.name === query || cell.block.key === query);
            } else if (isObjectRecord(query)) {
                predicate = cell => {
                    if (!cell.block) return false;
                    if (query.name != null && cell.block.name !== query.name) return false;
                    if (query.key != null && cell.block.key !== query.key) return false;
                    if (query.states != null) {
                        if (!isObjectRecord(query.states)) throw new TypeError('query.states must be an object.');
                        for (const key of Object.keys(query.states)) {
                            if (cell.block.states[key] !== query.states[key]) return false;
                        }
                    }
                    return true;
                };
            } else {
                throw new TypeError('findBlocks expects a block name, query object, or predicate function.');
            }

            const result = [];
            for (const cell of this.blocks(options)) {
                if (predicate(cell)) result.push(cell);
            }
            return result;
        }

        /**
         * Count references to palette entries.
         *
         * @param {{layers?:0|1|'both'|Array<0|1>, includeVoid?:boolean}} [options]
         * @returns {{byPaletteIndex: Map<number, number>, byBlockKey: Map<string, number>, voidCount:number, invalidCount:number}}
         */
        countBlocks(options = {}) {
            const layers = this.normalizeLayers(options.layers ?? 0);
            const includeVoid = options.includeVoid === true;
            const byPaletteIndex = new Map();
            const byBlockKey = new Map();
            let voidCount = 0;
            let invalidCount = 0;

            for (const layer of layers) {
                for (const paletteIndex of this.blockIndices[layer]) {
                    if (paletteIndex === -1) {
                        voidCount++;
                        if (!includeVoid) continue;
                    }
                    if (paletteIndex < -1 || paletteIndex >= this.blockPalette.length) {
                        invalidCount++;
                        continue;
                    }

                    byPaletteIndex.set(paletteIndex, (byPaletteIndex.get(paletteIndex) || 0) + 1);
                    if (paletteIndex >= 0) {
                        const key = this.blockPalette[paletteIndex].key;
                        byBlockKey.set(key, (byBlockKey.get(key) || 0) + 1);
                    }
                }
            }

            return {byPaletteIndex, byBlockKey, voidCount, invalidCount};
        }

        /**
         * Get cube bounds for a Minecraft block in Blockbench model units.
         * By convention one Minecraft block is 16 Blockbench units.
         *
         * `flipZ` can be enabled when the rest of your importer uses the opposite
         * north/south convention. The parser itself does not force a coordinate flip.
         *
         * @param {number} x
         * @param {number} y
         * @param {number} z
         * @param {{scale?:number, origin?:[number,number,number], flipZ?:boolean}} [options]
         * @returns {{from:[number,number,number], to:[number,number,number]}}
         */
        getBlockbenchCubeBounds(x, y, z, options = {}) {
            if (!this.contains(x, y, z)) throw new RangeError(`Coordinates (${x}, ${y}, ${z}) are out of bounds.`);
            const scale = options.scale ?? 16;
            const origin = options.origin || [0, 0, 0];
            const mappedZ = options.flipZ ? this.size.z - 1 - z : z;

            const from = [
                origin[0] + x * scale,
                origin[1] + y * scale,
                origin[2] + mappedZ * scale,
            ];
            return {
                from,
                to: [from[0] + scale, from[1] + scale, from[2] + scale],
            };
        }

        /**
         * Return a compact structure summary useful for logs and diagnostics.
         */
        getSummary() {
            const primary = this.countBlocks({layers: 0, includeVoid: true});
            const secondary = this.countBlocks({layers: 1, includeVoid: true});
            return {
                sourceName: this.options.sourceName,
                formatVersion: this.formatVersion,
                size: {...this.size},
                volume: this.volume,
                worldOrigin: {...this.worldOrigin},
                paletteName: this.paletteName,
                paletteCount: Object.keys(this.palettes).length,
                blockPaletteSize: this.blockPalette.length,
                primaryLayer: {
                    voidCount: primary.voidCount,
                    invalidCount: primary.invalidCount,
                    uniquePermutations: primary.byBlockKey.size,
                },
                secondaryLayer: {
                    voidCount: secondary.voidCount,
                    invalidCount: secondary.invalidCount,
                    uniquePermutations: secondary.byBlockKey.size,
                },
                blockPositionDataCount: this.blockPositionData.size,
                entityCount: this.entities.length,
                warningCount: this.warnings.length,
            };
        }

        /**
         * Return a JSON-safe representation of the parsed source NBT.
         *
         * @param {Parameters<typeof toJSONCompatible>[1]} [options]
         */
        toJSON(options = {}) {
            return toJSONCompatible(this.raw, options);
        }

        /**
         * Serialize the original typed NBT document without semantic changes.
         * For parsed files this is byte-identical, including unknown tags.
         */
        toUint8Array(options = {}) {
            if (!this.nbtDocument) throw new Error('No typed NBT document is available for serialization.');
            return LittleEndianNBTWriter.write(this.nbtDocument, options);
        }

        /** Return a mutable bidirectional editor initialized from this structure. */
        edit(options = {}) {
            return new MinecraftBedrockStructureEditor(this, options);
        }

        /** @param {0|1|'both'|Array<0|1>} layers */
        normalizeLayers(layers) {
            if (layers === 'both') return [0, 1];
            if (layers === 0 || layers === 1) return [layers];
            if (Array.isArray(layers)) {
                const unique = [...new Set(layers)];
                unique.forEach(layer => this.assertLayer(layer));
                return unique;
            }
            throw new TypeError('layers must be 0, 1, "both", or an array containing 0 and/or 1.');
        }

        /** @param {number} layer */
        assertLayer(layer) {
            if (layer !== 0 && layer !== 1) throw new RangeError('Block layer must be 0 or 1.');
        }

        /** @param {unknown} value @param {string} path */
        requireRecord(value, path) {
            if (!isObjectRecord(value)) {
                throw new MCStructureParseError('Expected an NBT compound.', {
                    path,
                    code: 'EXPECTED_COMPOUND',
                });
            }
            return value;
        }

        /** @param {unknown} value @param {string} path */
        requireList(value, path) {
            if (!Array.isArray(value) && !(ArrayBuffer.isView(value) && !(value instanceof DataView))) {
                throw new MCStructureParseError('Expected an NBT list.', {
                    path,
                    code: 'EXPECTED_LIST',
                });
            }
            return value;
        }

        /** @param {unknown} value @param {number} length @param {string} path */
        requireNumberList(value, length, path) {
            const list = this.requireList(value, path);
            if (list.length !== length || !list.every(Number.isFinite)) {
                throw new MCStructureParseError(`Expected a list of exactly ${length} finite numbers.`, {
                    path,
                    code: 'INVALID_NUMBER_LIST',
                });
            }
            return list;
        }

        /** @param {unknown} value @param {number} length @param {string} path */
        requireIntegerList(value, length, path) {
            const list = this.requireList(value, path);
            if (list.length !== length || !list.every(Number.isSafeInteger)) {
                throw new MCStructureParseError(`Expected a list of exactly ${length} safe integers.`, {
                    path,
                    code: 'INVALID_INTEGER_LIST',
                });
            }
            return list;
        }

        /** @param {unknown} value @param {string} path */
        requireInteger(value, path) {
            if (!Number.isInteger(value)) {
                throw new MCStructureParseError('Expected an integer.', {
                    path,
                    code: 'EXPECTED_INTEGER',
                });
            }
            return value;
        }

        /** @param {unknown} value @param {string} path */
        requireString(value, path) {
            if (typeof value !== 'string') {
                throw new MCStructureParseError('Expected a string.', {
                    path,
                    code: 'EXPECTED_STRING',
                });
            }
            return value;
        }

        /** @param {string} code @param {string} path @param {string} message */
        warn(code, path, message) {
            const warning = Object.freeze({code, path, message});
            this.warnings.push(warning);
            return warning;
        }
    }

    /** Set or replace a named child in a typed TAG_Compound node. */
    function setCompoundTag(compoundNode, name, childNode) {
        if (!isNBTNode(compoundNode) || compoundNode.type !== NBT_TAG.Compound) {
            throw new TypeError('setCompoundTag expects a TAG_Compound node.');
        }
        const child = isNBTNode(childNode) ? cloneNBT(childNode) : inferNBTNode(childNode, {path: `$.${name}`});
        child.name = String(name);
        compoundNode.value[name] = child;
        return child;
    }

    /** Get a named typed child from a TAG_Compound node. */
    function getCompoundTag(compoundNode, name) {
        return isNBTNode(compoundNode) && compoundNode.type === NBT_TAG.Compound
            ? compoundNode.value[name] || null
            : null;
    }

    /** Delete a named child from a TAG_Compound node. */
    function deleteCompoundTag(compoundNode, name) {
        if (!isNBTNode(compoundNode) || compoundNode.type !== NBT_TAG.Compound) return false;
        return delete compoundNode.value[name];
    }

    /** Return an NBT compound node from either a typed node or plain object. */
    function normalizeCompoundNode(value, path = '$') {
        const node = isNBTNode(value) ? cloneNBT(value) : NBT.compound(value);
        if (node.type !== NBT_TAG.Compound) {
            throw new NBTWriteError('Expected a TAG_Compound value.', {path, code: 'EXPECTED_COMPOUND'});
        }
        delete node.name;
        return node;
    }

    /** Convert block-state data to a typed compound while retaining old widths where possible. */
    function buildBlockStatesNode(entry) {
        const states = isObjectRecord(entry.states) ? entry.states : createDictionary();
        const result = entry._statesTemplate
            ? cloneNBT(entry._statesTemplate)
            : NBT.compound();
        result.type = NBT_TAG.Compound;
        result.typeName = NBT_TAG_NAME[NBT_TAG.Compound];
        result.value = isObjectRecord(result.value) ? result.value : createDictionary();

        for (const key of Object.keys(result.value)) {
            if (!Object.prototype.hasOwnProperty.call(states, key)) delete result.value[key];
        }
        for (const key of Object.keys(states)) {
            const value = states[key];
            const existing = result.value[key];
            let child = existing ? cloneNBT(existing) : null;

            if (child) {
                const compatible = (
                    child.type === NBT_TAG.Byte && Number.isInteger(value) && value >= -128 && value <= 127
                ) || (
                    child.type === NBT_TAG.Short && Number.isInteger(value) && value >= -32768 && value <= 32767
                ) || (
                    child.type === NBT_TAG.Int && Number.isInteger(value) && value >= -2147483648 && value <= 2147483647
                ) || (
                    child.type === NBT_TAG.Long && (typeof value === 'bigint' || Number.isSafeInteger(value) || typeof value === 'string')
                ) || (
                    (child.type === NBT_TAG.Float || child.type === NBT_TAG.Double) && typeof value === 'number' && Number.isFinite(value)
                ) || (
                    child.type === NBT_TAG.String && typeof value === 'string'
                );
                if (!compatible) child = null;
            }

            if (!child) {
                if (typeof value === 'boolean') child = NBT.byte(value ? 1 : 0);
                else if (typeof value === 'bigint') child = NBT.long(value);
                else if (Number.isInteger(value)) child = NBT.int(value);
                else if (typeof value === 'number') child = NBT.double(value);
                else if (typeof value === 'string') child = NBT.string(value);
                else throw new TypeError(`Unsupported block state ${JSON.stringify(key)} value.`);
            } else {
                child.value = child.type === NBT_TAG.Long && typeof value !== 'bigint' ? BigInt(value) : value;
            }
            child.name = key;
            result.value[key] = child;
        }
        return result;
    }

    /**
     * Mutable, bidirectional editor for Minecraft Bedrock .mcstructure files.
     *
     * The editor keeps exact typed NBT templates for existing values, so unknown
     * extension tags and narrow numeric types survive export. High-level methods
     * update blocks, palettes, block entities, scheduled ticks, entities, size,
     * and world origin without forcing callers to manually rebuild NBT.
     */
    class MinecraftBedrockStructureEditor {
        /**
         * @param {MinecraftBedrockStructure|ArrayBuffer|ArrayBufferView} source
         * @param {{palette?:string, defaultBlockVersion?:number, sourceName?:string}} [options]
         */
        constructor(source, options = {}) {
            if (!(source instanceof MinecraftBedrockStructure)) {
                source = MinecraftBedrockStructure.parse(source, options);
            }
            if (!source.nbtDocument) {
                throw new TypeError('The source structure does not contain a typed NBT document.');
            }

            this.sourceName = options.sourceName || source.options.sourceName || null;
            this.rootName = source.nbtDocument.name || '';
            this.templateDocument = cloneNBT(source.nbtDocument);
            this.formatVersion = source.formatVersion;
            this.size = {...source.size};
            this.worldOrigin = {...source.worldOrigin};
            this.blockIndices = source.blockIndices.map(layer => new Int32Array(layer));
            this.paletteName = options.palette || source.paletteName;
            this.defaultBlockVersion = options.defaultBlockVersion
                ?? source.blockPalette[0]?.version
                ?? 18168865; // A known-valid 1.21.60.33 fallback for newly created files.
            this.palettes = new Map();

            const rootTag = this.templateDocument;
            const structureTag = getCompoundTag(rootTag, 'structure');
            const paletteContainerTag = getCompoundTag(structureTag, 'palette');

            for (const paletteName of Object.keys(source.palettes)) {
                const semanticPalette = source.palettes[paletteName];
                const typedPalette = getCompoundTag(paletteContainerTag, paletteName);
                const typedBlockList = getCompoundTag(typedPalette, 'block_palette');
                const typedPositionData = getCompoundTag(typedPalette, 'block_position_data');

                const blockPalette = semanticPalette.blockPalette.map((entry, index) => {
                    const template = typedBlockList?.value?.items?.[index]
                        ? cloneNBT(typedBlockList.value.items[index])
                        : NBT.compound();
                    const statesTemplate = getCompoundTag(template, 'states') || NBT.compound();
                    return {
                        name: entry.name,
                        states: cloneValue(entry.states),
                        version: entry.version,
                        _template: template,
                        _statesTemplate: cloneNBT(statesTemplate),
                    };
                });

                const blockPositionData = new Map();
                if (typedPositionData?.type === NBT_TAG.Compound) {
                    for (const key of Object.keys(typedPositionData.value)) {
                        const index = Number(key);
                        if (Number.isSafeInteger(index) && index >= 0) {
                            const node = cloneNBT(typedPositionData.value[key]);
                            delete node.name;
                            blockPositionData.set(index, node);
                        }
                    }
                }

                const paletteRecord = {
                    name: paletteName,
                    blockPalette,
                    blockPositionData,
                    _template: typedPalette ? cloneNBT(typedPalette) : NBT.compound(),
                    _blockPaletteElementType: typedBlockList?.type === NBT_TAG.List
                        ? typedBlockList.value.elementType
                        : NBT_TAG.Compound,
                };
                this.rebuildPaletteLookup(paletteRecord);
                this.palettes.set(paletteName, paletteRecord);
            }

            const entitiesTag = getCompoundTag(structureTag, 'entities');
            this._entitiesElementType = entitiesTag?.type === NBT_TAG.List
                ? entitiesTag.value.elementType
                : NBT_TAG.Compound;
            this.entities = entitiesTag?.type === NBT_TAG.List
                ? entitiesTag.value.items.map(item => {
                    const node = cloneNBT(item);
                    delete node.name;
                    return node;
                })
                : [];

            if (!this.palettes.has(this.paletteName)) {
                throw new RangeError(`Palette ${JSON.stringify(this.paletteName)} does not exist.`);
            }
        }

        /** Create an editable structure from binary input. */
        static parse(input, options = {}) {
            return new MinecraftBedrockStructureEditor(MinecraftBedrockStructure.parse(input, options), options);
        }

        /** Parse a browser File or Blob into an editor. */
        static async fromBlob(blob, options = {}) {
            if (!blob || typeof blob.arrayBuffer !== 'function') {
                throw new TypeError('fromBlob expects a browser File or Blob.');
            }
            const sourceName = options.sourceName || (typeof blob.name === 'string' ? blob.name : null);
            return MinecraftBedrockStructureEditor.parse(await blob.arrayBuffer(), {...options, sourceName});
        }

        /** Parse the binary content returned by Blockbench.import/read. */
        static fromBlockbenchFile(file, options = {}) {
            if (!file || file.content == null) {
                throw new TypeError('Expected a Blockbench file object containing binary `content`.');
            }
            const sourceName = options.sourceName || file.name || file.path || null;
            return MinecraftBedrockStructureEditor.parse(file.content, {...options, sourceName});
        }

        /**
         * Create a new valid structure. The default primary layer contains air,
         * while the secondary layer is structure void (-1).
         */
        static create(options = {}) {
            const sizeInput = options.size || [1, 1, 1];
            const size = Array.isArray(sizeInput)
                ? {x: sizeInput[0], y: sizeInput[1], z: sizeInput[2]}
                : {x: sizeInput.x, y: sizeInput.y, z: sizeInput.z};
            const originInput = options.worldOrigin || [0, 0, 0];
            const worldOrigin = Array.isArray(originInput)
                ? {x: originInput[0], y: originInput[1], z: originInput[2]}
                : {x: originInput.x, y: originInput.y, z: originInput.z};
            const volume = checkedVolume(size.x, size.y, size.z, options.maxVolume ?? DEFAULT_LIMITS.maxVolume);
            const paletteName = options.palette || 'default';
            const blockVersion = options.blockVersion ?? 18168865;
            const air = {
                name: 'minecraft:air',
                states: createDictionary(),
                version: blockVersion,
            };

            const root = NBT.compound({
                format_version: NBT.int(options.formatVersion ?? 1),
                size: NBT.list(NBT_TAG.Int, [NBT.int(size.x), NBT.int(size.y), NBT.int(size.z)]),
                structure: NBT.compound({
                    block_indices: NBT.list(NBT_TAG.List, [
                        NBT.list(NBT_TAG.Int, Array.from({length: volume}, () => NBT.int(0))),
                        NBT.list(NBT_TAG.Int, Array.from({length: volume}, () => NBT.int(-1))),
                    ]),
                    entities: NBT.list(NBT_TAG.End, []),
                    palette: NBT.compound({
                        [paletteName]: NBT.compound({
                            block_palette: NBT.list(NBT_TAG.Compound, [
                                NBT.compound({
                                    name: NBT.string(air.name),
                                    states: NBT.compound(),
                                    version: NBT.int(blockVersion),
                                }),
                            ]),
                            block_position_data: NBT.compound(),
                        }),
                    }),
                }),
                structure_world_origin: NBT.list(NBT_TAG.Int, [
                    NBT.int(worldOrigin.x), NBT.int(worldOrigin.y), NBT.int(worldOrigin.z),
                ]),
            });
            root.name = options.rootName || '';

            const bytes = LittleEndianNBTWriter.write(root);
            const editor = MinecraftBedrockStructureEditor.parse(bytes, {
                palette: paletteName,
                defaultBlockVersion: blockVersion,
                sourceName: options.sourceName || null,
            });
            if (options.fillPrimary === null || options.fillPrimary === -1) editor.blockIndices[0].fill(-1);
            else if (options.fillPrimary && options.fillPrimary !== 'minecraft:air') {
                editor.fill({x: 0, y: 0, z: 0}, {x: size.x - 1, y: size.y - 1, z: size.z - 1}, options.fillPrimary);
            }
            return editor;
        }

        get volume() {
            return checkedVolume(this.size.x, this.size.y, this.size.z, DEFAULT_LIMITS.maxVolume);
        }

        get primaryLayer() { return this.blockIndices[0]; }
        get secondaryLayer() { return this.blockIndices[1]; }
        get palette() { return this.requirePalette(this.paletteName); }
        get blockPalette() { return this.palette.blockPalette; }
        get blockPositionData() { return this.palette.blockPositionData; }

        /** Select the active palette used by convenience methods and validation. */
        selectPalette(name) {
            this.requirePalette(name);
            this.paletteName = name;
            return this;
        }

        /** Add another palette, optionally cloned from an existing palette. */
        addPalette(name, options = {}) {
            if (typeof name !== 'string' || !name) throw new TypeError('Palette name must be a non-empty string.');
            if (this.palettes.has(name)) throw new RangeError(`Palette ${JSON.stringify(name)} already exists.`);
            const cloneFrom = options.cloneFrom === false ? null : (options.cloneFrom || this.paletteName);
            if (cloneFrom) {
                const source = this.requirePalette(cloneFrom);
                const paletteRecord = {
                    name,
                    blockPalette: source.blockPalette.map(entry => ({
                        name: entry.name,
                        states: cloneValue(entry.states),
                        version: entry.version,
                        _template: cloneNBT(entry._template),
                        _statesTemplate: cloneNBT(entry._statesTemplate),
                    })),
                    blockPositionData: new Map(Array.from(source.blockPositionData, ([index, node]) => [index, cloneNBT(node)])),
                    _template: cloneNBT(source._template),
                    _blockPaletteElementType: source._blockPaletteElementType,
                };
                this.rebuildPaletteLookup(paletteRecord);
                this.palettes.set(name, paletteRecord);
            } else {
                // block_indices are shared by every palette, so an actually empty
                // alternate palette would immediately make every referenced index
                // invalid. `cloneFrom: false` means "start without palette-specific
                // metadata", not "break the shared index table": seed compatible
                // block entries from the active palette while leaving position NBT
                // and the palette compound itself fresh.
                const source = this.requirePalette(this.paletteName);
                const paletteRecord = {
                    name,
                    blockPalette: source.blockPalette.map(entry => ({
                        name: entry.name,
                        states: cloneValue(entry.states),
                        version: entry.version,
                        _template: NBT.compound(),
                        _statesTemplate: NBT.compound(cloneValue(entry.states || createDictionary())),
                    })),
                    blockPositionData: new Map(),
                    _template: NBT.compound(),
                    _blockPaletteElementType: NBT_TAG.Compound,
                };
                this.rebuildPaletteLookup(paletteRecord);
                this.palettes.set(name, paletteRecord);
            }
            return this.palettes.get(name);
        }

        /** Remove a palette. At least one palette must remain. */
        removePalette(name) {
            if (!this.palettes.has(name)) return false;
            if (this.palettes.size === 1) throw new RangeError('A structure must retain at least one palette.');
            this.palettes.delete(name);
            if (this.paletteName === name) this.paletteName = this.palettes.keys().next().value;
            return true;
        }

        /** Return a palette by name or throw a useful error. */
        requirePalette(name = this.paletteName) {
            const palette = this.palettes.get(name);
            if (!palette) throw new RangeError(`Palette ${JSON.stringify(name)} does not exist.`);
            return palette;
        }

        /** Rebuild O(1) lookup tables after a palette mutation. */
        rebuildPaletteLookup(palette) {
            palette._keyToIndex = new Map();
            palette._nameToIndex = new Map();
            for (let index = 0; index < palette.blockPalette.length; index++) {
                const entry = palette.blockPalette[index];
                const key = palettePermutationKey(entry);
                if (!palette._keyToIndex.has(key)) palette._keyToIndex.set(key, index);
                if (!palette._nameToIndex.has(entry.name)) palette._nameToIndex.set(entry.name, index);
            }
            return palette;
        }

        /** Convert relative coordinates to Bedrock's Z-fastest flat index. */
        coordinatesToIndex(x, y, z, options = {}) {
            if (![x, y, z].every(Number.isInteger)) throw new TypeError('Block coordinates must be integers.');
            if (options.checkBounds !== false && !this.contains(x, y, z)) {
                throw new RangeError(`Coordinates (${x}, ${y}, ${z}) are outside the structure.`);
            }
            return this.size.z * this.size.y * x + this.size.z * y + z;
        }

        /** Convert a flat index to relative coordinates. */
        indexToCoordinates(index, options = {}) {
            if (!Number.isInteger(index)) throw new TypeError('Flat block index must be an integer.');
            if (options.checkBounds !== false && (index < 0 || index >= this.volume)) {
                throw new RangeError(`Flat block index ${index} is outside 0..${this.volume - 1}.`);
            }
            const yz = this.size.y * this.size.z;
            const x = Math.floor(index / yz);
            const remainder = index - x * yz;
            const y = Math.floor(remainder / this.size.z);
            return {x, y, z: remainder - y * this.size.z};
        }

        contains(x, y, z) {
            return Number.isInteger(x) && Number.isInteger(y) && Number.isInteger(z)
                && x >= 0 && x < this.size.x
                && y >= 0 && y < this.size.y
                && z >= 0 && z < this.size.z;
        }

        /** Return one editable block cell. */
        getBlock(x, y, z, options = {}) {
            const layer = options.layer ?? 0;
            this.assertLayer(layer);
            const index = this.coordinatesToIndex(x, y, z);
            const paletteIndex = this.blockIndices[layer][index];
            const palette = this.requirePalette(options.palette || this.paletteName);
            return {
                index,
                position: {x, y, z},
                layer,
                paletteIndex,
                block: paletteIndex >= 0 && paletteIndex < palette.blockPalette.length
                    ? palette.blockPalette[paletteIndex]
                    : null,
            };
        }

        /** Find an existing block permutation in a palette. */
        findPaletteIndex(block, paletteName = this.paletteName) {
            const palette = this.requirePalette(paletteName);
            if (!palette._keyToIndex || !palette._nameToIndex) this.rebuildPaletteLookup(palette);
            if (typeof block === 'string') return palette._nameToIndex.get(block) ?? -1;
            if (!block || typeof block.name !== 'string') return -1;
            if (Number.isInteger(block.version)) {
                const key = palettePermutationKey({
                    name: block.name,
                    states: block.states || createDictionary(),
                    version: block.version,
                });
                return palette._keyToIndex.get(key) ?? -1;
            }
            // Preserve the historical API when callers omit version: select the
            // first name/state match regardless of packed version.
            const stateKey = blockPermutationKey({name: block.name, states: block.states || createDictionary()});
            return palette.blockPalette.findIndex(entry => blockPermutationKey(entry) === stateKey);
        }

        /** Add a block permutation or return its existing palette index. */
        ensureBlockPermutation(block, options = {}) {
            if (!block || typeof block.name !== 'string' || !block.name) {
                throw new TypeError('A block permutation requires a non-empty `name`.');
            }
            const palette = this.requirePalette(options.palette || this.paletteName);
            const normalized = {
                name: block.name,
                states: isObjectRecord(block.states) ? cloneValue(block.states) : createDictionary(),
                version: block.version ?? options.version ?? this.defaultBlockVersion,
            };
            if (!Number.isInteger(normalized.version)) throw new TypeError('Block version must be an integer.');
            const existing = this.findPaletteIndex(normalized, palette.name);
            if (existing >= 0) {
                // block_indices are shared by all palettes. If a malformed or
                // externally-edited alternate palette is shorter, an early return
                // here would let a subsequently referenced index become invalid in
                // that palette. Repair only the missing slots and preserve every
                // alternate entry that already exists.
                for (const candidate of this.palettes.values()) {
                    let changed = false;
                    while (candidate.blockPalette.length <= existing) {
                        const source = palette.blockPalette[candidate.blockPalette.length] || normalized;
                        candidate.blockPalette.push({
                            name: source.name,
                            states: cloneValue(source.states || createDictionary()),
                            version: source.version ?? normalized.version,
                            _template: source._template ? cloneNBT(source._template) : NBT.compound(),
                            _statesTemplate: source._statesTemplate
                                ? cloneNBT(source._statesTemplate)
                                : NBT.compound(source.states || createDictionary()),
                        });
                        changed = true;
                    }
                    if (changed) this.rebuildPaletteLookup(candidate);
                }
                return existing;
            }

            const statesNode = isNBTNode(block.statesNBT)
                ? normalizeCompoundNode(block.statesNBT, '$.statesNBT')
                : NBT.compound(normalized.states);
            // block_indices are shared by every palette in an .mcstructure.
            // Appending to only the active palette would make the same numeric
            // index invalid for every alternate palette. Keep palette lengths
            // aligned by appending the new permutation to all palettes. Alternate
            // palettes can still customize the entry afterwards with
            // updateBlockPermutation().
            const index = Math.max(...Array.from(this.palettes.values(), candidate => candidate.blockPalette.length));
            for (const candidate of this.palettes.values()) {
                while (candidate.blockPalette.length < index) {
                    const fallback = palette.blockPalette[candidate.blockPalette.length] || normalized;
                    candidate.blockPalette.push({
                        name: fallback.name,
                        states: cloneValue(fallback.states || createDictionary()),
                        version: fallback.version ?? normalized.version,
                        _template: NBT.compound(),
                        _statesTemplate: NBT.compound(fallback.states || createDictionary()),
                    });
                }
                candidate.blockPalette.push({
                    ...normalized,
                    states: cloneValue(normalized.states),
                    _template: NBT.compound(),
                    _statesTemplate: candidate === palette ? cloneNBT(statesNode) : NBT.compound(normalized.states),
                });
                this.rebuildPaletteLookup(candidate);
            }
            return index;
        }

        /** Resolve a palette index, block name, block descriptor, null, or -1. */
        resolvePaletteIndex(block, options = {}) {
            const palette = this.requirePalette(options.palette || this.paletteName);
            if (block == null || block === -1) return -1;
            if (Number.isInteger(block)) {
                if (block < -1 || block >= palette.blockPalette.length) {
                    throw new RangeError(`Palette index ${block} is invalid for palette ${JSON.stringify(palette.name)}.`);
                }
                return block;
            }
            if (typeof block === 'string') {
                const existing = this.findPaletteIndex(block, palette.name);
                if (existing >= 0) return existing;
                return this.ensureBlockPermutation({name: block, states: createDictionary()}, {palette: palette.name});
            }
            if (isObjectRecord(block)) return this.ensureBlockPermutation(block, {palette: palette.name});
            throw new TypeError('Block must be a palette index, block name, descriptor object, null, or -1.');
        }

        /** Set one block in either the primary or secondary layer. */
        setBlock(x, y, z, block, options = {}) {
            const layer = options.layer ?? 0;
            this.assertLayer(layer);
            const index = this.coordinatesToIndex(x, y, z);
            const paletteIndex = this.resolvePaletteIndex(block, options);
            this.blockIndices[layer][index] = paletteIndex;
            return this.getBlock(x, y, z, options);
        }

        /** Set a flat block index directly. */
        setBlockByIndex(index, block, options = {}) {
            const position = this.indexToCoordinates(index);
            return this.setBlock(position.x, position.y, position.z, block, options);
        }

        /** Fill an inclusive cuboid with one block permutation. */
        fill(from, to, block, options = {}) {
            const layer = options.layer ?? 0;
            this.assertLayer(layer);
            const min = {
                x: Math.min(from.x, to.x), y: Math.min(from.y, to.y), z: Math.min(from.z, to.z),
            };
            const max = {
                x: Math.max(from.x, to.x), y: Math.max(from.y, to.y), z: Math.max(from.z, to.z),
            };
            if (!this.contains(min.x, min.y, min.z) || !this.contains(max.x, max.y, max.z)) {
                throw new RangeError('Fill bounds are outside the structure.');
            }
            const paletteIndex = this.resolvePaletteIndex(block, options);
            let changed = 0;
            for (let x = min.x; x <= max.x; x++) {
                for (let y = min.y; y <= max.y; y++) {
                    for (let z = min.z; z <= max.z; z++) {
                        this.blockIndices[layer][this.coordinatesToIndex(x, y, z, {checkBounds: false})] = paletteIndex;
                        changed++;
                    }
                }
            }
            return changed;
        }

        /** Replace every matching block in one or both layers. */
        replaceBlocks(query, replacement, options = {}) {
            const layers = options.layers === 'both' ? [0, 1] : [options.layer ?? 0];
            layers.forEach(layer => this.assertLayer(layer));
            const palette = this.requirePalette(options.palette || this.paletteName);
            const replacementIndex = this.resolvePaletteIndex(replacement, options);
            let changed = 0;

            for (const layer of layers) {
                const values = this.blockIndices[layer];
                for (let index = 0; index < values.length; index++) {
                    const paletteIndex = values[index];
                    const block = paletteIndex >= 0 && paletteIndex < palette.blockPalette.length
                        ? palette.blockPalette[paletteIndex]
                        : null;
                    const cell = {index, position: this.indexToCoordinates(index, {checkBounds: false}), layer, paletteIndex, block};
                    let matches = false;
                    if (typeof query === 'function') matches = Boolean(query(cell));
                    else if (query == null || query === -1) matches = paletteIndex === -1;
                    else if (Number.isInteger(query)) matches = paletteIndex === query;
                    else if (typeof query === 'string') matches = Boolean(block && block.name === query);
                    else if (isObjectRecord(query)) {
                        matches = Boolean(block);
                        if (matches && query.name != null) matches = block.name === query.name;
                        if (matches && query.states != null) {
                            for (const key of Object.keys(query.states)) {
                                if (block.states[key] !== query.states[key]) { matches = false; break; }
                            }
                        }
                    }
                    if (matches) {
                        values[index] = replacementIndex;
                        changed++;
                    }
                }
            }
            return changed;
        }

        /** Update an existing palette entry without changing block indices. */
        updateBlockPermutation(index, patch, options = {}) {
            const palette = this.requirePalette(options.palette || this.paletteName);
            if (!Number.isInteger(index) || index < 0 || index >= palette.blockPalette.length) {
                throw new RangeError(`Palette entry ${index} does not exist.`);
            }
            const entry = palette.blockPalette[index];
            if (patch.name != null) {
                if (typeof patch.name !== 'string' || !patch.name) throw new TypeError('Block name must be non-empty.');
                entry.name = patch.name;
            }
            if (patch.states != null) {
                if (!isObjectRecord(patch.states)) throw new TypeError('Block states must be an object.');
                entry.states = cloneValue(patch.states);
                if (patch.statesNBT) entry._statesTemplate = normalizeCompoundNode(patch.statesNBT);
            }
            if (patch.version != null) {
                if (!Number.isInteger(patch.version)) throw new TypeError('Block version must be an integer.');
                entry.version = patch.version;
            }
            this.rebuildPaletteLookup(palette);
            return entry;
        }

        /** Remove unused and duplicate palette entries, remapping both layers. */
        compactPalette(options = {}) {
            const palette = this.requirePalette(options.palette || this.paletteName);
            const used = new Set();
            for (const layer of this.blockIndices) for (const value of layer) if (value >= 0) used.add(value);

            const palettes = Array.from(this.palettes.values());
            const paletteLength = Math.max(0, ...palettes.map(candidate => candidate.blockPalette.length));
            const remap = new Int32Array(paletteLength);
            remap.fill(-1);
            const keyToIndex = new Map();
            const retainedIndices = [];
            for (let oldIndex = 0; oldIndex < paletteLength; oldIndex++) {
                if (options.keepUnused !== true && !used.has(oldIndex)) continue;
                const entries = palettes.map(candidate => candidate.blockPalette[oldIndex] || null);
                if (used.has(oldIndex) && entries.some(entry => !entry)) {
                    throw new RangeError(`Referenced palette index ${oldIndex} is missing from one or more palettes.`);
                }
                // A numeric block index addresses the same slot in every palette.
                // Two slots are safe to deduplicate only when *all* palettes agree;
                // comparing only the active palette corrupts alternate-palette
                // semantics after the shared block_indices array is remapped.
                const key = entries.map(entry => entry ? palettePermutationKey(entry) : '<missing>').join('\u0000');
                let newIndex = keyToIndex.get(key);
                if (newIndex == null || options.dedupe === false) {
                    newIndex = retainedIndices.length;
                    retainedIndices.push(oldIndex);
                    if (options.dedupe !== false) keyToIndex.set(key, newIndex);
                }
                remap[oldIndex] = newIndex;
            }
            for (const layer of this.blockIndices) {
                for (let i = 0; i < layer.length; i++) {
                    if (layer[i] >= 0) layer[i] = remap[layer[i]];
                }
            }
            for (const candidate of palettes) {
                candidate.blockPalette = retainedIndices.map(index => candidate.blockPalette[index]);
                this.rebuildPaletteLookup(candidate);
            }
            return {
                remap,
                removed: remap.length - retainedIndices.length,
                paletteSize: palette.blockPalette.length,
            };
        }

        /** Change the stored world origin. */
        setWorldOrigin(x, y, z) {
            if (![x, y, z].every(Number.isSafeInteger)) throw new TypeError('World origin values must be safe integers.');
            if (![x, y, z].every(value => value >= NBT_INT_MIN && value <= NBT_INT_MAX)) {
                throw new RangeError('World origin values must fit in signed 32-bit NBT integers.');
            }
            this.worldOrigin = {x, y, z};
            return this;
        }

        /**
         * Resize the structure. `offset` maps old (0,0,0) to the supplied new
         * coordinate, enabling crop, padding, and translation in one operation.
         */
        resize(size, options = {}) {
            const next = Array.isArray(size)
                ? {x: size[0], y: size[1], z: size[2]}
                : {x: size.x, y: size.y, z: size.z};
            const nextVolume = checkedVolume(next.x, next.y, next.z, options.maxVolume ?? DEFAULT_LIMITS.maxVolume);
            const offset = options.offset || {x: 0, y: 0, z: 0};
            const dx = Array.isArray(offset) ? offset[0] : offset.x;
            const dy = Array.isArray(offset) ? offset[1] : offset.y;
            const dz = Array.isArray(offset) ? offset[2] : offset.z;
            if (![dx, dy, dz].every(Number.isInteger)) throw new TypeError('Resize offset values must be integers.');

            const fillPrimary = this.resolvePaletteIndex(options.fillPrimary ?? -1, options);
            const fillSecondary = this.resolvePaletteIndex(options.fillSecondary ?? -1, options);
            const layers = [new Int32Array(nextVolume), new Int32Array(nextVolume)];
            layers[0].fill(fillPrimary);
            layers[1].fill(fillSecondary);

            const oldSize = this.size;
            const oldLayers = this.blockIndices;
            const oldIndex = (x, y, z) => oldSize.z * oldSize.y * x + oldSize.z * y + z;
            const newIndex = (x, y, z) => next.z * next.y * x + next.z * y + z;
            for (let x = 0; x < oldSize.x; x++) {
                for (let y = 0; y < oldSize.y; y++) {
                    for (let z = 0; z < oldSize.z; z++) {
                        const nx = x + dx, ny = y + dy, nz = z + dz;
                        if (nx < 0 || ny < 0 || nz < 0 || nx >= next.x || ny >= next.y || nz >= next.z) continue;
                        const sourceIndex = oldIndex(x, y, z);
                        const targetIndex = newIndex(nx, ny, nz);
                        layers[0][targetIndex] = oldLayers[0][sourceIndex];
                        layers[1][targetIndex] = oldLayers[1][sourceIndex];
                    }
                }
            }

            for (const palette of this.palettes.values()) {
                const remapped = new Map();
                for (const [index, node] of palette.blockPositionData) {
                    const yz = oldSize.y * oldSize.z;
                    const x = Math.floor(index / yz);
                    const remainder = index - x * yz;
                    const y = Math.floor(remainder / oldSize.z);
                    const z = remainder - y * oldSize.z;
                    const nx = x + dx, ny = y + dy, nz = z + dz;
                    if (nx < 0 || ny < 0 || nz < 0 || nx >= next.x || ny >= next.y || nz >= next.z) continue;
                    remapped.set(newIndex(nx, ny, nz), node);
                }
                palette.blockPositionData = remapped;
            }

            this.size = next;
            this.blockIndices = layers;
            return this;
        }

        /** Get raw per-position data as typed NBT or a plain object. */
        getBlockPositionData(x, y, z, options = {}) {
            const index = this.coordinatesToIndex(x, y, z);
            const node = this.requirePalette(options.palette || this.paletteName).blockPositionData.get(index);
            if (!node) return null;
            return options.typed === true ? cloneNBT(node) : unwrapNBTNode(node);
        }

        /** Set or remove all data associated with one block position. */
        setBlockPositionData(x, y, z, data, options = {}) {
            const index = this.coordinatesToIndex(x, y, z);
            const map = this.requirePalette(options.palette || this.paletteName).blockPositionData;
            if (data == null) map.delete(index);
            else map.set(index, normalizeCompoundNode(data, `block_position_data.${index}`));
            return this;
        }

        /** Set only `block_entity_data`, preserving scheduled ticks. */
        setBlockEntity(x, y, z, data, options = {}) {
            const index = this.coordinatesToIndex(x, y, z);
            const palette = this.requirePalette(options.palette || this.paletteName);
            const positionNode = palette.blockPositionData.get(index) || NBT.compound();
            if (data == null) deleteCompoundTag(positionNode, 'block_entity_data');
            else setCompoundTag(positionNode, 'block_entity_data', normalizeCompoundNode(data, '$.block_entity_data'));
            if (Object.keys(positionNode.value).length === 0) palette.blockPositionData.delete(index);
            else palette.blockPositionData.set(index, positionNode);
            return this;
        }

        /** Get only the block entity payload for one coordinate. */
        getBlockEntity(x, y, z, options = {}) {
            const positionNode = this.requirePalette(options.palette || this.paletteName)
                .blockPositionData.get(this.coordinatesToIndex(x, y, z));
            const node = getCompoundTag(positionNode, 'block_entity_data');
            if (!node) return null;
            return options.typed === true ? cloneNBT(node) : unwrapNBTNode(node);
        }

        /** Set the scheduled tick queue for one coordinate. */
        setScheduledTicks(x, y, z, ticks, options = {}) {
            const index = this.coordinatesToIndex(x, y, z);
            const palette = this.requirePalette(options.palette || this.paletteName);
            const positionNode = palette.blockPositionData.get(index) || NBT.compound();
            if (ticks == null) {
                deleteCompoundTag(positionNode, 'tick_queue_data');
            } else {
                let list;
                if (isNBTNode(ticks)) {
                    list = cloneNBT(ticks);
                    if (list.type !== NBT_TAG.List) throw new TypeError('Scheduled ticks must be a TAG_List.');
                } else {
                    if (!Array.isArray(ticks)) throw new TypeError('Scheduled ticks must be an array.');
                    list = NBT.list(NBT_TAG.Compound, ticks.map(tick => normalizeCompoundNode(tick)));
                }
                setCompoundTag(positionNode, 'tick_queue_data', list);
            }
            if (Object.keys(positionNode.value).length === 0) palette.blockPositionData.delete(index);
            else palette.blockPositionData.set(index, positionNode);
            return this;
        }

        /** Return a copy of all structure entities. */
        getEntities(options = {}) {
            return this.entities.map(node => options.typed === true ? cloneNBT(node) : unwrapNBTNode(node));
        }

        /** Add an entity compound and return its index. */
        addEntity(entity) {
            const node = normalizeCompoundNode(entity, '$.entities[]');
            this.entities.push(node);
            return this.entities.length - 1;
        }

        /** Replace an existing entity compound. */
        updateEntity(index, entity) {
            if (!Number.isInteger(index) || index < 0 || index >= this.entities.length) {
                throw new RangeError(`Entity index ${index} does not exist.`);
            }
            this.entities[index] = normalizeCompoundNode(entity, `$.entities[${index}]`);
            return this;
        }

        /** Remove and return an entity. */
        removeEntity(index, options = {}) {
            if (!Number.isInteger(index) || index < 0 || index >= this.entities.length) return null;
            const [node] = this.entities.splice(index, 1);
            return options.typed === true ? node : unwrapNBTNode(node);
        }

        /** Validate the editable model without serializing it. */
        validate() {
            const errors = [];
            const warnings = [];
            let volume = 0;
            try { volume = checkedVolume(this.size.x, this.size.y, this.size.z, DEFAULT_LIMITS.maxVolume); }
            catch (error) { errors.push({code: error.code || 'INVALID_SIZE', message: error.message}); }
            if (!Number.isInteger(this.formatVersion)) errors.push({code: 'INVALID_FORMAT_VERSION', message: 'formatVersion must be an integer.'});
            if (![this.worldOrigin.x, this.worldOrigin.y, this.worldOrigin.z].every(Number.isSafeInteger)) {
                errors.push({code: 'INVALID_WORLD_ORIGIN', message: 'worldOrigin must contain safe integers.'});
            } else if (![this.worldOrigin.x, this.worldOrigin.y, this.worldOrigin.z]
                .every(value => value >= NBT_INT_MIN && value <= NBT_INT_MAX)) {
                errors.push({code: 'INVALID_WORLD_ORIGIN', message: 'worldOrigin must fit in signed 32-bit NBT integers.'});
            }
            if (this.blockIndices.length !== 2 || this.blockIndices.some(layer => layer.length !== volume)) {
                errors.push({code: 'INVALID_LAYER_LENGTH', message: 'Both block layers must match the structure volume.'});
            }
            if (this.palettes.size === 0) errors.push({code: 'NO_PALETTES', message: 'At least one palette is required.'});

            for (const [name, palette] of this.palettes) {
                for (let i = 0; i < palette.blockPalette.length; i++) {
                    const entry = palette.blockPalette[i];
                    if (!entry || typeof entry.name !== 'string' || !entry.name) {
                        errors.push({code: 'INVALID_BLOCK_NAME', message: `Palette ${name} entry ${i} has no valid name.`});
                    }
                    if (!Number.isInteger(entry.version)) {
                        errors.push({code: 'INVALID_BLOCK_VERSION', message: `Palette ${name} entry ${i} has no integer version.`});
                    }
                    if (!isObjectRecord(entry.states)) {
                        errors.push({code: 'INVALID_BLOCK_STATES', message: `Palette ${name} entry ${i} has invalid states.`});
                    }
                }
                for (const [index] of palette.blockPositionData) {
                    if (!Number.isInteger(index) || index < 0 || index >= volume) {
                        errors.push({code: 'POSITION_DATA_OUT_OF_BOUNDS', message: `Palette ${name} position data index ${index} is outside the structure.`});
                    }
                }
                for (let layerIndex = 0; layerIndex < this.blockIndices.length; layerIndex++) {
                    const layer = this.blockIndices[layerIndex];
                    for (let index = 0; index < layer.length; index++) {
                        const value = layer[index];
                        if (value < -1 || value >= palette.blockPalette.length) {
                            errors.push({
                                code: 'INVALID_PALETTE_INDEX',
                                message: `Layer ${layerIndex} index ${index} references ${value}, invalid for palette ${name}.`,
                            });
                            if (errors.length >= 100) break;
                        }
                    }
                    if (errors.length >= 100) break;
                }
            }
            if (this.formatVersion !== 1) warnings.push({code: 'UNKNOWN_FORMAT_VERSION', message: `format_version ${this.formatVersion} may not be supported by Minecraft.`});
            return {valid: errors.length === 0, errors, warnings};
        }

        /** Build a complete typed root document while preserving unknown tags. */
        toNBTDocument(options = {}) {
            const validation = this.validate();
            if (!validation.valid && options.allowInvalid !== true) {
                throw new MCStructureParseError(
                    `Cannot serialize invalid structure: ${validation.errors[0].message}`,
                    {code: validation.errors[0].code, path: '$'}
                );
            }

            // Serialization replaces the huge block-index lists and never mutates
            // retained typed payloads, so sharing them avoids a throwaway clone of
            // the entire source structure before writing.
            const document = cloneNBT(this.templateDocument, {shareTypedArrays: true});
            document.name = options.rootName ?? this.rootName;
            document.type = NBT_TAG.Compound;
            document.typeName = NBT_TAG_NAME[NBT_TAG.Compound];
            if (!isObjectRecord(document.value)) document.value = createDictionary();

            setCompoundTag(document, 'format_version', NBT.int(this.formatVersion));
            setCompoundTag(document, 'size', NBT.list(NBT_TAG.Int, [
                NBT.int(this.size.x), NBT.int(this.size.y), NBT.int(this.size.z),
            ]));
            setCompoundTag(document, 'structure_world_origin', NBT.list(NBT_TAG.Int, [
                NBT.int(this.worldOrigin.x), NBT.int(this.worldOrigin.y), NBT.int(this.worldOrigin.z),
            ]));

            let structureTag = getCompoundTag(document, 'structure');
            if (!structureTag || structureTag.type !== NBT_TAG.Compound) structureTag = NBT.compound();
            else structureTag = cloneNBT(structureTag);

            const blockIndicesTag = createNBTNode(NBT_TAG.List, {
                elementType: NBT_TAG.List,
                elementTypeName: NBT_TAG_NAME[NBT_TAG.List],
                items: [NBT.compactIntList(this.blockIndices[0]), NBT.compactIntList(this.blockIndices[1])],
            }, 'block_indices');
            structureTag.value.block_indices = blockIndicesTag;
            setCompoundTag(structureTag, 'entities', this.entities.length === 0
                ? NBT.list(this._entitiesElementType ?? NBT_TAG.End, [])
                : NBT.list(NBT_TAG.Compound, this.entities));

            const paletteContainer = NBT.compound();
            for (const [paletteName, palette] of this.palettes) {
                let paletteTag = palette._template ? cloneNBT(palette._template) : NBT.compound();
                if (paletteTag.type !== NBT_TAG.Compound) paletteTag = NBT.compound();

                const blockItems = palette.blockPalette.map(entry => {
                    let entryTag = entry._template ? cloneNBT(entry._template) : NBT.compound();
                    if (entryTag.type !== NBT_TAG.Compound) entryTag = NBT.compound();
                    setCompoundTag(entryTag, 'name', NBT.string(entry.name));
                    setCompoundTag(entryTag, 'states', buildBlockStatesNode(entry));
                    setCompoundTag(entryTag, 'version', NBT.int(entry.version));
                    delete entryTag.name;
                    return entryTag;
                });
                setCompoundTag(paletteTag, 'block_palette', blockItems.length === 0
                    ? NBT.list(palette._blockPaletteElementType ?? NBT_TAG.End, [])
                    : NBT.list(NBT_TAG.Compound, blockItems));

                const positionDataTag = NBT.compound();
                const sortedPositionData = Array.from(palette.blockPositionData.entries()).sort((a, b) => a[0] - b[0]);
                for (const [index, node] of sortedPositionData) setCompoundTag(positionDataTag, String(index), node);
                setCompoundTag(paletteTag, 'block_position_data', positionDataTag);
                setCompoundTag(paletteContainer, paletteName, paletteTag);
            }
            setCompoundTag(structureTag, 'palette', paletteContainer);
            setCompoundTag(document, 'structure', structureTag);
            return document;
        }

        /** Serialize to uncompressed little-endian NBT bytes. */
        toUint8Array(options = {}) {
            const writerOptions = {
                initialCapacity: Math.max(1024, Math.min(0x7fffffff, this.volume * 8 + 65536)),
                ...(options.writerOptions || {}),
            };
            const bytes = LittleEndianNBTWriter.write(this.toNBTDocument(options), writerOptions);
            if (options.validateOutput !== false) {
                MinecraftBedrockStructure.parse(bytes, {
                    palette: this.paletteName,
                    strict: true,
                    invalidIndexPolicy: 'error',
                    sourceName: options.sourceName || this.sourceName,
                });
            }
            return bytes;
        }

        /** Serialize to a tightly sized ArrayBuffer. */
        toArrayBuffer(options = {}) {
            const bytes = this.toUint8Array(options);
            return bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength);
        }

        /** Serialize to a browser Blob. */
        toBlob(options = {}) {
            if (typeof Blob === 'undefined') throw new Error('Blob is unavailable in this runtime.');
            return new Blob([this.toUint8Array(options)], {type: 'application/octet-stream'});
        }

        /** Save through Blockbench's native export dialog. */
        exportWithBlockbench(options = {}) {
            if (typeof Blockbench === 'undefined' || typeof Blockbench.export !== 'function') {
                throw new Error('Blockbench.export is unavailable outside Blockbench.');
            }
            const name = (options.name || this.sourceName || 'structure').replace(/\.mcstructure$/i, '');
            const content = this.toArrayBuffer(options);
            return Blockbench.export({
                type: options.type || 'Minecraft Bedrock Structure',
                extensions: ['mcstructure'],
                name,
                content,
                savetype: 'binary',
                custom_writer: options.customWriter,
            }, options.callback);
        }

        /** Trigger a browser download without Blockbench. */
        download(filename = 'structure.mcstructure', options = {}) {
            if (typeof document === 'undefined' || typeof URL === 'undefined') {
                throw new Error('Browser download APIs are unavailable in this runtime.');
            }
            const blob = this.toBlob(options);
            const url = URL.createObjectURL(blob);
            const anchor = document.createElement('a');
            anchor.href = url;
            anchor.download = filename.endsWith('.mcstructure') ? filename : `${filename}.mcstructure`;
            anchor.style.display = 'none';
            document.body.appendChild(anchor);
            anchor.click();
            anchor.remove();
            setTimeout(() => URL.revokeObjectURL(url), 0);
        }

        /** Write directly to disk in Node.js. */
        saveToFile(path, options = {}) {
            if (typeof require !== 'function') throw new Error('saveToFile is only available in Node.js/Blockbench desktop.');
            const fs = require('node:fs');
            fs.writeFileSync(path, Buffer.from(this.toUint8Array(options)));
            return path;
        }

        /** Parse the exported bytes again and return an immutable structure view. */
        build(options = {}) {
            return MinecraftBedrockStructure.parse(this.toUint8Array(options), {
                palette: this.paletteName,
                strict: true,
                invalidIndexPolicy: 'error',
                sourceName: options.sourceName || this.sourceName,
            });
        }

        assertLayer(layer) {
            if (layer !== 0 && layer !== 1) throw new RangeError('Block layer must be 0 or 1.');
        }
    }

    return Object.freeze({
        NBT_TAG,
        NBT_TAG_NAME,
        NBTParseError,
        NBTWriteError,
        MCStructureParseError,
        LittleEndianNBTReader,
        LittleEndianNBTWriter,
        MinecraftBedrockStructure,
        MinecraftBedrockStructureEditor,
        NBT,
        cloneNBT,
        unwrapNBTNode,
        unwrapNBTDocument,
        decodeBlockVersion,
        blockPermutationKey,
        toJSONCompatible,
        toUint8Array,
    });
})();

