        'minecraft:quartz_block', 'minecraft:concrete', 'minecraft:terracotta', 'minecraft:obsidian',
        'minecraft:water', 'minecraft:lava', 'minecraft:torch', 'minecraft:lantern',
        'minecraft:ladder', 'minecraft:rail', 'minecraft:chest', 'minecraft:barrel',
