            if (!clipboard) {
                Blockbench.showQuickMessage(tr('bedrock_structure.message.no_blocks', 'Select at least one structure block.'), 2200);
                return null;
            }
            Blockbench.showQuickMessage(trf('bedrock_structure.message.copied_cells', 'Copied {0} structure cells.', [clipboard.cells.length.toLocaleString()]), 2200);
