                rotation: {label: 'Rotate around Y', type: 'select', value: '0', options: {0: 'No rotation', 1: '90° clockwise', 2: '180°', 3: '90° counter-clockwise'}},
                mirror: {label: 'Mirror', type: 'select', value: '', options: {'': 'No mirror', x: 'Mirror X', z: 'Mirror Z'}},
