    function sourceMaterialsForChunk(mesh) {
        const source = mesh?.userData?.bedrockLightflowSourceMaterials || mesh?.material;
        return Array.isArray(source) ? source : source ? [source] : [];
    }

    function materialIndexAtVertex(geometry, vertexIndex) {
        const group = (geometry?.groups || []).find(entry => (
            vertexIndex >= entry.start && vertexIndex < entry.start + entry.count
        ));
        return Number(group?.materialIndex || 0);
    }

    function markEditableBakeTexture(texture, material) {
        if (!texture) return texture;
        if (material?.userData?.bedrockAtlas) {
            texture.mcstructure_baked_atlas_texture = true;
            texture.userData ||= {};
            texture.userData.bedrockAtlas = true;
        }
        return texture;
    }

    function textureForBakedMaterial(material, cache, createdTextures) {
        const map = material?.map || material?.uniforms?.map?.value || null;
        if (!map || typeof Texture === 'undefined') return null;
        if (cache.has(map)) return markEditableBakeTexture(cache.get(map), material);
        const existing = Texture.all.find(texture => {
            const nativeMaterial = typeof texture.getMaterial === 'function' ? texture.getMaterial() : texture.material;
            const nativeMap = nativeMaterial?.map || nativeMaterial?.uniforms?.map?.value || texture.texture || texture.three_texture;
            return nativeMap === map;
        });
        if (existing) {
            markEditableBakeTexture(existing, material);
            cache.set(map, existing);
            return existing;
        }
        const image = map.image;
        const width = Math.max(1, Number(image?.naturalWidth || image?.videoWidth || image?.width || 0));
        const height = Math.max(1, Number(image?.naturalHeight || image?.videoHeight || image?.height || 0));
        if (!image || typeof document === 'undefined') return null;
        try {
            const canvas = document.createElement('canvas');
            canvas.width = width;
            canvas.height = height;
            const context = canvas.getContext('2d');
            context.imageSmoothingEnabled = false;
            context.drawImage(image, 0, 0, width, height);
            const texture = new Texture({
                name: `${material.userData?.bedrockAtlas ? 'structure_atlas' : 'structure_texture'}_${createdTextures.length + 1}.png`,
                folder: 'bedrock_editable_bake',
                mcstructure_baked_atlas_texture: !!material.userData?.bedrockAtlas,
            });
            texture.fromDataURL(canvas.toDataURL('image/png')).add(false);
            texture.saved = false;
            markEditableBakeTexture(texture, material);
            createdTextures.push(texture);
            cache.set(map, texture);
            return texture;
        } catch (error) {
            warnOnce('bake texture', error);
            cache.set(map, null);
            return null;
        }
    }

    function sourceVerticesMatch(position, uv, left, right, epsilon = 1e-6) {
        if (!position || left == null || right == null) return false;
        if (Math.abs(position.getX(left) - position.getX(right)) > epsilon) return false;
        if (Math.abs(position.getY(left) - position.getY(right)) > epsilon) return false;
        if (Math.abs(position.getZ(left) - position.getZ(right)) > epsilon) return false;
        if (uv) {
            if (Math.abs(uv.getX(left) - uv.getX(right)) > epsilon) return false;
            if (Math.abs(uv.getY(left) - uv.getY(right)) > epsilon) return false;
        }
        return true;
    }

    function sourceQuadIndices(position, uv, vertexStart) {
        if (!position || vertexStart + 5 >= position.count) return null;
        const first = [vertexStart, vertexStart + 1, vertexStart + 2];
        const second = [vertexStart + 3, vertexStart + 4, vertexStart + 5];
        const firstMatches = first.map(sourceIndex => second.some(candidate => sourceVerticesMatch(position, uv, sourceIndex, candidate)));
        const uniqueFirstLocal = firstMatches.findIndex(value => !value);
        if (uniqueFirstLocal < 0 || firstMatches.filter(Boolean).length !== 2) return null;
        const start = first[(uniqueFirstLocal + 2) % 3];
        const uniqueFirst = first[uniqueFirstLocal];
        const otherCommon = first[(uniqueFirstLocal + 1) % 3];
        const uniqueSecond = second.find(sourceIndex => (
            !sourceVerticesMatch(position, uv, sourceIndex, start) &&
            !sourceVerticesMatch(position, uv, sourceIndex, otherCommon)
        ));
        if (uniqueSecond == null) return null;
        const hasStart = second.some(sourceIndex => sourceVerticesMatch(position, uv, sourceIndex, start));
        const hasOther = second.some(sourceIndex => sourceVerticesMatch(position, uv, sourceIndex, otherCommon));
        if (!hasStart || !hasOther) return null;
        return [start, uniqueFirst, otherCommon, uniqueSecond];
    }

    function addedMeshFaceKey(mesh, beforeKeys, addResult) {
        if (Array.isArray(addResult) && addResult.length) return addResult[0];
        if (typeof addResult === 'string') return addResult;
        const after = Object.keys(mesh.faces || {});
        return after.find(key => !beforeKeys.has(key)) || after[after.length - 1] || '';
    }

    function addEditableFaceFromSource(mesh, sourceMesh, sourceIndices, material, textureCache, createdTextures, greedyFaceData, autoTileOverrides) {
        const geometry = sourceMesh.geometry;
        const position = geometry.attributes.position;
        const uv = geometry.attributes.uv;
        const repeat = geometry.getAttribute?.('bedrockGreedyRepeat');
        const tileUv = geometry.getAttribute?.('bedrockTileUv');
        const atlasRect = geometry.getAttribute?.('bedrockAtlasRect');
        const vectors = sourceIndices.map(sourceIndex => [
            position.getX(sourceIndex),
            position.getY(sourceIndex),
            position.getZ(sourceIndex),
        ]);
        const vertexKeys = mesh.addVertices(...vectors);
        const texture = textureForBakedMaterial(material, textureCache, createdTextures);
        const faceUv = {};
        const textureWidth = Math.max(1, Number(texture?.getUVWidth?.() || texture?.width || material?.map?.image?.width || 16));
        const textureHeight = Math.max(1, Number(texture?.getUVHeight?.() || texture?.display_height || material?.map?.image?.height || 16));
        vertexKeys.forEach((key, offset) => {
            const sourceIndex = sourceIndices[offset];
            faceUv[key] = uv
                ? [uv.getX(sourceIndex) * textureWidth, (1 - uv.getY(sourceIndex)) * textureHeight]
                : [0,0];
        });
        const beforeKeys = new Set(Object.keys(mesh.faces || {}));
        const addResult = mesh.addFaces(new MeshFace(mesh, {
            vertices: vertexKeys,
            uv: faceUv,
            texture: texture?.uuid || false,
        }));
        const faceKey = addedMeshFaceKey(mesh, beforeKeys, addResult);
        const greedy = !!(
            faceKey && repeat && sourceIndices.length >= 3 &&
            sourceIndices.every(sourceIndex => Number(repeat.getX(sourceIndex)) > 0.5)
        );
        if (greedy) {
            autoTileOverrides[faceKey] = true;
            const tiles = tileUv
                ? sourceIndices.flatMap(sourceIndex => [tileUv.getX(sourceIndex), tileUv.getY(sourceIndex)])
                : [];
            const first = sourceIndices[0];
            const rect = atlasRect
                ? [
                    atlasRect.getX(first), atlasRect.getY(first),
                    atlasRect.getZ(first), atlasRect.getW(first)
                ]
                : null;
            greedyFaceData[faceKey] = {t: tiles, r: rect};
        }
        return {faceKey, greedy};
    }

    function chunkToEditableMesh(sourceMesh, ownerFilter, textureCache, createdTextures) {
        if (typeof Mesh === 'undefined' || typeof MeshFace === 'undefined') return null;
        const geometry = sourceMesh?.geometry;
        const position = geometry?.attributes?.position;
        const uv = geometry?.attributes?.uv;
        if (!position || position.count < 3) return null;
        const owners = sourceMesh.userData?.triangleOwners || [];
        const materials = sourceMaterialsForChunk(sourceMesh);
        const renderLayer = sourceMesh.userData?.bedrockRenderLayer || 'solid';
        const mesh = new Mesh({
            name: `${RENDER_LAYER_DEFINITIONS[renderLayer]?.name || renderLayer} · ${sourceMesh.userData?.chunkId || 'chunk'}`,
            vertices: {},
            faces: {},
            origin: [0,0,0],
            rotation: [0,0,0],
            shading: 'flat',
            mcstructure_baked_mesh: true,
            mcstructure_greedy_face_data_json: '',
        });
        const greedyFaceData = Object.create(null);
        const autoTileOverrides = Object.create(null);
        let faceCount = 0;
        let greedyFaceCount = 0;
        const groups = Array.isArray(geometry.groups) && geometry.groups.length
            ? geometry.groups
            : [{start: 0, count: position.count, materialIndex: 0}];

        for (const group of groups) {
            const start = Math.max(0, Number(group.start) || 0);
            const end = Math.min(position.count, start + Math.max(0, Number(group.count) || 0));
            const material = materials[Number(group.materialIndex || 0)] || materials[0] || null;
            let cursor = start;
            while (cursor + 2 < end) {
                const firstTriangle = Math.floor(cursor / 3);
                const canPair = cursor + 5 < end && (!ownerFilter || (
                    ownerFilter.has(owners[firstTriangle]) && ownerFilter.has(owners[firstTriangle + 1])
                ));
                const quadIndices = canPair ? sourceQuadIndices(position, uv, cursor) : null;
                if (quadIndices) {
                    const result = addEditableFaceFromSource(
                        mesh, sourceMesh, quadIndices, material,
                        textureCache, createdTextures, greedyFaceData, autoTileOverrides
                    );
                    if (result.faceKey) {
                        faceCount++;
                        if (result.greedy) greedyFaceCount++;
                    }
                    cursor += 6;
                    continue;
                }

                if (!ownerFilter || ownerFilter.has(owners[firstTriangle])) {
                    const triangleIndices = [cursor, cursor + 1, cursor + 2];
                    const result = addEditableFaceFromSource(
                        mesh, sourceMesh, triangleIndices, material,
                        textureCache, createdTextures, greedyFaceData, autoTileOverrides
                    );
                    if (result.faceKey) {
                        faceCount++;
                        if (result.greedy) greedyFaceCount++;
                    }
                }
                cursor += 3;
            }
        }
        if (!faceCount) return null;
        if (renderLayer === 'vegetation') mesh.sa_lighting_normal = 'up';
        mesh.userData ||= {};
        mesh.userData.bedrockRenderLayer = renderLayer;
        mesh.userData.bedrockEditableBakeFaceCount = faceCount;
        mesh.userData.bedrockEditableBakeGreedyFaces = greedyFaceCount;
        mesh.mcstructure_greedy_face_data_json = Object.keys(greedyFaceData).length
            ? JSON.stringify(greedyFaceData)
            : '';
        mesh.sa_mesh_face_auto_tile = Object.keys(autoTileOverrides).length
            ? JSON.stringify(autoTileOverrides)
            : '';
        return mesh;
    }

    function parseEditableGreedyFaceData(mesh) {
        const raw = mesh?.mcstructure_greedy_face_data_json;
        if (!raw) return {};
        if (raw && typeof raw === 'object' && !Array.isArray(raw)) return raw;
        try {
            const parsed = JSON.parse(String(raw));
            return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
        } catch {
            return {};
        }
    }

    function textureForMeshFace(face) {
        if (!face?.texture || typeof Texture === 'undefined' || !Array.isArray(Texture.all)) return null;
        return Texture.all.find(texture => (
            texture && (texture.uuid === face.texture || texture.id === face.texture || texture.name === face.texture)
        )) || null;
    }

    function materialUsesEditableBakeAtlas(material) {
        if (!material) return false;
        const map = material.map || material.uniforms?.map?.value || null;
        if (!map || typeof Texture === 'undefined' || !Array.isArray(Texture.all)) return false;
        return Texture.all.some(texture => {
            if (!texture?.mcstructure_baked_atlas_texture) return false;
            const nativeMaterial = typeof texture.getMaterial === 'function' ? texture.getMaterial() : texture.material;
            const nativeMap = nativeMaterial?.map || nativeMaterial?.uniforms?.map?.value || texture.texture || texture.three_texture;
            return nativeMap === map;
        });
    }

    function restoreEditableGreedyPreviewMaterials(mesh) {
        const preview = mesh?.mesh || (window.Project?.nodes_3d ? Project.nodes_3d[mesh?.uuid] : null);
        const state = preview?.userData?.bedrockEditableGreedyMaterials;
        if (!preview || !state) return false;
        const current = Array.isArray(preview.material) ? preview.material : [preview.material];
        const isOurClone = current.some(material => state.clones.includes(material));
        // Shader Architect may currently own the mesh and retain our clone as its
        // native source slot. Do not dispose a clone that another renderer can
        // still restore later; wait until the preview is actually using it.
        if (!isOurClone) return false;
        preview.material = state.wasArray ? state.source.slice() : state.source[0];
        state.clones.forEach(material => material?.dispose?.());
        delete preview.userData.bedrockEditableGreedyMaterials;
        return true;
    }

    function patchEditableGreedyPreviewMaterials(mesh, preview) {
        if (!preview || isLightflowRenderMode()) return false;
        const current = Array.isArray(preview.material) ? preview.material : [preview.material];
        const existingState = preview.userData?.bedrockEditableGreedyMaterials;
        if (existingState && current.some(material => existingState.clones.includes(material))) return true;
        if (existingState) restoreEditableGreedyPreviewMaterials(mesh);

        const source = Array.isArray(preview.material) ? preview.material.slice() : [preview.material];
        const clones = [];
        let changed = false;
        const patched = source.map(material => {
            if (!materialUsesEditableBakeAtlas(material) || typeof material?.clone !== 'function') return material;
            const clone = material.clone();
            clone.name = `${material.name || 'Bedrock Atlas'} [Editable Greedy]`;
            clone.userData ||= {};
            clone.userData.bedrockAtlas = true;
            clone.userData.bedrockEditableGreedyClone = true;
            installGreedyAtlasMaterialSupport(clone);
            clone.needsUpdate = true;
            clones.push(clone);
            changed = true;
            return clone;
        });
        if (!changed) return false;
        preview.userData ||= {};
        preview.userData.bedrockEditableGreedyMaterials = {
            source,
            clones,
            wasArray: Array.isArray(preview.material),
        };
        preview.material = Array.isArray(preview.material) ? patched : patched[0];
        return true;
    }

    function patchEditableGreedyMeshPreview(mesh) {
        if (!mesh?.mcstructure_baked_mesh || typeof THREE === 'undefined') return false;
        const data = parseEditableGreedyFaceData(mesh);
        const greedyKeys = Object.keys(data).filter(key => mesh.faces && Object.prototype.hasOwnProperty.call(mesh.faces, key));
        let existingOverrides = {};
        try {
            const parsed = mesh.sa_mesh_face_auto_tile ? JSON.parse(mesh.sa_mesh_face_auto_tile) : {};
            if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) existingOverrides = parsed;
        } catch {}
        const overrides = {};
        Object.keys(mesh.faces || {}).forEach(faceKey => {
            if (typeof existingOverrides[faceKey] === 'boolean') overrides[faceKey] = existingOverrides[faceKey];
        });
        greedyKeys.forEach(faceKey => { overrides[faceKey] = true; });
        mesh.sa_mesh_face_auto_tile = Object.keys(overrides).length ? JSON.stringify(overrides) : '';
        if (!greedyKeys.length) {
            restoreEditableGreedyPreviewMaterials(mesh);
            return false;
        }

        const preview = mesh.mesh || (window.Project?.nodes_3d ? Project.nodes_3d[mesh.uuid] : null);
        const geometry = preview?.geometry;
        const position = geometry?.getAttribute?.('position');
        if (!preview || !geometry?.isBufferGeometry || !position) return false;
        const tileValues = new Float32Array(position.count * 2);
        const rectValues = new Float32Array(position.count * 4);
        const repeatValues = new Float32Array(position.count);
        for (let vertexIndex = 0; vertexIndex < position.count; vertexIndex++) {
            rectValues[vertexIndex * 4 + 2] = 1;
            rectValues[vertexIndex * 4 + 3] = 1;
        }

        let positionOffset = 0;
        Object.keys(mesh.faces || {}).forEach(faceKey => {
            const face = mesh.faces[faceKey];
            const vertexCount = Array.isArray(face?.vertices) ? face.vertices.length : 0;
            if (!vertexCount || positionOffset >= position.count) return;
            const meta = data[faceKey];
            if (meta) {
                const tiles = Array.isArray(meta.t) ? meta.t : [];
                const texture = textureForMeshFace(face);
                const textureWidth = Math.max(1, Number(texture?.getUVWidth?.() || texture?.width || 16));
                const textureHeight = Math.max(1, Number(texture?.getUVHeight?.() || texture?.display_height || texture?.height || 16));
                const uvPixels = face.vertices.map(vertexKey => face.uv?.[vertexKey]).filter(value => Array.isArray(value));
                let rect = Array.isArray(meta.r) && meta.r.length >= 4 ? meta.r.slice(0, 4) : [0,0,1,1];
                if (uvPixels.length === vertexCount) {
                    const us = uvPixels.map(value => Number(value[0]) / textureWidth);
                    const vs = uvPixels.map(value => 1 - Number(value[1]) / textureHeight);
                    rect = [Math.min(...us), Math.min(...vs), Math.max(...us), Math.max(...vs)];
                }
                for (let local = 0; local < vertexCount && positionOffset + local < position.count; local++) {
                    const target = positionOffset + local;
                    repeatValues[target] = 1;
                    tileValues[target * 2] = Number(tiles[local * 2]) || 0;
                    tileValues[target * 2 + 1] = Number(tiles[local * 2 + 1]) || 0;
                    rectValues.set(rect, target * 4);
                }
            }
            positionOffset += vertexCount;
        });

        geometry.setAttribute('bedrockTileUv', new THREE.BufferAttribute(tileValues, 2));
        geometry.setAttribute('bedrockAtlasRect', new THREE.BufferAttribute(rectValues, 4));
        geometry.setAttribute('bedrockGreedyRepeat', new THREE.BufferAttribute(repeatValues, 1));
        geometry.attributes.bedrockTileUv.needsUpdate = true;
        geometry.attributes.bedrockAtlasRect.needsUpdate = true;
        geometry.attributes.bedrockGreedyRepeat.needsUpdate = true;
        patchEditableGreedyPreviewMaterials(mesh, preview);
        return true;
    }

    function patchAllEditableGreedyMeshPreviews() {
        if (typeof Mesh === 'undefined' || !Array.isArray(Mesh.all)) return 0;
        let patched = 0;
        for (const mesh of Mesh.all) {
            if (!mesh?.mcstructure_baked_mesh) continue;
            if (patchEditableGreedyMeshPreview(mesh)) patched++;
        }
        return patched;
    }

    function scheduleEditableGreedyPreviewPatch(delay = 0) {
        if (editableGreedyPatchTimer) clearTimeout(editableGreedyPatchTimer);
        editableGreedyPatchTimer = setTimeout(() => {
            editableGreedyPatchTimer = null;
            if (isStructureProject()) patchAllEditableGreedyMeshPreviews();
        }, Math.max(0, Number(delay) || 0));
    }

    function createGreedyBakeSourceMesh(sourceMesh, selectedCells = null) {
        const records = sourceMesh?.userData?.bedrockChunkRecords;
        const needsSubset = selectedCells instanceof Set && selectedCells.size > 0;
        if (!needsSubset) return {mesh: sourceMesh, temporary: false, stats: null};
        if (!Array.isArray(records) || !records.length || !optimizedPreview?.recordMap) return {mesh: null, temporary: false, stats: null};
        const selectedRecords = records.filter(record => selectedCells.has(record.element));
        if (!selectedRecords.length) return {mesh: null, temporary: false, stats: null};
        const stats = blockRenderStats();
        const mesh = buildOptimizedChunk(
            selectedRecords,
            optimizedPreview.recordMap,
            `${sourceMesh.userData?.chunkId || 'chunk'}#editable-greedy`,
            optimizedPreview.fallbackMaterial,
            stats,
            {greedy: true, registerFlipbooks: false}
        );
        if (!mesh) return {mesh: null, temporary: false, stats};
        mesh.userData.bedrockRenderLayer = sourceMesh.userData?.bedrockRenderLayer || 'solid';
        mesh.userData.chunkId = sourceMesh.userData?.chunkId || '';
        return {mesh, temporary: true, stats};
    }

    function disposeBakeSources(entries) {
        for (const entry of entries || []) {
            if (!entry?.temporary || !entry.mesh) continue;
            unregisterGeometryFlipbookTargets(entry.mesh);
            entry.mesh.geometry?.dispose?.();
            entry.mesh.removeFromParent?.();
        }
    }

    function bakeStructureToEditableMeshes() {
        if (!optimizedPreview?.chunkMeshes?.size || typeof Mesh === 'undefined') {
            Blockbench.showQuickMessage(tr('bedrock_structure.message.rebuild_before_bake', 'Rebuild the structure preview before baking.'), 2400);
            return [];
        }
        const selectedCells = new Set(selectedStructureBlocks());
        const selectedOutlinerNodes = selectedStructureOutlinerNodes();
        const selectedLayers = new Set(
            selectedOutlinerNodes
                .map(item => item?.mcstructure_baked_layer)
                .filter(Boolean)
        );
        const selectedChunks = new Set(
            selectedOutlinerNodes
                .map(item => item?.mcstructure_chunk_id)
                .filter(Boolean)
        );
        const isEffectivelyVisible = mesh => {
            let current = mesh;
            while (current) {
                if (current.visible === false) return false;
                current = current.parent;
            }
            return true;
        };
        const allSourceMeshes = Array.from(optimizedPreview.chunkMeshes);
        const sourceMeshes = selectedCells.size
            ? allSourceMeshes
            : selectedChunks.size
                ? allSourceMeshes.filter(mesh => selectedChunks.has(mesh.userData?.chunkId))
                : selectedLayers.size
                    ? allSourceMeshes.filter(mesh => selectedLayers.has(mesh.userData?.bedrockRenderLayer))
                    : allSourceMeshes.filter(isEffectivelyVisible);

        const bakeSources = sourceMeshes
            .map(sourceMesh => createGreedyBakeSourceMesh(sourceMesh, selectedCells))
            .filter(entry => entry?.mesh);
        const triangleCount = bakeSources.reduce((sum, entry) => (
            sum + Math.floor((entry.mesh.geometry?.attributes?.position?.count || 0) / 3)
        ), 0);
        if (!triangleCount) {
            disposeBakeSources(bakeSources);
            Blockbench.showQuickMessage(tr('bedrock_structure.message.no_baked_faces', 'The current selection contains no baked faces.'), 2400);
            return [];
        }
        if (triangleCount > 250000) {
            disposeBakeSources(bakeSources);
            Blockbench.showMessageBox({
                title: 'Bake is too large',
                message: `This optimized bake would still create ${triangleCount.toLocaleString()} render triangles. Select one render layer or fewer cells first (limit: 250,000).`,
                icon: 'warning',
            });
            return [];
        }
        const created = [];
        const createdTextures = [];
        const textureCache = new Map();
        Undo.initEdit({outliner: true, elements: [], textures: [], selection: true});
        const group = new Group({
            name: `Editable Structure Bake ${Group.all.filter(item => item.mcstructure_editable_bake_group).length + 1}`,
            mcstructure_editable_bake_group: true,
        }).init().addTo();
        try {
            for (const entry of bakeSources) {
                const editable = chunkToEditableMesh(
                    entry.mesh,
                    null,
                    textureCache,
                    createdTextures
                );
                if (!editable) continue;
                editable.init().addTo(group);
                editable.preview_controller?.updateGeometry?.(editable);
                editable.preview_controller?.updateFaces?.(editable);
                editable.preview_controller?.updateUV?.(editable);
                patchEditableGreedyMeshPreview(editable);
                created.push(editable);
            }
        } finally {
            disposeBakeSources(bakeSources);
        }
        if (!created.length) {
            group.remove?.();
            Undo.cancelEdit?.(true);
            return [];
        }
        unselectAllElements();
        group.select?.();
        Undo.finishEdit('Bake structure to editable meshes', {
            outliner: true,
            elements: created,
            textures: createdTextures,
            selection: true,
        });
        const shaderEngine = getShaderArchitectEngine();
        if (shaderEngine && isLightflowRenderMode() && typeof shaderEngine.updateCubes === 'function') {
            try { shaderEngine.updateCubes(created, 'bedrock_editable_greedy_bake'); }
            catch (error) { warnOnce('editable greedy lightflow', error); }
        }
        Canvas.updateAll?.();
        scheduleEditableGreedyPreviewPatch(0);
        Project.saved = false;
        const editableFaceCount = created.reduce((sum, mesh) => sum + Object.keys(mesh.faces || {}).length, 0);
        const greedyFaceCount = created.reduce((sum, mesh) => sum + Number(mesh.userData?.bedrockEditableBakeGreedyFaces || 0), 0);
        const greedyText = greedyFaceCount ? ` · ${greedyFaceCount.toLocaleString()} greedy region${greedyFaceCount === 1 ? '' : 's'}` : '';
        Blockbench.showQuickMessage(
            `Baked ${created.length} editable mesh${created.length === 1 ? '' : 'es'} · ${editableFaceCount.toLocaleString()} faces${greedyText}.`,
            3600
        );
        return created;
    }

    function adoptStructureCube(cube, options = {}) {
        if (!isStructureProject() || !(cube instanceof Cube)) return cube;
        const newlyAdopted = !cube.mcstructure_managed;
        if (newlyAdopted) {
            cube.mcstructure_managed = true;
            cube.mcstructure_block = Project.mcstructure_default_block || 'minecraft:stone';
            cube.mcstructure_states_json = '{}';
            cube.mcstructure_version = Number(Project.mcstructure_default_version) || 18168865;
            cube.mcstructure_layer = 0;
            cube.mcstructure_shape_override = 'auto';
            cube.mcstructure_source_position = '';
            cube.mcstructure_position_data_json = '';
            cube.mcstructure_grid_position = inferGridPositionFromTransform(cube);
            const primary = findStructureGroup('block', 0);
            if (primary && cube.parent !== primary) cube.addTo(primary);
            applyTextureForBlock(cube);
            if (options.normalize !== false) setCubeGridPosition(cube, cube.mcstructure_grid_position, true);
        }
        // Existing managed blocks deliberately keep their last committed grid
        // position here. finish_edit can then use it as a rollback point if a
        // free-form Blockbench transform lands on an occupied cell.
        return cube;
    }

    function createBlockAt(position, block, states, version, layer, undo = true) {
        if (undo) {
            const normalizedPosition = [position.x, position.y, position.z].map(value => Math.round(Number(value) || 0));
            const normalizedLayer = Number(layer) === 1 ? 1 : 0;
            return runLogicalUndo(
                tr('bedrock_structure.undo.add_block', 'Add structure block'),
                () => createBlockAt(position, block, states, version, layer, false),
                {
                    targets: {
                        ids: [],
                        keys: [spatialRecordKey(normalizedPosition[0], normalizedPosition[1], normalizedPosition[2], normalizedLayer)],
                        positionData: false,
                    }
                }
            );
        }
        const runtime = ensureLogicalRuntime();
        if (!runtime) throw new Error('The logical structure runtime is unavailable.');
        const normalizedPosition = [position.x, position.y, position.z].map(value => Math.round(Number(value) || 0));
        const normalizedLayer = Number(layer) === 1 ? 1 : 0;
        const key = spatialRecordKey(normalizedPosition[0], normalizedPosition[1], normalizedPosition[2], normalizedLayer);
        const existing = runtime.byKey.get(key);
        if (existing) {
            throw new RangeError(`Layer ${normalizedLayer} already contains ${existing.name} at (${position.x}, ${position.y}, ${position.z}).`);
        }
        const descriptor = {
            name: String(block || '').includes(':') ? String(block) : `minecraft:${String(block || 'stone')}`,
            states: states || {},
            version: Number(version) || Number(Project.mcstructure_default_version) || 18168865,
        };
        const record = makeLogicalBlockRecord({
            name: makeBlockLabel(descriptor, normalizedLayer),
            visibility: normalizedLayer === 0 || Boolean(Project.mcstructure_secondary_visible),
            mcstructure_grid_position: normalizedPosition,
            mcstructure_shape_override: 'auto',
            mcstructure_block: descriptor.name,
            mcstructure_states_json: JSON.stringify(descriptor.states, null, 2),
            mcstructure_version: descriptor.version,
            mcstructure_layer: normalizedLayer,
            mcstructure_source_position: '',
            mcstructure_position_data_json: '',
        });
        runtime.records.push(record);
        runtime.byKey.set(key, record);
        runtime.byId.set(record.mcstructure_runtime_id, record);
        touchLogicalRuntime(runtime, {rebuildIndex: false});
        setLogicalSelection([record]);
        scheduleOptimizedPreviewRebuild(0, [{position: getStructureGridPosition(record), layer: Number(record.mcstructure_layer || 0)}]);
        syncStructurePanel();
        return record;
    }

    function prepareEntityNodeForLocator(identifier, position, rotation, sourceNode = null) {
        const normalizedIdentifier = String(identifier || '').trim();
        if (!normalizedIdentifier) throw new TypeError('Entity identifier cannot be empty.');
        const positionValues = [Number(position?.x), Number(position?.y), Number(position?.z)];
        const rotationValues = [Number(rotation?.yaw), Number(rotation?.pitch)];
        if (!positionValues.every(Number.isFinite) || !rotationValues.every(Number.isFinite)) {
            throw new TypeError('Entity position and rotation must be finite numbers.');
        }
        let node = sourceNode ? cloneNBT(sourceNode) : BedrockStructureParser.NBT.compound();
        if (!node || node.type !== BedrockStructureParser.NBT_TAG.Compound) {
            throw new TypeError('Entity NBT must be a typed TAG_Compound.');
        }
        setCompoundChild(node, 'identifier', BedrockStructureParser.NBT.string(
            normalizedIdentifier.includes(':') ? normalizedIdentifier : `minecraft:${normalizedIdentifier}`
        ));
        const origin = Array.isArray(Project.mcstructure_world_origin)
            ? Project.mcstructure_world_origin.slice(0, 3).map(value => Number(value) || 0)
            : [0, 0, 0];
        updateEntityListNode(node, 'Pos', [
            origin[0] + positionValues[0],
            origin[1] + positionValues[1],
            origin[2] + positionValues[2],
        ], BedrockStructureParser.NBT_TAG.Float);
        updateEntityListNode(node, 'Rotation', [
            rotationValues[0],
            rotationValues[1],
        ], BedrockStructureParser.NBT_TAG.Float);
        return node;
    }

    function createEntityAt(identifier, position, rotation, undo = true, sourceNode = null) {
        const group = findStructureGroup('entity');
        if (!group) throw new Error('The structure entity group is missing.');
        const node = prepareEntityNodeForLocator(identifier, position, rotation, sourceNode);
        if (undo) Undo.initEdit({outliner: true, elements: [], selection: true});
        const locator = new Locator({
            name: identifier.replace(/^minecraft:/, ''),
            position: [position.x * BLOCK_SIZE, position.y * BLOCK_SIZE, position.z * BLOCK_SIZE],
            rotation: [rotation.pitch, rotation.yaw, 0],
            mcstructure_entity: true,
            mcstructure_entity_nbt_json: stringifyTypedNBT(node),
            mcstructure_entity_source_index: -1,
            mcstructure_entity_has_position: true,
            mcstructure_entity_has_rotation: true,
        }).init().addTo(group);
        if (undo) {
            unselectAllElements();
            locator.select();
            Undo.finishEdit(tr('bedrock_structure.undo.add_entity', 'Add structure entity'), {
                outliner: true,
                elements: [locator],
                selection: true,
            });
        }
        Project.saved = false;
        return locator;
    }

    function getPlainBlockEntity(cube) {
        const runtime = ensureLogicalRuntime();
        const raw = runtime?.positionData?.get(logicalPositionKey(getStructureGridPosition(cube))) || '';
        const positionData = parseTypedNBT(raw, `${cube.name} position data`);
        const blockEntity = getCompoundChild(positionData, 'block_entity_data');
        if (!blockEntity) return '';
        return JSON.stringify(
            BedrockStructureParser.toJSONCompatible(BedrockStructureParser.NBT.unwrap(blockEntity)),
            null,
            2
        );
    }

    function updateCubeBlockEntity(cube, plainValue) {
        const runtime = ensureLogicalRuntime();
        if (!runtime) throw new Error('The logical structure runtime is unavailable.');
        runtime.positionData ||= new Map();
        const key = logicalPositionKey(getStructureGridPosition(cube));
        let positionData = parseTypedNBT(runtime.positionData.get(key) || '', `${cube.name} position data`);
        if (!positionData) positionData = BedrockStructureParser.NBT.compound();
        if (String(plainValue || '').trim() === '') {
            setCompoundChild(positionData, 'block_entity_data', null);
        } else {
            const plain = parseObjectJSON(plainValue, 'Block entity');
            const existing = getCompoundChild(positionData, 'block_entity_data');
            setCompoundChild(positionData, 'block_entity_data', mergePlainIntoNBT(existing, plain));
        }
        if (Object.keys(positionData.value).length) runtime.positionData.set(key, stringifyTypedNBT(positionData));
        else runtime.positionData.delete(key);
        cube.mcstructure_position_data_json = '';
    }

    function getTypedPositionDataAt(position) {
        const runtime = ensureLogicalRuntime();
        if (!runtime || !Array.isArray(position) || position.length < 3) return null;
        const normalized = position.slice(0, 3).map(value => Math.round(Number(value) || 0));
        const raw = runtime.positionData?.get(logicalPositionKey(normalized)) || '';
        return parseTypedNBT(raw, `Position data (${normalized.join(', ')})`);
    }

    function getTypedPositionData(cube) {
        if (!cube) return null;
        return getTypedPositionDataAt(getStructureGridPosition(cube));
    }

    function getPlainScheduledTicksAt(position) {
        const positionData = getTypedPositionDataAt(position);
        const ticks = getCompoundChild(positionData, 'tick_queue_data');
        if (!ticks) return '[]';
        return JSON.stringify(
            BedrockStructureParser.toJSONCompatible(BedrockStructureParser.NBT.unwrap(ticks)),
            null,
            2
        );
    }

    function getPlainScheduledTicks(cube) {
        return cube ? getPlainScheduledTicksAt(getStructureGridPosition(cube)) : '[]';
    }

    function showPositionDataCoordinateDialog() {
        const runtime = ensureLogicalRuntime();
        const selected = selectedStructureBlocks();
        const firstKnownKey = runtime?.positionData?.keys?.().next?.().value || '';
        const fallback = firstKnownKey
            ? firstKnownKey.split(',').slice(0, 3).map(value => Math.round(Number(value) || 0))
            : [0, 0, 0];
        const initial = selected.length === 1 ? getStructureGridPosition(selected[0]) : fallback;
        new Dialog({
            id: 'bedrock_structure_position_data_coordinate',
            title: 'bedrock_structure.dialog.position_data',
            width: 520,
            form: {
                position: {
                    label: 'bedrock_structure.field.block_coordinate',
                    type: 'vector',
                    dimensions: 3,
                    value: initial,
                    step: 1,
                    description: 'bedrock_structure.desc.position_air_coordinate',
                },
            },
            onConfirm(result) {
                const target = Array.isArray(result.position)
                    ? result.position.slice(0, 3).map(value => Math.round(Number(value) || 0))
                    : initial.slice();
                if (target.length < 3 || !target.every(Number.isSafeInteger)) {
                    Blockbench.showQuickMessage(tr('bedrock_structure.message.position_coordinates_invalid', 'Position data coordinates must be three safe integers.'), 3000);
                    return;
                }
                this.hide();
                showPositionDataDialog(target);
            },
        }).show();
    }

    function showPositionDataDialog(position = null) {
        const selected = selectedStructureBlocks();
        const cube = selected.length === 1 ? selected[0] : null;
        if ((!Array.isArray(position) || position.length < 3) && !cube) {
            showPositionDataCoordinateDialog();
            return;
        }
        const initialPosition = Array.isArray(position) && position.length >= 3
            ? position.slice(0, 3).map(value => Math.round(Number(value) || 0))
            : getStructureGridPosition(cube);
        let positionData;
        let tickValue;
        try {
            positionData = getTypedPositionDataAt(initialPosition) || BedrockStructureParser.NBT.compound();
            tickValue = getPlainScheduledTicksAt(initialPosition);
        } catch (error) {
            showError('read position data', error);
            return;
        }
        new Dialog({
            id: 'bedrock_structure_position_data',
            title: 'bedrock_structure.dialog.position_data',
            width: 760,
            form: {
                coordinate: {
                    label: 'bedrock_structure.field.block_coordinate',
                    type: 'text',
                    value: `(${initialPosition.join(', ')})`,
                    readonly: true,
                    description: 'bedrock_structure.desc.position_coordinate_owned',
                },
                apply_ticks: {
                    label: 'bedrock_structure.field.apply_ticks',
                    type: 'checkbox',
                    value: false,
                    description: 'bedrock_structure.desc.apply_ticks',
                },
                ticks: {
                    label: 'bedrock_structure.field.scheduled_ticks',
                    type: 'textarea',
                    value: tickValue,
                    description: 'bedrock_structure.desc.scheduled_ticks',
                },
                typed_nbt: {
                    label: 'bedrock_structure.field.position_typed_nbt',
                    type: 'textarea',
                    value: stringifyTypedNBT(positionData),
                    description: 'bedrock_structure.desc.position_typed_nbt',
                },
            },
            onConfirm(result) {
                try {
                    const targetPosition = initialPosition.slice();
                    let next = parseTypedNBT(result.typed_nbt, 'Position data');
                    if (!next) next = BedrockStructureParser.NBT.compound();
                    if (next.type !== BedrockStructureParser.NBT_TAG.Compound) {
                        throw new TypeError('Position data must be a typed TAG_Compound.');
                    }
                    if (result.apply_ticks === true) {
                        let ticks;
                        try { ticks = JSON.parse(String(result.ticks || '[]')); }
                        catch (error) { throw new SyntaxError(`Scheduled ticks are not valid JSON: ${error.message}`); }
                        if (!Array.isArray(ticks)) throw new TypeError('Scheduled ticks must be a JSON array.');
                        const existingTicks = getCompoundChild(next, 'tick_queue_data');
                        if (!ticks.length) {
                            setCompoundChild(next, 'tick_queue_data', null);
                        } else if (existingTicks) {
                            setCompoundChild(next, 'tick_queue_data', mergePlainIntoNBT(existingTicks, ticks));
                        } else {
                            setCompoundChild(next, 'tick_queue_data', BedrockStructureParser.NBT.list(
                                BedrockStructureParser.NBT_TAG.Compound,
                                ticks.map(tick => BedrockStructureParser.NBT.compound(tick))
                            ));
                        }
                    }
                    const runtime = ensureLogicalRuntime();
                    const key = logicalPositionKey(targetPosition);
                    const updated = runLogicalUndo(
                        tr('bedrock_structure.undo.position_data', 'Edit block position NBT'),
                        () => {
                            runtime.positionData ||= new Map();
                            if (Object.keys(next.value || {}).length) runtime.positionData.set(key, stringifyTypedNBT(next));
                            else runtime.positionData.delete(key);
                            touchLogicalRuntime(runtime, {rebuildIndex: false});
                            syncStructurePanel();
                            return true;
                        },
                        {
                            targets: {
                                ids: [],
                                keys: [],
                                positionKeys: [key],
                                selection: false,
                            }
                        }
                    );
                    if (!updated) return;
                    this.hide();
                    Blockbench.showQuickMessage(trf('bedrock_structure.message.position_nbt_updated', 'Position NBT updated at ({0}).', [targetPosition.join(', ')]), 2600);
                } catch (error) {
                    showError('edit position data', error);
                }
            },
        }).show();
    }

    function showAddBlockDialog() {
        if (!isStructureProject()) return;
        const selected = selectedStructureBlocks()[0] || null;
        let suggested = {x: 0, y: 0, z: 0};
        if (selected?.mcstructure_managed) {
            const logical = getStructureGridPosition(selected);
            suggested = {x: logical[0] + 1, y: logical[1], z: logical[2]};
        }
        new Dialog({
            id: 'bedrock_structure_add_block',
            title: 'bedrock_structure.action.add_block',
            width: 560,
            form: {
                x: {label: 'bedrock_structure.field.x', type: 'number', value: suggested.x, step: 1},
                y: {label: 'bedrock_structure.field.y', type: 'number', value: suggested.y, step: 1},
                z: {label: 'bedrock_structure.field.z', type: 'number', value: suggested.z, step: 1},
                source_hint: selected ? {
                    type: 'info',
                    text: 'bedrock_structure.desc.add_block_template',
                } : {type: 'info', text: 'bedrock_structure.desc.add_block_manual'},
                block_preset: {label: 'bedrock_structure.field.known_block', type: 'select', value: '__custom__', options: structureBlockPresetOptions()},
                block: {label: 'bedrock_structure.field.block', type: 'text', value: selected?.mcstructure_block || Project.mcstructure_default_block},
                states: {label: 'bedrock_structure.field.states', type: 'textarea', value: selected?.mcstructure_states_json || '{}'},
                version: {
                    label: 'bedrock_structure.field.version',
                    type: 'number',
                    value: selected?.mcstructure_version || Project.mcstructure_default_version,
                    step: 1,
                },
                layer: {
                    label: 'bedrock_structure.field.layer',
                    type: 'select',
                    options: {
                        0: 'bedrock_structure.field.layer_primary',
                        1: 'bedrock_structure.field.layer_secondary',
                    },
                    value: String(selected?.mcstructure_layer || 0),
                },
            },
            onConfirm(result) {
                try {
                    const coordinates = [result.x, result.y, result.z].map(Number);
                    if (!coordinates.every(Number.isInteger)) throw new TypeError('Block coordinates must be integers.');
                    const version = Number(result.version);
                    if (!Number.isInteger(version)) throw new TypeError('Block version must be an integer.');
                    createBlockAt(
                        {x: coordinates[0], y: coordinates[1], z: coordinates[2]},
                        blockIdentifierFromDialog(result, 'block', 'block_preset'),
                        parseObjectJSON(result.states, 'Block states'),
                        version,
                        Number(result.layer)
                    );
                    this.hide();
                } catch (error) {
                    showError('add block', error);
                }
            },
        }).show();
    }

    function showEditBlockDialog() {
        if (!isStructureProject()) return;
        const selected = selectedStructureBlocks();
        if (!selected.length) {
            Blockbench.showQuickMessage(tr('bedrock_structure.message.no_blocks', 'Select at least one structure block.'));
            return;
        }
        const first = selected[0];
        const multiple = selected.length > 1;
        const allEqual = getter => selected.every(item => getter(item) === getter(first));
        const mixedBlock = multiple && !allEqual(item => item.mcstructure_block);
        const mixedStates = multiple && !allEqual(item => item.mcstructure_states_json || '{}');
        const mixedVersion = multiple && !allEqual(item => Number(item.mcstructure_version));
        const mixedLayer = multiple && !allEqual(item => Number(item.mcstructure_layer || 0));
        let blockEntityValue;
        try {
            blockEntityValue = getPlainBlockEntity(first);
        } catch (error) {
            showError('read block entity', error);
            return;
        }
        new Dialog({
            id: 'bedrock_structure_edit_block',
            title: 'bedrock_structure.dialog.block',
            width: 620,
            form: {
                selection_summary: multiple ? {
                    type: 'info',
                    text: `${selected.length.toLocaleString()} cells selected. Enable Apply only for fields you want to overwrite across the selection.`,
                } : {type: 'info', text: 'Edit the selected structure cell.'},
                apply_block: {
                    label: 'bedrock_structure.field.apply_block', type: 'checkbox', value: !mixedBlock && false,
                    condition: () => multiple,
                },
                block_preset: {label: 'bedrock_structure.field.known_block', type: 'select', value: '__custom__', options: structureBlockPresetOptions()},
                block: {label: 'bedrock_structure.field.block', type: 'text', value: first.mcstructure_block},
                apply_states: {
                    label: 'bedrock_structure.field.apply_states', type: 'checkbox', value: !mixedStates && false,
                    condition: () => multiple,
                },
                states: {
                    label: 'bedrock_structure.field.states',
                    type: 'textarea',
                    value: first.mcstructure_states_json || '{}',
                },
                apply_version: {
                    label: 'bedrock_structure.field.apply_version', type: 'checkbox', value: !mixedVersion && false,
                    condition: () => multiple,
                },
                version: {
                    label: 'bedrock_structure.field.version',
                    type: 'number',
                    value: first.mcstructure_version,
                    step: 1,
                },
                apply_layer: {
                    label: 'bedrock_structure.field.apply_layer', type: 'checkbox', value: !mixedLayer && false,
                    condition: () => multiple,
                },
                layer: {
                    label: 'bedrock_structure.field.layer',
                    type: 'select',
                    options: {
                        0: 'bedrock_structure.field.layer_primary',
                        1: 'bedrock_structure.field.layer_secondary',
                    },
                    value: String(first.mcstructure_layer || 0),
                },
                block_entity: {
                    label: 'bedrock_structure.field.block_entity',
                    type: 'textarea',
                    value: blockEntityValue,
                    description: 'bedrock_structure.desc.block_entity',
                    condition: () => !multiple,
                },
            },
            onConfirm(result) {
                try {
                    const applyBlock = !multiple || result.apply_block === true;
                    const applyStates = !multiple || result.apply_states === true;
                    const applyVersion = !multiple || result.apply_version === true;
                    const applyLayer = !multiple || result.apply_layer === true;
                    if (multiple && !applyBlock && !applyStates && !applyVersion && !applyLayer) {
                        Blockbench.showQuickMessage(tr('bedrock_structure.message.choose_apply_field', 'Choose at least one field to apply to the selection.'), 2400);
                        return;
                    }
                    const block = applyBlock
                        ? blockIdentifierFromDialog(result, 'block', 'block_preset')
                        : first.mcstructure_block;
                    if (applyBlock && !block) throw new TypeError('Block identifier cannot be empty.');
                    const states = applyStates ? parseObjectJSON(result.states, 'Block states') : null;
                    const version = applyVersion ? Number(result.version) : null;
                    const layer = applyLayer ? Number(result.layer) : null;
                    if (applyVersion && !Number.isInteger(version)) throw new TypeError('Block version must be an integer.');
                    if (applyLayer && layer !== 0 && layer !== 1) throw new TypeError('Block layer must be 0 or 1.');
                    const selectedSet = new Set(selected);
                    const runtime = ensureLogicalRuntime();
                    if (applyLayer) {
                        const movingKeys = new Set();
                        for (const cube of selected) {
                            const position = getStructureGridPosition(cube);
                            const key = spatialRecordKey(position[0], position[1], position[2], layer);
                            const occupant = runtime?.byKey?.get(key);
                            if ((occupant && !selectedSet.has(occupant)) || movingKeys.has(key)) {
                                throw new RangeError(`Layer ${layer} already contains a block at (${position.join(',')}).`);
                            }
                            movingKeys.add(key);
                        }
                    }
                    const updated = runLogicalUndo(
                        tr('bedrock_structure.undo.edit_block', 'Edit structure block data'),
                        () => {
                            const dirtyPositions = [];
                            const oldKeys = selected.map(cube => logicalRecordKey(cube));
                            for (const cube of selected) {
                                const position = getStructureGridPosition(cube).slice();
                                const oldLayer = Number(cube.mcstructure_layer || 0);
                                dirtyPositions.push({position, layer: oldLayer});
                                if (applyBlock) cube.mcstructure_block = block.includes(':') ? block : `minecraft:${block}`;
                                if (applyStates) cube.mcstructure_states_json = JSON.stringify(states, null, 2);
                                if (applyVersion) cube.mcstructure_version = version;
                                if (applyLayer) cube.mcstructure_layer = layer;
                                if (!multiple) updateCubeBlockEntity(cube, result.block_entity);
                                const nextLayer = Number(cube.mcstructure_layer || 0);
                                const nextStates = cachedParsedBlockStates(cube);
                                cube.name = makeBlockLabel({name: cube.mcstructure_block, states: nextStates, version: cube.mcstructure_version}, nextLayer);
                                cube.visibility = nextLayer === 0 || Boolean(Project.mcstructure_secondary_visible);
                                dirtyPositions.push({position, layer: nextLayer});
                            }
                            if (runtime) {
                                for (const key of oldKeys) runtime.byKey.delete(key);
                                for (const cube of selected) runtime.byKey.set(logicalRecordKey(cube), cube);
                            }
                            touchLogicalRuntime(runtime || undefined, {rebuildIndex: !runtime});
                            scheduleOptimizedPreviewRebuild(0, dirtyPositions);
                            updateLogicalSelectionHelpers();
                            syncStructurePanel();
                            return true;
                        },
                        {
                            targets: {
                                ids: selected.map(cube => cube.mcstructure_runtime_id).filter(Boolean),
                                keys: [],
                                positionKeys: selected.map(cube => logicalPositionKey(getStructureGridPosition(cube))),
                                selection: false,
                            }
                        }
                    );
                    if (!updated) return;
                    this.hide();
                    Blockbench.showQuickMessage(tr('bedrock_structure.message.updated', 'Structure block data updated.'));
                } catch (error) {
                    showError('edit block', error);
                }
            },
        }).show();
    }

    function showAddEntityDialog() {
        if (!isStructureProject()) return;
        const defaultEntityNBT = BedrockStructureParser.NBT.compound({
            identifier: BedrockStructureParser.NBT.string('minecraft:armor_stand'),
        });
        new Dialog({
            id: 'bedrock_structure_add_entity',
            title: 'bedrock_structure.action.add_entity',
            width: 720,
            form: {
                transform_authority: {
                    type: 'info',
                    text: tr(
                        'bedrock_structure.desc.entity_authority',
                        'Identifier, position, and rotation fields are authoritative. They are written into typed NBT and synchronized again on export; use the typed editor for all additional tags and exact numeric widths.'
                    ),
                },
                identifier: {
                    label: 'bedrock_structure.field.identifier',
                    type: 'text',
                    value: 'minecraft:armor_stand',
                },
                x: {label: 'bedrock_structure.field.x', type: 'number', value: 0, step: 0.25},
                y: {label: 'bedrock_structure.field.y', type: 'number', value: 0, step: 0.25},
                z: {label: 'bedrock_structure.field.z', type: 'number', value: 0, step: 0.25},
                yaw: {label: 'bedrock_structure.field.yaw', type: 'number', value: 0, step: 1},
                pitch: {label: 'bedrock_structure.field.pitch', type: 'number', value: 0, step: 1},
                typed_nbt: {
                    label: 'bedrock_structure.field.entity_nbt',
                    type: 'textarea',
                    value: stringifyTypedNBT(defaultEntityNBT),
                    description: 'bedrock_structure.desc.entity_nbt',
                },
            },
            onConfirm(result) {
                try {
                    const identifier = String(result.identifier).trim();
                    if (!identifier) throw new TypeError('Entity identifier cannot be empty.');
                    const typed = parseTypedNBT(result.typed_nbt, 'Entity NBT');
                    if (!typed || typed.type !== BedrockStructureParser.NBT_TAG.Compound) {
                        throw new TypeError('Entity NBT must be a typed TAG_Compound.');
                    }
                    createEntityAt(
                        identifier,
                        {x: Number(result.x), y: Number(result.y), z: Number(result.z)},
                        {yaw: Number(result.yaw), pitch: Number(result.pitch)},
                        true,
                        typed
                    );
                    this.hide();
                } catch (error) {
                    showError('add entity', error);
                }
            },
        }).show();
    }

    function showEditEntityDialog() {
        if (!isStructureProject()) return;
        const locator = Locator.all.find(entry => entry.selected && entry.mcstructure_entity)
            || Locator.all.find(entry => entry.mcstructure_entity && Outliner.selected.includes(entry));
        if (!locator) {
            Blockbench.showQuickMessage(tr('bedrock_structure.message.no_entity', 'Select one structure entity locator.'));
            return;
        }
        let typed;
        try {
            typed = parseTypedNBT(locator.mcstructure_entity_nbt_json, `${locator.name} NBT`);
            if (!typed || typed.type !== BedrockStructureParser.NBT_TAG.Compound) {
                throw new TypeError(`${locator.name} NBT must be a typed TAG_Compound.`);
            }
        } catch (error) {
            showError('read entity NBT', error);
            return;
        }
        new Dialog({
            id: 'bedrock_structure_edit_entity',
            title: 'bedrock_structure.dialog.entity',
            width: 680,
            form: {
                transform_authority: {
                    type: 'info',
                    text: tr(
                        'bedrock_structure.desc.entity_authority',
                        'Identifier, position, and rotation fields are authoritative. They are written into typed NBT and synchronized again on export; use the typed editor for all additional tags and exact numeric widths.'
                    ),
                },
                x: {label: 'bedrock_structure.field.x', type: 'number', value: Number(locator.position?.[0] || 0) / BLOCK_SIZE, step: 0.25},
                y: {label: 'bedrock_structure.field.y', type: 'number', value: Number(locator.position?.[1] || 0) / BLOCK_SIZE, step: 0.25},
                z: {label: 'bedrock_structure.field.z', type: 'number', value: Number(locator.position?.[2] || 0) / BLOCK_SIZE, step: 0.25},
                yaw: {label: 'bedrock_structure.field.yaw', type: 'number', value: Number(locator.rotation?.[1] || 0), step: 1},
                pitch: {label: 'bedrock_structure.field.pitch', type: 'number', value: Number(locator.rotation?.[0] || 0), step: 1},
                entity_nbt: {
                    label: 'bedrock_structure.field.entity_nbt',
                    type: 'textarea',
                    value: stringifyTypedNBT(typed),
                    description: 'bedrock_structure.desc.entity_nbt',
                },
            },
            onConfirm(result) {
                try {
                    const position = [Number(result.x), Number(result.y), Number(result.z)];
                    const rotation = [Number(result.pitch), Number(result.yaw), 0];
                    if (!position.every(Number.isFinite) || !rotation.every(Number.isFinite)) {
                        throw new TypeError('Entity position and rotation must be finite numbers.');
                    }
                    const editedTyped = parseTypedNBT(result.entity_nbt, 'Entity NBT');
                    if (!editedTyped || editedTyped.type !== BedrockStructureParser.NBT_TAG.Compound) {
                        throw new TypeError('Entity NBT must be a typed TAG_Compound.');
                    }
                    const editedPlain = BedrockStructureParser.NBT.unwrap(editedTyped);
                    const identifier = String(
                        editedPlain?.identifier
                        || editedPlain?.Identifier
                        || editedPlain?.id
                        || locator.name
                        || 'minecraft:armor_stand'
                    );
                    const nextTyped = prepareEntityNodeForLocator(
                        identifier,
                        {x: position[0], y: position[1], z: position[2]},
                        {yaw: rotation[1], pitch: rotation[0]},
                        editedTyped
                    );
                    Undo.initEdit({elements: [locator]});
                    locator.mcstructure_entity_nbt_json = stringifyTypedNBT(nextTyped);
                    locator.name = getEntityIdentifier(nextTyped, 0).replace(/^minecraft:/, '');
                    locator.position = position.map(value => value * BLOCK_SIZE);
                    locator.rotation = rotation;
                    locator.mcstructure_entity_has_position = true;
                    locator.mcstructure_entity_has_rotation = true;
                    locator.preview_controller?.updateTransform?.(locator);
                    Undo.finishEdit(tr('bedrock_structure.undo.edit_entity', 'Edit structure entity data'), {
                        elements: [locator],
                    });
                    Project.saved = false;
                    this.hide();
                    Blockbench.showQuickMessage(
                        tr('bedrock_structure.message.entity_updated', 'Structure entity data updated.')
                    );
                } catch (error) {
                    showError('edit entity', error);
                }
            },
        }).show();
    }

    function readPackJson(fileSystem, filePath, options = {}) {
        if (!filePath || !fileSystem.existsSync(filePath)) return null;
        try {
            // Resource packs found in the wild frequently contain a UTF-8 BOM,
            // comments/trailing commas, or one optional metadata file that is
            // malformed while the actual textures remain perfectly usable.
            const content = String(fileSystem.readFileSync(filePath, 'utf8') || '').replace(/^\uFEFF/, '');
            if (!content.trim()) return null;
            if (typeof autoParseJSON === 'function') return autoParseJSON(content, false);
            return JSON.parse(content);
        } catch (error) {
            const required = options.required === true;
            const label = options.label || filePath;
            if (required) {
                throw new Error(`Could not parse resource-pack JSON ${label}: ${error?.message || error}`);
            }
            warnOnce(`resource-pack-json:${filePath}`, new Error(`Ignoring malformed optional resource-pack JSON ${label}: ${error?.message || error}`));
            return null;
        }
    }

    function normalizeTextureVariants(value) {
        if (value == null) return [];
        if (typeof value === 'string') return [{path: value, overlayColor: null}];
        if (Array.isArray(value)) return value.flatMap(normalizeTextureVariants);
        if (typeof value === 'object') {
            if (typeof value.path === 'string') {
                return [{
                    path: value.path,
                    overlayColor: value.overlay_color || value.tint_color || null,
                }];
            }
            if (value.textures != null) return normalizeTextureVariants(value.textures);
        }
        return [];
    }

    function firstTextureReference(value) {
        return normalizeTextureVariants(value)[0]?.path || null;
    }

    const LEGACY_TEXTURE_STATE_VARIANTS = Object.freeze({
        stone_type: ['stone','granite','granite_smooth','diorite','diorite_smooth','andesite','andesite_smooth'],
        sand_type: ['normal','red'],
        dirt_type: ['normal','coarse'],
        wood_type: ['oak','spruce','birch','jungle','acacia','dark_oak'],
        old_leaf_type: ['oak','spruce','birch','jungle'],
        new_leaf_type: ['acacia','dark_oak'],
        tall_grass_type: ['default','tall','fern','snow'],
        double_plant_type: ['sunflower','syringa','grass','fern','rose','paeonia'],
        prismarine_block_type: ['default','dark','bricks'],
        coral_color: ['blue','pink','purple','red','yellow'],
    });

    function stateVariantIndex(states, count) {
        if (!states || count <= 1) return 0;
        for (const [stateName, values] of Object.entries(LEGACY_TEXTURE_STATE_VARIANTS)) {
            const value = states[stateName];
            if (value == null) continue;
            const index = values.indexOf(String(value).replace(/^minecraft:/, ''));
            if (index >= 0 && index < count) return index;
        }
        const numeric = Object.values(states).filter(value => Number.isInteger(Number(value)));
        if (numeric.length === 1) {
            const index = Number(numeric[0]);
            if (index >= 0 && index < count) return index;
        }
        return 0;
    }

    function normalizeResourcePackRoot(fileSystem, pathModule, selectedPath) {
        const selected = pathModule.resolve(String(selectedPath || ''));
        if (!selected || !fileSystem.existsSync(selected)) {
            throw new Error(`Resource-pack folder does not exist: ${selectedPath}`);
        }

        const scoreCandidate = candidate => {
            let score = 0;
            try {
                if (!fileSystem.statSync(candidate).isDirectory()) return -1;
                const texturesDirectory = pathModule.join(candidate, 'textures');
                const hasTextures = fileSystem.existsSync(texturesDirectory);
                if (!hasTextures) return -1;
                if (fileSystem.existsSync(pathModule.join(texturesDirectory, 'terrain_texture.json'))) score += 32;
                if (fileSystem.existsSync(pathModule.join(candidate, 'manifest.json'))) score += 16;
                if (fileSystem.existsSync(pathModule.join(candidate, 'blocks.json'))) score += 8;
                if (fileSystem.existsSync(pathModule.join(texturesDirectory, 'blocks'))) score += 6;
                score += 2;
                if (fileSystem.existsSync(pathModule.join(candidate, 'biomes_client.json'))) score += 1;
            } catch {}
            return score;
        };

        const candidates = new Set([selected, pathModule.join(selected, 'resource_pack')]);
        // Also accept selecting a parent directory that contains one or more
        // resource packs (common for development_resource_packs and samples).
        try {
            for (const entry of fileSystem.readdirSync(selected, {withFileTypes: true}).slice(0, 256)) {
                if (!entry?.isDirectory?.()) continue;
                const child = pathModule.join(selected, entry.name);
                candidates.add(child);
                candidates.add(pathModule.join(child, 'resource_pack'));
            }
        } catch {}

        let best = null;
        let bestScore = -1;
        for (const candidate of candidates) {
            const score = scoreCandidate(candidate);
            if (score > bestScore) {
                best = candidate;
                bestScore = score;
            }
        }
        if (best && bestScore >= 2) return best;

        throw new Error(
            `No usable Bedrock resource pack was found in ${selectedPath}. `
            + 'The selected folder should contain a manifest.json, blocks.json, a textures folder, or textures/terrain_texture.json.'
        );
    }

    function bedrockJsonFiles(fileSystem, pathModule, root, limit = 8192) {
        if (!root || !fileSystem.existsSync(root)) return [];
        const files = [];
        const pending = [root];
        while (pending.length && files.length < limit) {
            const directory = pending.pop();
            let entries = [];
            try { entries = fileSystem.readdirSync(directory, {withFileTypes: true}); } catch { continue; }
            entries.sort((a, b) => String(a.name).localeCompare(String(b.name)));
            for (let index = entries.length - 1; index >= 0; index--) {
                const entry = entries[index];
                const fullPath = pathModule.join(directory, entry.name);
                if (entry.isDirectory?.()) pending.push(fullPath);
                else if (entry.isFile?.() && /\.json$/i.test(entry.name)) files.push(fullPath);
            }
        }
        return files.sort((a, b) => String(a).localeCompare(String(b)));
    }

    function linkedBehaviorPackRoot(fileSystem, pathModule, resourcePackRoot) {
        const resourceManifest = readPackJson(fileSystem, pathModule.join(resourcePackRoot, 'manifest.json'));
        const resourceUuid = String(resourceManifest?.header?.uuid || '').toLowerCase();
        if (!resourceUuid) return null;

        const parent = pathModule.dirname(resourcePackRoot);
        const grandParent = pathModule.dirname(parent);
        const parentName = pathModule.basename(parent).toLowerCase();
        const rootName = pathModule.basename(resourcePackRoot).toLowerCase();
        const searchRoots = new Set();
        if (parentName === 'resource_packs') searchRoots.add(pathModule.join(grandParent, 'behavior_packs'));
        if (parentName === 'development_resource_packs') searchRoots.add(pathModule.join(grandParent, 'development_behavior_packs'));
        if (rootName === 'resource_pack') {
            searchRoots.add(pathModule.join(parent, 'behavior_pack'));
            searchRoots.add(pathModule.join(parent, 'behavior_packs'));
        }
        searchRoots.add(pathModule.join(parent, 'behavior_pack'));
        searchRoots.add(pathModule.join(parent, 'behavior_packs'));
        searchRoots.add(pathModule.join(parent, 'development_behavior_packs'));

        const packCandidates = [];
        for (const searchRoot of searchRoots) {
            if (!fileSystem.existsSync(searchRoot)) continue;
            const directManifest = pathModule.join(searchRoot, 'manifest.json');
            if (fileSystem.existsSync(directManifest)) packCandidates.push(searchRoot);
            let children = [];
            try { children = fileSystem.readdirSync(searchRoot, {withFileTypes: true}); } catch { continue; }
            children.sort((a, b) => String(a.name).localeCompare(String(b.name)));
            for (const entry of children) {
                if (!entry.isDirectory?.()) continue;
                const candidate = pathModule.join(searchRoot, entry.name);
                if (fileSystem.existsSync(pathModule.join(candidate, 'manifest.json'))) packCandidates.push(candidate);
            }
        }

        for (const candidate of Array.from(new Set(packCandidates)).sort((a, b) => String(a).localeCompare(String(b)))) {
            const manifest = readPackJson(fileSystem, pathModule.join(candidate, 'manifest.json'));
            const dependencies = Array.isArray(manifest?.dependencies) ? manifest.dependencies : [];
            if (dependencies.some(entry => String(entry?.uuid || '').toLowerCase() === resourceUuid)) return candidate;
        }
        return null;
    }

    function buildBedrockCustomGeometryIndex(fileSystem, pathModule, resourcePackRoot) {
        const behaviorPackRoot = linkedBehaviorPackRoot(fileSystem, pathModule, resourcePackRoot);
        const blockDefinitions = new Map();
        const geometries = new Map();
        const diagnostics = {behaviorPackRoot, duplicateBlocks: 0, duplicateGeometries: 0, malformed: 0};

        if (behaviorPackRoot) {
            for (const filePath of bedrockJsonFiles(fileSystem, pathModule, pathModule.join(behaviorPackRoot, 'blocks'))) {
                const parsed = readPackJson(fileSystem, filePath);
                const block = parsed?.['minecraft:block'];
                const identifier = block?.description?.identifier;
                if (typeof identifier !== 'string' || !identifier) continue;
                if (blockDefinitions.has(identifier)) diagnostics.duplicateBlocks++;
                blockDefinitions.set(identifier, {definition: block, filePath});
            }
        }

        for (const filePath of bedrockJsonFiles(fileSystem, pathModule, pathModule.join(resourcePackRoot, 'models', 'blocks'))) {
            const parsed = readPackJson(fileSystem, filePath);
            const list = parsed?.['minecraft:geometry'];
            if (!Array.isArray(list)) continue;
            for (const geometry of list) {
                const identifier = geometry?.description?.identifier;
                if (typeof identifier !== 'string' || !identifier) continue;
                if (geometries.has(identifier)) diagnostics.duplicateGeometries++;
                geometries.set(identifier, {geometry, filePath});
            }
        }
        return {behaviorPackRoot, blockDefinitions, geometries, diagnostics};
    }

    function bedrockStateValue(states, key) {
        if (!states || typeof states !== 'object') return undefined;
        if (Object.prototype.hasOwnProperty.call(states, key)) return states[key];
        const bare = String(key || '').replace(/^.*:/, '');
        if (Object.prototype.hasOwnProperty.call(states, bare)) return states[bare];
        const namespaced = `minecraft:${bare}`;
        if (Object.prototype.hasOwnProperty.call(states, namespaced)) return states[namespaced];
        return undefined;
    }

    function bedrockConditionLiteral(text) {
        const value = String(text || '').trim();
        if ((value.startsWith("'") && value.endsWith("'")) || (value.startsWith('"') && value.endsWith('"'))) {
            return value.slice(1, -1).replace(/\\(['"\\])/g, '$1');
        }
        if (/^(true|false)$/i.test(value)) return value.toLowerCase() === 'true';
        if (/^null$/i.test(value)) return null;
        if (/^[-+]?(?:\d+\.?\d*|\.\d+)$/.test(value)) return Number(value);
        return undefined;
    }

    function stripBedrockConditionParens(expression) {
        let text = String(expression || '').trim();
        while (text.startsWith('(') && text.endsWith(')')) {
            let depth = 0;
            let quote = '';
            let encloses = true;
            for (let index = 0; index < text.length; index++) {
                const char = text[index];
                if (quote) {
                    if (char === '\\') index++;
                    else if (char === quote) quote = '';
                    continue;
                }
                if (char === "'" || char === '"') { quote = char; continue; }
                if (char === '(') depth++;
                else if (char === ')') depth--;
                if (depth === 0 && index < text.length - 1) { encloses = false; break; }
            }
            if (!encloses) break;
            text = text.slice(1, -1).trim();
        }
        return text;
    }

    function bedrockTopLevelOperator(expression, operator) {
        let depth = 0;
        let quote = '';
        for (let index = 0; index <= expression.length - operator.length; index++) {
            const char = expression[index];
            if (quote) {
                if (char === '\\') index++;
                else if (char === quote) quote = '';
                continue;
            }
            if (char === "'" || char === '"') { quote = char; continue; }
            if (char === '(') { depth++; continue; }
            if (char === ')') { depth--; continue; }
            if (depth === 0 && expression.slice(index, index + operator.length) === operator) return index;
        }
        return -1;
    }

    function evaluateBedrockStateCondition(expression, states, unsupported = null) {
        if (expression === true || expression === false) return expression;
        let text = stripBedrockConditionParens(expression);
        if (!text) return false;
        for (const operator of ['||', '&&']) {
            const index = bedrockTopLevelOperator(text, operator);
            if (index >= 0) {
                const left = text.slice(0, index);
                const right = text.slice(index + operator.length);
                return operator === '||'
                    ? evaluateBedrockStateCondition(left, states, unsupported) || evaluateBedrockStateCondition(right, states, unsupported)
                    : evaluateBedrockStateCondition(left, states, unsupported) && evaluateBedrockStateCondition(right, states, unsupported);
            }
        }
        if (text.startsWith('!') && text[1] !== '=') return !evaluateBedrockStateCondition(text.slice(1), states, unsupported);
        const stateCall = '(?:q|query)\\.block_state\\(\\s*([\'\"])([^\'\"]+)\\1\\s*\\)';
        const comparison = text.match(new RegExp(`^${stateCall}\\s*(==|!=|<=|>=|<|>)\\s*(.+)$`, 'i'));
        if (comparison) {
            const actual = bedrockStateValue(states, comparison[2]);
            const expected = bedrockConditionLiteral(comparison[4]);
            if (expected === undefined) { unsupported?.add?.('permutation_condition'); return false; }
            switch (comparison[3]) {
                case '==': return actual == expected;
                case '!=': return actual != expected;
                case '<': return actual < expected;
                case '<=': return actual <= expected;
                case '>': return actual > expected;
                case '>=': return actual >= expected;
            }
        }
        const direct = text.match(new RegExp(`^${stateCall}$`, 'i'));
        if (direct) return Boolean(bedrockStateValue(states, direct[2]));
        unsupported?.add?.('permutation_condition');
        return false;
    }

    function effectiveBedrockBlockComponents(blockDefinition, states, unsupported = null) {
        const components = {...(blockDefinition?.components || {})};
        for (const permutation of Array.isArray(blockDefinition?.permutations) ? blockDefinition.permutations : []) {
            if (!evaluateBedrockStateCondition(permutation?.condition, states, unsupported)) continue;
            Object.assign(components, permutation?.components || {});
        }
        return components;
    }

    function rotateBedrockPoint(point, pivot, rotation) {
        const result = [point[0] - pivot[0], point[1] - pivot[1], point[2] - pivot[2]];
        const angles = Array.isArray(rotation) ? rotation : [0, 0, 0];
        for (let axis = 0; axis < 3; axis++) {
            const radians = (Number(angles[axis]) || 0) * Math.PI / 180;
            if (!radians) continue;
            const sine = Math.sin(radians);
            const cosine = Math.cos(radians);
            if (axis === 0) {
                const y = result[1] * cosine - result[2] * sine;
                const z = result[1] * sine + result[2] * cosine;
                result[1] = y; result[2] = z;
            } else if (axis === 1) {
                const x = result[0] * cosine + result[2] * sine;
                const z = -result[0] * sine + result[2] * cosine;
                result[0] = x; result[2] = z;
            } else {
                const x = result[0] * cosine - result[1] * sine;
                const y = result[0] * sine + result[1] * cosine;
                result[0] = x; result[1] = y;
            }
        }
        return [result[0] + pivot[0], result[1] + pivot[1], result[2] + pivot[2]];
    }

    function bedrockCubeFaceVertices(from, to, face) {
        const [x1,y1,z1] = from;
        const [x2,y2,z2] = to;
        if (face === 'north') return [[x1,y1,z1],[x2,y1,z1],[x2,y2,z1],[x1,y2,z1]];
        if (face === 'south') return [[x2,y1,z2],[x1,y1,z2],[x1,y2,z2],[x2,y2,z2]];
        if (face === 'west') return [[x1,y1,z2],[x1,y1,z1],[x1,y2,z1],[x1,y2,z2]];
        if (face === 'east') return [[x2,y1,z1],[x2,y1,z2],[x2,y2,z2],[x2,y2,z1]];
        if (face === 'down') return [[x1,y1,z1],[x1,y1,z2],[x2,y1,z2],[x2,y1,z1]];
        return [[x1,y2,z2],[x1,y2,z1],[x2,y2,z1],[x2,y2,z2]];
    }

    function bedrockBoxUvRect(face, uv, size) {
        const u = Number(uv?.[0]) || 0;
        const v = Number(uv?.[1]) || 0;
        const x = Number(size?.[0]) || 0;
        const y = Number(size?.[1]) || 0;
        const z = Number(size?.[2]) || 0;
        if (face === 'east') return [u, v + z, z, y];
        if (face === 'north') return [u + z, v + z, x, y];
        if (face === 'west') return [u + z + x, v + z, z, y];
        if (face === 'south') return [u + z * 2 + x, v + z, x, y];
        if (face === 'up') return [u + z + x, v + z, -x, -z];
        return [u + z + x * 2, v, -x, z];
    }

    function bedrockFaceUvSize(face, size) {
        if (face === 'east' || face === 'west') return [Number(size?.[2]) || 0, Number(size?.[1]) || 0];
        if (face === 'north' || face === 'south') return [Number(size?.[0]) || 0, Number(size?.[1]) || 0];
        return [Number(size?.[0]) || 0, Number(size?.[2]) || 0];
    }

    function bedrockFaceUvs(face, rect, textureWidth, textureHeight, rotation = 0, mirror = false) {
        const [u, v, du, dv] = rect.map(value => Number(value) || 0);
        const corners = {
            tl: [u, v], tr: [u + du, v], br: [u + du, v + dv], bl: [u, v + dv],
        };
        let ordered = (face === 'up' || face === 'down')
            ? [corners.bl, corners.tl, corners.tr, corners.br]
            : [corners.br, corners.bl, corners.tl, corners.tr];
        if (mirror) {
            ordered = ordered.map(([px, py]) => [u + du - (px - u), py]);
        }
        const turns = ((Math.round((Number(rotation) || 0) / 90) % 4) + 4) % 4;
        if (turns) ordered = ordered.slice(4 - turns).concat(ordered.slice(0, 4 - turns));
        const width = Math.max(1, Number(textureWidth) || 16);
        const height = Math.max(1, Number(textureHeight) || 16);
        return ordered.map(([px, py]) => [px / width, 1 - py / height]);
    }

    function applyBedrockBlockTransformation(point, transformation, unsupported = null) {
        if (!transformation || typeof transformation !== 'object') return point;
        const result = point.slice();
        const center = [8, 8, 8];
        const scale = Array.isArray(transformation.scale) ? transformation.scale.map(Number) : [1, 1, 1];
        const scalePivotRaw = Array.isArray(transformation.scale_pivot) ? transformation.scale_pivot : [0, 0, 0];
        const scalePivot = center.map((value, axis) => value + (Number(scalePivotRaw[axis]) || 0) * 16);
        for (let axis = 0; axis < 3; axis++) result[axis] = scalePivot[axis] + (result[axis] - scalePivot[axis]) * (Number.isFinite(scale[axis]) ? scale[axis] : 1);
        const rotationPivotRaw = Array.isArray(transformation.rotation_pivot) ? transformation.rotation_pivot : [0, 0, 0];
        const rotationPivot = center.map((value, axis) => value + (Number(rotationPivotRaw[axis]) || 0) * 16);
        const rotated = rotateBedrockPoint(result, rotationPivot, transformation.rotation || [0,0,0]);
        const translation = Array.isArray(transformation.translation) ? transformation.translation : [0,0,0];
        for (let axis = 0; axis < 3; axis++) rotated[axis] += (Number(translation[axis]) || 0) * 16;
        if (transformation.rotation && !Array.isArray(transformation.rotation)) unsupported?.add?.('transformation_rotation');
        return rotated;
    }

    function compileBedrockGeometryShape(geometry, options = {}) {
        if (!geometry || typeof geometry !== 'object') return null;
        const unsupported = options.unsupported || new Set();
        const description = geometry.description || {};
        const geometryIdentifier = String(description.identifier || options.geometryIdentifier || 'geometry.unknown');
        const textureWidth = Math.max(1, Number(description.texture_width) || 16);
        const textureHeight = Math.max(1, Number(description.texture_height) || 16);
        const bones = Array.isArray(geometry.bones) ? geometry.bones : [];
        const boneMap = new Map(bones.map(bone => [String(bone?.name || ''), bone]));
        const geometryComponent = options.geometryComponent && typeof options.geometryComponent === 'object'
            ? options.geometryComponent
            : {};
        const hiddenBones = new Set();
        if (geometryComponent.bone_visibility && typeof geometryComponent.bone_visibility === 'object') {
            for (const [boneName, visible] of Object.entries(geometryComponent.bone_visibility)) {
                if (visible === false) hiddenBones.add(boneName);
                else if (visible !== true) unsupported.add('bone_visibility_expression');
            }
        }
        for (const key of ['culling','culling_layer','culling_shape','n_way_visual_rotation']) {
            if (geometryComponent[key] != null) unsupported.add(key);
        }
        if (geometryComponent.uv_lock === true || Array.isArray(geometryComponent.uv_lock)) unsupported.add('uv_lock');

        const boneChain = bone => {
            const result = [];
            const seen = new Set();
            let current = bone;
            while (current) {
                const name = String(current.name || '');
                if (seen.has(name)) { unsupported.add('bone_parent_cycle'); break; }
                seen.add(name);
                result.push(current);
                if (!current.parent) break;
                current = boneMap.get(String(current.parent));
                if (!current) { unsupported.add('missing_bone_parent'); break; }
            }
            return result;
        };
        const hiddenByHierarchy = bone => boneChain(bone).some(entry => hiddenBones.has(String(entry.name || '')));
        const transformPoint = (point, cube, bone) => {
            let transformed = point.slice();
            if (Array.isArray(cube?.rotation) && cube.rotation.some(value => Number(value))) {
                // Bedrock cubes rotate around their uninflated cube center when no
                // explicit cube pivot is present. Using world/model origin here
                // displaced asymmetric rotated cubes, especially when inflate was
                // also applied to the rendered bounds.
                const pivot = Array.isArray(cube.pivot)
                    ? cube.pivot.map(Number)
                    : [0, 1, 2].map(axis => (
                        (Number(cube.origin?.[axis]) || 0)
                        + (Number(cube.size?.[axis]) || 0) / 2
                    ));
                transformed = rotateBedrockPoint(transformed, pivot, cube.rotation);
            }
            for (const entry of boneChain(bone)) {
                if (!Array.isArray(entry?.rotation) || !entry.rotation.some(value => Number(value))) continue;
                transformed = rotateBedrockPoint(transformed, Array.isArray(entry.pivot) ? entry.pivot.map(Number) : [0,0,0], entry.rotation);
            }
            transformed = [transformed[0] + 8, transformed[1], transformed[2] + 8];
            return applyBedrockBlockTransformation(transformed, options.transformation, unsupported);
        };

        const quads = [];
        for (const bone of bones) {
            if (!bone || hiddenByHierarchy(bone)) continue;
            if (bone.poly_mesh) unsupported.add('poly_mesh');
            if (bone.texture_meshes) unsupported.add('texture_meshes');
            const cubes = Array.isArray(bone.cubes) ? bone.cubes : [];
            for (const cube of cubes) {
                if (!Array.isArray(cube?.origin) || !Array.isArray(cube?.size)) { unsupported.add('invalid_cube'); continue; }
                const inflate = Number(cube.inflate ?? bone.inflate ?? 0) || 0;
                const origin = cube.origin.map(Number);
                const size = cube.size.map(Number);
                const from = [origin[0] - inflate, origin[1] - inflate, origin[2] - inflate];
                const to = [origin[0] + size[0] + inflate, origin[1] + size[1] + inflate, origin[2] + size[2] + inflate];
                const mirror = cube.mirror === undefined ? bone.mirror === true : cube.mirror === true;
                const perFaceUv = cube.uv && !Array.isArray(cube.uv) && typeof cube.uv === 'object' ? cube.uv : null;
                for (const face of SHAPE_FACE_NAMES) {
                    let rect;
                    let materialInstance = face;
                    let uvRotation = 0;
                    if (perFaceUv) {
                        const faceUv = perFaceUv[face];
                        if (faceUv == null) continue;
                        if (Array.isArray(faceUv)) {
                            const uvSize = bedrockFaceUvSize(face, size);
                            rect = [faceUv[0], faceUv[1], uvSize[0], uvSize[1]];
                        } else if (typeof faceUv === 'object' && Array.isArray(faceUv.uv)) {
                            const uvSize = Array.isArray(faceUv.uv_size) ? faceUv.uv_size : bedrockFaceUvSize(face, size);
                            rect = [faceUv.uv[0], faceUv.uv[1], uvSize[0], uvSize[1]];
                            materialInstance = faceUv.material_instance || face;
                            uvRotation = faceUv.uv_rotation || 0;
                        } else {
                            unsupported.add('invalid_face_uv');
                            continue;
                        }
                    } else {
                        rect = bedrockBoxUvRect(face, Array.isArray(cube.uv) ? cube.uv : [0,0], size);
                    }
                    const vertices = bedrockCubeFaceVertices(from, to, face).map(point => transformPoint(point, cube, bone));
                    quads.push({
                        face,
                        materialInstance,
                        doubleSided: false,
                        vertices,
                        uvs: bedrockFaceUvs(face, rect, textureWidth, textureHeight, uvRotation, mirror),
                    });
                }
            }
        }
        return {
            key: `resource_pack_geometry:${geometryIdentifier}`,
            boxes: [],
            quads,
            occludes: false,
            approximate: unsupported.size > 0,
            source: 'resource_pack_geometry',
            unsupported: Array.from(unsupported).sort(),
        };
    }

    function ensureFlipbookAnimationTimer() {
        if (flipbookAnimationTimer || !activeFlipbookAnimations.size) return;
        flipbookAnimationTimer = setInterval(() => {
            if (!activeFlipbookAnimations.size) {
                clearInterval(flipbookAnimationTimer);
                flipbookAnimationTimer = null;
                return;
            }
            const now = typeof performance !== 'undefined' ? performance.now() : Date.now();
            let frameChanged = false;
            for (const animation of Array.from(activeFlipbookAnimations)) {
                try { frameChanged = animation.update(now) || frameChanged; }
                catch (error) {
                    activeFlipbookAnimations.delete(animation);
                    warnOnce('flipbook animation', error);
                }
            }
            if (frameChanged) {
                const previews = Array.isArray(window.Preview?.all) ? Preview.all : [window.Preview?.selected].filter(Boolean);
                previews.forEach(preview => preview?.render?.());
                window.LightManagerMarkShadowsDirty?.({scene: true});
                if (window.LightflowAnimationRuntime) {
                    window.LightflowAnimationRuntime.sceneMotionEpoch = (Number(window.LightflowAnimationRuntime.sceneMotionEpoch) || 0) + 1;
                }
            }
        }, 50);
    }

    function createResourcePackResolver(selectedPath) {
        if (typeof require !== 'function') {
            throw new Error(tr(
                'bedrock_structure.message.pack_desktop',
                'Resource-pack folder loading is available in Blockbench Desktop.'
            ));
        }
        const fileSystem = require('node:fs');
        const pathModule = require('node:path');
        const rootPath = normalizeResourcePackRoot(fileSystem, pathModule, selectedPath);
        const terrainPath = pathModule.join(rootPath, 'textures', 'terrain_texture.json');
        const terrain = readPackJson(fileSystem, terrainPath) || {};
        const blocks = readPackJson(fileSystem, pathModule.join(rootPath, 'blocks.json')) || {};
        const flipbooks = readPackJson(fileSystem, pathModule.join(rootPath, 'textures', 'flipbook_textures.json')) || [];
        const biomesClient = readPackJson(fileSystem, pathModule.join(rootPath, 'biomes_client.json')) || {};
        const textureData = terrain.texture_data || {};
        const customGeometryIndex = buildBedrockCustomGeometryIndex(fileSystem, pathModule, rootPath);
        const customBlockContextCache = new Map();
        const customShapeCache = new Map();
        const customMaterialDescriptorCache = new Map();
        const customUnsupportedFeatures = new Set();
        const customGeometryDiagnostics = new Map();
        const textureCache = new Map();
        const resolvedFileCache = new Map();
        const blockDefinitionCache = new Map();
        const clientBiomeComponentsCache = new Map();
        const faceDescriptorCache = new Map();
        const heldTextures = new Set();
        const resolverDiagnostics = {
            fileChecks: 0, fileCacheHits: 0, fileCacheMisses: 0,
            definitionCacheHits: 0, definitionCacheMisses: 0,
            faceCacheHits: 0, faceCacheMisses: 0, atlasUploads: 0,
        };
        const textureSetCache = new Map();
        const materialCache = new Map();
        const layeredTextureCache = new Map();
        const decodedImageCanvasCache = new WeakMap();
        const textureReadyQueues = new WeakMap();
        // V2.0.4: block faces no longer depend on a material color multiplier for
        // biome tint. Static appearances are baked into shared texture-atlas pages
        // so grass/foliage cannot collapse to black while Blockbench textures are
        // still loading or while a PBR material interprets tint differently.
        const atlasEntryCache = new Map();
        const atlasPagesByMode = new Map();
        const atlasPages = new Set();
        const animationEntries = new Set();
        let disposed = false;
        const ownedDerivedTextures = new Set();
        const aliases = {
            grass_block: ['grass'],
            oak_planks: ['planks_oak'],
            spruce_planks: ['planks_spruce'],
            birch_planks: ['planks_birch'],
            jungle_planks: ['planks_jungle'],
            acacia_planks: ['planks_acacia'],
            dark_oak_planks: ['planks_big_oak'],
        };
        // Partial packs (Vanilla RTX derivatives and similar PBR projects) often
        // omit vanilla entries from blocks.json and terrain_texture.json while
        // still shipping the vanilla texture files. Blocks whose textures are not
        // named after the block id (grass_block -> grass_side/grass_top/dirt)
        // cannot fall back by filename, so resolve them from vanilla's physical
        // layout before giving up.
        const vanillaGrassDefinition = {
            sound: 'grass',
            isotropic: {down: true, up: true},
            textures: {
                down: 'textures/blocks/dirt',
                side: 'textures/blocks/grass_side',
                up: 'textures/blocks/grass_top',
            },
        };
        const vanillaFilePathDefinitions = Object.freeze({
            grass_block: vanillaGrassDefinition,
            grass: vanillaGrassDefinition,
            mycelium: {
                sound: 'grass',
                isotropic: {down: true, up: true},
                textures: {
                    down: 'textures/blocks/dirt',
                    side: 'textures/blocks/mycelium_side',
                    up: 'textures/blocks/mycelium_top',
                },
            },
            podzol: {
                sound: 'gravel',
                textures: {
                    down: 'textures/blocks/dirt',
                    side: 'textures/blocks/dirt_podzol_side',
                    up: 'textures/blocks/dirt_podzol_top',
                },
            },
            grass_path: {
                sound: 'grass',
                textures: {
                    down: 'textures/blocks/dirt',
                    side: 'textures/blocks/grass_path_side',
                    up: 'textures/blocks/grass_path_top',
                },
            },
            dirt_path: {
                sound: 'grass',
                textures: {
                    down: 'textures/blocks/dirt',
                    side: 'textures/blocks/dirt_path_side',
                    up: 'textures/blocks/dirt_path_top',
                },
            },
            melon_block: {
                sound: 'wood',
                textures: {
                    down: 'textures/blocks/melon_top',
                    side: 'textures/blocks/melon_side',
                    up: 'textures/blocks/melon_top',
                },
            },
            pumpkin: {
                sound: 'wood',
                isotropic: {down: true, up: true},
                textures: {
                    down: 'textures/blocks/pumpkin_top',
                    side: 'textures/blocks/pumpkin_side',
                    up: 'textures/blocks/pumpkin_top',
                },
            },
            hay_block: {
                sound: 'grass',
                isotropic: {down: true, up: true},
                textures: {
                    down: 'textures/blocks/hay_block_top',
                    side: 'textures/blocks/hay_block_side',
                    up: 'textures/blocks/hay_block_top',
                },
            },
            oak_leaves: {textures: 'leaves_oak'},
            spruce_leaves: {textures: 'leaves_spruce'},
            birch_leaves: {textures: 'leaves_birch'},
            jungle_leaves: {textures: 'leaves_jungle'},
            acacia_leaves: {textures: 'leaves_acacia'},
            dark_oak_leaves: {textures: 'leaves_big_oak'},
        });
        // Historical Bedrock texture names still shipped by many packs. Used to
        // derive extra file candidates when a pack omits the JSON metadata.
        const legacyTextureNameMap = Object.freeze({
            oak_log: 'log_oak',
            spruce_log: 'log_spruce',
            birch_log: 'log_birch',
            jungle_log: 'log_jungle',
            acacia_log: 'log_acacia',
            dark_oak_log: 'log_big_oak',
            oak_planks: 'planks_oak',
            spruce_planks: 'planks_spruce',
            birch_planks: 'planks_birch',
            jungle_planks: 'planks_jungle',
            acacia_planks: 'planks_acacia',
            dark_oak_planks: 'planks_big_oak',
            dirt_path: 'grass_path',
        });
        const flipbookByAtlasTile = new Map();
        const flipbookByPath = new Map();
        for (const entry of Array.isArray(flipbooks) ? flipbooks : []) {
            if (entry?.atlas_tile) flipbookByAtlasTile.set(String(entry.atlas_tile), entry);
            if (entry?.flipbook_texture) {
                flipbookByPath.set(String(entry.flipbook_texture).replace(/\.(png|tga)$/i, ''), entry);
            }
        }

        function resolveFile(reference) {
            if (!reference) return null;
            const normalized = String(reference).replace(/\\/g, '/').replace(/\.(png|tga)$/i, '').replace(/^\.\//, '');
            if (resolvedFileCache.has(normalized)) {
                resolverDiagnostics.fileCacheHits++;
                return resolvedFileCache.get(normalized);
            }
            resolverDiagnostics.fileCacheMisses++;
            const relatives = normalized.startsWith('textures/')
                ? [normalized]
                : [
                    `textures/${normalized}`,
                    `textures/blocks/${normalized}`,
                    `textures/block/${normalized}`,
                ];
            for (const relative of relatives) {
                for (const extension of ['.png', '.tga']) {
                    const candidate = pathModule.join(rootPath, ...relative.split('/')) + extension;
                    resolverDiagnostics.fileChecks++;
                    if (fileSystem.existsSync(candidate)) {
                        resolvedFileCache.set(normalized, candidate);
                        return candidate;
                    }
                }
            }
            resolvedFileCache.set(normalized, null);
            return null;
        }

        function getTexture(filePath) {
            if (!filePath) return null;
            const normalized = pathModule.normalize(filePath).toLowerCase();
            if (textureCache.has(normalized)) return textureCache.get(normalized);
            const key = `pack:${normalized}`;
            let texture = Texture.all.find(entry => entry.mcstructure_texture_key === key);
            if (!texture) {
                texture = new Texture({
                    name: pathModule.basename(filePath),
                    folder: 'bedrock_resource_pack',
                    mcstructure_texture_key: key,
                });
                texture.fromPath(filePath).add(false);
                texture.saved = true;
                texture.mcstructure_resource_pack_owned = true;
            }
            if (!heldTextures.has(texture)) {
                heldTextures.add(texture);
                resourcePackTextureReferences.set(texture, (resourcePackTextureReferences.get(texture) || 0) + 1);
            }
            textureCache.set(normalized, texture);
            return texture;
        }

        function readTextureSetForFile(filePath) {
            if (!filePath) return null;
            const setPath = String(filePath).replace(/\.(png|tga)$/i, '.texture_set.json');
            const key = pathModule.normalize(setPath).toLowerCase();
            if (textureSetCache.has(key)) return textureSetCache.get(key);
            const parsed = readPackJson(fileSystem, setPath);
            const textureSet = parsed?.['minecraft:texture_set'] || null;
            textureSetCache.set(key, textureSet);
            return textureSet;
        }

        function resolveTextureSetFile(baseFilePath, reference) {
            if (typeof reference !== 'string' || !reference) return null;
            const normalized = reference.replace(/\\/g, '/').replace(/\.(png|tga)$/i, '');
            if (normalized.startsWith('textures/')) return resolveFile(normalized);
            const baseDirectory = pathModule.dirname(baseFilePath);
            for (const extension of ['.png', '.tga']) {
                const sameDirectory = pathModule.join(baseDirectory, normalized) + extension;
                if (fileSystem.existsSync(sameDirectory)) return sameDirectory;
            }
            return resolveFile(normalized);
        }

        function ownedCanvasTexture(canvas) {
            const texture = typeof THREE.CanvasTexture === 'function'
                ? new THREE.CanvasTexture(canvas)
                : new THREE.Texture(canvas);
            texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
            texture.magFilter = texture.minFilter = THREE.NearestFilter;
            texture.needsUpdate = true;
            ownedDerivedTextures.add(texture);
            return texture;
        }

        function textureCanvas(texture) {
            if (!texture) return null;

            // Blockbench Texture allocates a transparent placeholder canvas before
            // fromPath() has decoded the real image. `texture.width` may already be
            // 16 at that point, so it is NOT a reliable readiness signal. In 2.1.0
            // that placeholder could be copied into the structure atlas, mark the
            // atlas entry as ready, and permanently turn every face using that tile
            // into an alpha-zero hole. Prefer the decoded image whenever a BB image
            // exists and only fall back to texture.canvas for texture-like objects
            // that do not have an asynchronous image source.
            const image = texture.img || texture.image || texture.getOwnMaterial?.()?.map?.image || null;
            if (texture.img) {
                const naturalWidth = Number(texture.img.naturalWidth || texture.img.videoWidth || 0);
                const naturalHeight = Number(texture.img.naturalHeight || texture.img.videoHeight || 0);
                const complete = texture.img.complete === undefined ? true : texture.img.complete === true;
                if (!complete || naturalWidth < 1 || naturalHeight < 1) return null;
            }

            if (image && typeof document !== 'undefined') {
                const cachedCanvas = (typeof image === 'object' && image) ? decodedImageCanvasCache.get(image) : null;
                if (cachedCanvas) return cachedCanvas;
                const width = Number(image.naturalWidth || image.videoWidth || image.width || 0);
                const height = Number(image.naturalHeight || image.videoHeight || image.height || 0);
                if (width > 0 && height > 0) {
                    const canvas = document.createElement('canvas');
                    canvas.width = width;
                    canvas.height = height;
                    const ctx = canvas.getContext('2d', {willReadFrequently: true});
                    if (!ctx) return null;
                    ctx.imageSmoothingEnabled = false;
                    try {
                        ctx.drawImage(image, 0, 0, width, height);
                        if (typeof image === 'object' && image) decodedImageCanvasCache.set(image, canvas);
                        return canvas;
                    } catch {
                        return null;
                    }
                }
            }

            // Derived synchronous texture-like objects (layered/tint canvases) do
            // not necessarily expose an HTMLImageElement; their canvas is already
            // authoritative and safe to consume immediately.
            if (!texture.img && texture.canvas?.width && texture.canvas?.height) return texture.canvas;
            return null;
        }

        function scheduleTextureReady(texture, callback) {
            if (!texture || typeof callback !== 'function') return;
            const immediate = textureCanvas(texture);
            if (immediate) {
                callback(immediate);
                return;
            }
            let state = textureReadyQueues.get(texture);
            if (!state) {
                state = {callbacks: new Set(), finished: false, armed: false};
                textureReadyQueues.set(texture, state);
            }
            state.callbacks.add(callback);
            if (state.armed || state.finished) return;
            state.armed = true;
            const run = () => {
                if (state.finished || disposed) return;
                const canvas = textureCanvas(texture);
                if (!canvas) return;
                state.finished = true;
                const callbacks = Array.from(state.callbacks);
                state.callbacks.clear();
                for (const pending of callbacks) {
                    try { pending(canvas); } catch (error) { warnOnce('texture ready callback', error); }
                }
            };
            const image = texture?.img || texture?.image || texture?.getOwnMaterial?.()?.map?.image;
            if (image?.addEventListener) image.addEventListener('load', run, {once: true});
            // One retry schedule per texture, regardless of how many atlas/material
            // consumers are waiting for it. This avoids thousands of duplicate timers.
            for (const delay of [0, 50, 200, 750, 1500, 3000, 6000]) setTimeout(run, delay);
        }


        function normalizeTintHex(value) {
            try {
                const color = new THREE.Color(value || '#ffffff');
                return {
                    css: `#${color.getHexString()}`,
                    rgb: [
                        Math.round(color.r * 255),
                        Math.round(color.g * 255),
                        Math.round(color.b * 255),
                    ],
                };
            } catch {
                return {css: '#ffffff', rgb: [255, 255, 255]};
            }
        }

        function makeLayeredTintTexture(baseTexture, overlayTexture, tint, cacheKey) {
            if (!baseTexture || !overlayTexture || typeof document === 'undefined') return null;
            const normalizedTint = normalizeTintHex(tint);
            const key = `${cacheKey}|${normalizedTint.css}`;
            if (layeredTextureCache.has(key)) return layeredTextureCache.get(key);

            const canvas = document.createElement('canvas');
            canvas.width = canvas.height = 16;
            const map = ownedCanvasTexture(canvas);
            map.name = `Bedrock layered ${cacheKey}`;
            const textureLike = {
                uuid: `bedrock-layered:${hashString(key).toString(16)}`,
                name: `layered:${cacheKey}`,
                canvas,
                getOwnMaterial() { return {map}; },
                getMaterial() { return {map}; },
            };
            layeredTextureCache.set(key, textureLike);

            const render = () => {
                const baseCanvas = textureCanvas(baseTexture);
                const overlayCanvas = textureCanvas(overlayTexture);
                if (!baseCanvas || !overlayCanvas) return false;
                const width = overlayCanvas.width || baseCanvas.width || 16;
                const height = overlayCanvas.height || baseCanvas.height || 16;
                canvas.width = width;
                canvas.height = height;
                const ctx = canvas.getContext('2d', {willReadFrequently: true});
                if (!ctx) return false;
                ctx.imageSmoothingEnabled = false;
                ctx.clearRect(0, 0, width, height);
                // Layer 0: grass_side_carried. This is the complete carried side
                // (dirt/body) and is intentionally *not* tinted.
                ctx.globalCompositeOperation = 'source-over';
                ctx.globalAlpha = 1;
                ctx.drawImage(baseCanvas, 0, 0, width, height);

                const overlayWork = document.createElement('canvas');
                overlayWork.width = width;
                overlayWork.height = height;
                const overlayCtx = overlayWork.getContext('2d', {willReadFrequently: true});
                if (!overlayCtx) return false;
                overlayCtx.imageSmoothingEnabled = false;
                overlayCtx.drawImage(overlayCanvas, 0, 0, width, height);
                overlayCtx.globalCompositeOperation = 'multiply';
                overlayCtx.fillStyle = normalizedTint.css;
                overlayCtx.fillRect(0, 0, width, height);
                overlayCtx.globalCompositeOperation = 'destination-in';
                overlayCtx.drawImage(overlayCanvas, 0, 0, width, height);
                overlayCtx.globalCompositeOperation = 'source-over';

                // Layer 1: grass_side itself. Preserve its source alpha, tint
                // only its visible pixels, and composite over the carried base.
                // The final alpha therefore comes from the underlay wherever the
                // overlay is transparent; transparent grass pixels are never a
                // hole through the block face.
                ctx.globalCompositeOperation = 'source-over';
                ctx.globalAlpha = 1;
                ctx.drawImage(overlayWork, 0, 0);
                map.needsUpdate = true;
                return true;
            };

            if (!render()) {
                scheduleTextureReady(baseTexture, render);
                scheduleTextureReady(overlayTexture, render);
            }
            return textureLike;
        }

        function grassSideBaseTexture() {
            // Vanilla Bedrock keeps this file as a physical texture even though
            // it is not exposed as a terrain_texture alias. It is the *underlay*
            // for the alpha-only grass_side overlay and must not receive biome
            // tint. Resolve the file directly from textures/blocks.
            const exactReference = 'textures/blocks/grass_side_carried';
            const exactPath = resolveFile(exactReference);
            if (exactPath) {
                const texture = getTexture(exactPath);
                if (texture) return {texture, filePath: exactPath, reference: exactReference, exact: true};
            }

            // Custom packs may omit the carried texture. Keep a conservative
            // fallback so the face never turns into a transparent hole, while
            // making it explicit that vanilla uses grass_side_carried.
            for (const reference of ['textures/blocks/dirt', 'blocks/dirt', 'dirt']) {
                const filePath = resolveFile(reference);
                if (!filePath) continue;
                const texture = getTexture(filePath);
                if (texture) return {texture, filePath, reference, exact: false};
            }
            return null;
        }

        function extractChannelTexture(sourceCanvas, channel, colorCanvas = null, emissive = false) {
            if (!sourceCanvas || typeof document === 'undefined') return null;
            const width = sourceCanvas.width;
            const height = sourceCanvas.height;
            if (!width || !height) return null;
            const source = sourceCanvas.getContext('2d', {willReadFrequently: true})?.getImageData(0, 0, width, height);
            if (!source) return null;
            let color = null;
            if (emissive && colorCanvas) {
                const colorContext = colorCanvas.getContext('2d', {willReadFrequently: true});
                if (colorCanvas.width === width && colorCanvas.height === height) color = colorContext?.getImageData(0, 0, width, height) || null;
            }
            const output = new Uint8ClampedArray(source.data.length);
            for (let index = 0; index < source.data.length; index += 4) {
                const value = source.data[index + channel];
                if (emissive && color) {
                    output[index] = Math.round(color.data[index] * value / 255);
                    output[index + 1] = Math.round(color.data[index + 1] * value / 255);
                    output[index + 2] = Math.round(color.data[index + 2] * value / 255);
                } else {
                    output[index] = output[index + 1] = output[index + 2] = value;
                }
                output[index + 3] = 255;
            }
            const canvas = document.createElement('canvas');
            canvas.width = width;
            canvas.height = height;
            canvas.getContext('2d').putImageData(new ImageData(output, width, height), 0, 0);
            return ownedCanvasTexture(canvas);
        }

        function applyTextureSet(material, baseTexture, baseFilePath, textureSet) {
            if (!material || !textureSet || !baseFilePath) return;
            material.userData ||= {};
            material.userData.bedrockTextureSet = textureSet;

            const normalReference = textureSet.normal;
            const heightReference = textureSet.heightmap;
            const merReference = textureSet.metalness_emissive_roughness_subsurface
                ?? textureSet.metalness_emissive_roughness;

            if (typeof normalReference === 'string') {
                const filePath = resolveTextureSetFile(baseFilePath, normalReference);
                const texture = getTexture(filePath);
                const map = texture?.getOwnMaterial?.()?.map || texture?.getMaterial?.()?.map || texture?.material?.map;
                if (map) {
                    material.normalMap = map;
                    material.normalScale = new THREE.Vector2(1, -1);
                    material.userData.bedrockNormalMap = map;
                }
            } else if (typeof heightReference === 'string') {
                const filePath = resolveTextureSetFile(baseFilePath, heightReference);
                const texture = getTexture(filePath);
                const map = texture?.getOwnMaterial?.()?.map || texture?.getMaterial?.()?.map || texture?.material?.map;
                if (map) {
                    material.bumpMap = map;
                    material.bumpScale = 0.4;
                    material.userData.bedrockHeightMap = map;
                }
            }

            if (Array.isArray(merReference)) {
                const values = merReference.map(value => Math.max(0, Math.min(255, Number(value) || 0)) / 255);
                material.metalness = values[0] ?? 0;
                material.emissiveIntensity = values[1] ?? 0;
                material.roughness = values[2] ?? 1;
                material.emissive?.set?.(0xffffff);
                if (values.length > 3) material.userData.bedrockSubsurface = values[3];
                return;
            }
            if (typeof merReference !== 'string') return;
            const merFilePath = resolveTextureSetFile(baseFilePath, merReference);
            const merTexture = getTexture(merFilePath);
            if (!merTexture) return;
            scheduleTextureReady(merTexture, merCanvas => {
                const baseCanvas = textureCanvas(baseTexture);
                const metalness = extractChannelTexture(merCanvas, 0);
                const emissive = extractChannelTexture(merCanvas, 1, baseCanvas, true);
                const roughness = extractChannelTexture(merCanvas, 2);
                const subsurface = /subsurface/.test(Object.keys(textureSet).find(key => textureSet[key] === merReference) || '')
                    ? extractChannelTexture(merCanvas, 3)
                    : null;
                if (metalness) material.metalnessMap = metalness;
                if (emissive) material.emissiveMap = emissive;
                if (roughness) material.roughnessMap = roughness;
                material.metalness = 1;
                material.roughness = 1;
                material.emissive?.set?.(0xffffff);
                material.emissiveIntensity = 1;
                if (subsurface) material.userData.bedrockSubsurfaceMap = subsurface;
                material.userData.bedrockMERSMap = merTexture.getOwnMaterial?.()?.map || merTexture.getMaterial?.()?.map || merTexture.material?.map || null;
                material.needsUpdate = true;
            });
        }

        function getBlockDefinition(blockName) {
            const cacheKey = String(blockName || 'minecraft:stone');
            if (blockDefinitionCache.has(cacheKey)) {
                resolverDiagnostics.definitionCacheHits++;
                return blockDefinitionCache.get(cacheKey);
            }
            resolverDiagnostics.definitionCacheMisses++;
            const identifier = String(blockName || 'minecraft:stone').replace(/^.*:/, '');
            const candidates = [blockName, identifier, ...(aliases[identifier] || [])];
            for (const key of candidates) {
                if (blocks[key] != null) {
                    blockDefinitionCache.set(cacheKey, blocks[key]);
                    return blocks[key];
                }
            }
            const definition = vanillaFilePathDefinitions[identifier] || {textures: identifier};
            blockDefinitionCache.set(cacheKey, definition);
            return definition;
        }

        function semanticFaceForAxis(definition, face, states) {
            const textures = definition?.textures ?? definition;
            if (!textures || typeof textures !== 'object' || Array.isArray(textures)) return face;
            if (!('side' in textures) || (!('up' in textures) && !('down' in textures))) return face;
            const axis = states?.pillar_axis;
            if (axis === 'x') {
                if (face === 'east' || face === 'west') return face === 'east' ? 'up' : 'down';
                return 'side';
            }
            if (axis === 'z') {
                if (face === 'north' || face === 'south') return face === 'south' ? 'up' : 'down';
                return 'side';
            }
            return face;
        }

        function faceReference(definition, face, states) {
            const textures = definition?.textures ?? definition;
            if (typeof textures === 'string' || Array.isArray(textures)) return textures;
            if (!textures || typeof textures !== 'object') return null;
            const semanticFace = semanticFaceForAxis(definition, face, states);
            if (textures[semanticFace] != null) return textures[semanticFace];
            if (semanticFace === 'cross') {
                const upper = Number(states?.upper_block_bit ?? states?.upper_block ?? 0);
                if (upper && textures.up != null) return textures.up;
                if (!upper && textures.down != null) return textures.down;
                if (textures.side != null) return textures.side;
            }
            if (['north','south','east','west'].includes(semanticFace) && textures.side != null) return textures.side;
            return textures.all ?? textures.texture ?? textures.textures ?? null;
        }

        function terrainVariants(aliasOrPath) {
            if (aliasOrPath == null) return [];
            if (typeof aliasOrPath !== 'string') return normalizeTextureVariants(aliasOrPath);
            const entry = textureData[aliasOrPath];
            if (entry != null) return normalizeTextureVariants(entry.textures ?? entry);
            return normalizeTextureVariants(aliasOrPath);
        }

        function currentClientBiomeComponents() {
            const biomeId = String(Project?.mcstructure_biome || 'minecraft:plains');
            if (clientBiomeComponentsCache.has(biomeId)) return clientBiomeComponentsCache.get(biomeId);
            const shortName = biomeId.replace(/^.*:/, '');
            const filePath = pathModule.join(rootPath, 'biomes', `${shortName}.client_biome.json`);
            const modern = readPackJson(fileSystem, filePath);
            const components = modern?.['minecraft:client_biome']?.components;
            const result = components && typeof components === 'object' ? components : null;
            clientBiomeComponentsCache.set(biomeId, result);
            return result;
        }

        function colorArrayToHex(value) {
            if (!Array.isArray(value) || value.length < 3) return null;
            const rgb = value.slice(0, 3).map(component => Math.max(0, Math.min(255, Math.round(Number(component) || 0))));
            return `#${rgb.map(component => component.toString(16).padStart(2, '0')).join('')}`;
        }

        function biomeAppearanceColorSpec(componentName) {
            const component = currentClientBiomeComponents()?.[componentName];
            const color = component?.color;
            if (typeof color === 'string') return {color, colorMap: null};
            if (Array.isArray(color)) return {color: colorArrayToHex(color), colorMap: null};
            if (color && typeof color === 'object') {
                if (typeof color.color === 'string') return {color: color.color, colorMap: null};
                if (Array.isArray(color.color)) return {color: colorArrayToHex(color.color), colorMap: null};
                if (typeof color.color_map === 'string') return {color: null, colorMap: color.color_map};
            }
            return {color: null, colorMap: null};
        }

        function explicitBiomeColor(componentName) {
            return biomeAppearanceColorSpec(componentName).color;
        }

        let cachedBiomeClimateKey = null;
        let cachedBiomeClimate = null;
        function currentBiomeClimate() {
            const biomeId = String(Project?.mcstructure_biome || 'minecraft:plains');
            if (cachedBiomeClimateKey === biomeId) return cachedBiomeClimate;
            cachedBiomeClimateKey = biomeId;
            cachedBiomeClimate = null;
            const shortName = biomeId.replace(/^.*:/, '');
            const candidates = [
                pathModule.join(pathModule.dirname(rootPath), 'behavior_pack', 'biomes', `${shortName}.biome.json`),
                pathModule.join(pathModule.dirname(rootPath), 'behavior_packs', 'biomes', `${shortName}.biome.json`),
            ];
            for (const candidate of candidates) {
                const parsed = readPackJson(fileSystem, candidate);
                const climate = parsed?.['minecraft:biome']?.components?.['minecraft:climate'];
                if (!climate) continue;
                cachedBiomeClimate = {
                    temperature: Math.max(0, Math.min(1, Number(climate.temperature) || 0)),
                    downfall: Math.max(0, Math.min(1, Number(climate.downfall) || 0)),
                };
                break;
            }
            return cachedBiomeClimate;
        }

        const colorMapSampleCache = new Map();
        const colorMapRefreshPending = new Set();
        function refreshTintedBlocksWhenReady(texture, mapName) {
            if (!texture || colorMapRefreshPending.has(mapName)) return;
            colorMapRefreshPending.add(mapName);
            scheduleTextureReady(texture, () => {
                colorMapRefreshPending.delete(mapName);
                colorMapSampleCache.clear();
                if (disposed) return;
                try {
                    if (Project?.mcstructure_optimized_preview) scheduleOptimizedPreviewRebuild(0);
                    else if (BlockElementType) {
                        for (const element of BlockElementType.all || []) {
                            element.preview_controller?.updateFaces?.(element);
                            element.preview_controller?.updateGeometry?.(element);
                        }
                    }
                } catch (error) { warnOnce('biome tint refresh', error); }
            });
        }

        function sampleBiomeColorMap(mapName, fallback) {
            const biomeId = String(Project?.mcstructure_biome || 'minecraft:plains');
            const climate = currentBiomeClimate();
            const key = `${mapName}|${biomeId}|${climate?.temperature ?? 'x'}|${climate?.downfall ?? 'x'}`;
            if (colorMapSampleCache.has(key)) return colorMapSampleCache.get(key);
            const filePath = resolveFile(`colormap/${mapName}`);
            if (!filePath) return fallback;
            const texture = getTexture(filePath);
            const canvas = textureCanvas(texture);
            if (!canvas || !climate) {
                refreshTintedBlocksWhenReady(texture, mapName);
                return fallback;
            }
            try {
                // Vanilla biome colormaps use temperature on X and
                // temperature-weighted downfall on Y. This keeps resource-pack
                // colormaps authoritative instead of hard-coding foliage RGB.
                const temperature = Math.max(0, Math.min(1, climate.temperature));
                const humidity = Math.max(0, Math.min(1, climate.downfall * temperature));
                const x = Math.max(0, Math.min(canvas.width - 1, Math.floor((1 - temperature) * (canvas.width - 1))));
                const y = Math.max(0, Math.min(canvas.height - 1, Math.floor((1 - humidity) * (canvas.height - 1))));
                const pixel = canvas.getContext('2d', {willReadFrequently: true})?.getImageData(x, y, 1, 1)?.data;
                // The unused triangle of vanilla biome colormaps is transparent.
                // Canvas returns RGB 0,0,0 for those texels; treating that as a
                // legitimate tint is exactly what made grass/leaves turn black.
                if (!pixel || pixel[3] < 8) return fallback;
                const color = `#${[pixel[0], pixel[1], pixel[2]].map(component => component.toString(16).padStart(2, '0')).join('')}`;
                colorMapSampleCache.set(key, color);
                return color;
            } catch {
                return fallback;
            }
        }

        function grassTintColor() {
            const spec = biomeAppearanceColorSpec('minecraft:grass_appearance');
            if (spec.color) return spec.color;
            const grassVariants = terrainVariants('grass_side');
            const tintIndex = Math.max(0, Math.min(
                Math.max(0, grassVariants.length - 2),
                Math.round(Number(Project?.mcstructure_biome_tint_index) || 0)
            ));
            const fallback = grassVariants[tintIndex]?.overlayColor || '#79c05a';
            return sampleBiomeColorMap(spec.colorMap || 'grass', fallback);
        }

        // Bedrock does not encode all vanilla biome tinting as overlay_color in
        // terrain_texture.json. Modern block material instances expose the same
        // engine concept explicitly as tint_method. Vanilla's legacy blocks.json
        // predates that component, so map the known vanilla block families onto
        // the same semantic methods instead of special-casing texture colors.
        const VANILLA_UNTINTED_LEAVES = new Set([
            'azalea_leaves',
            'azalea_leaves_flowered',
            'flowering_azalea_leaves',
            'cherry_leaves',
            'pale_oak_leaves',
        ]);

        function legacyLeafTintMethod(identifier, states = {}) {
            if (identifier === 'birch_leaves') return 'birch_foliage';
            if (identifier === 'spruce_leaves') return 'evergreen_foliage';

            // Old Bedrock palettes used minecraft:leaves + old_leaf_type and
            // minecraft:leaves2 + new_leaf_type instead of per-species IDs.
            if (identifier === 'leaves') {
                const type = String(states.old_leaf_type ?? states.leaf_type ?? '').replace(/^minecraft:/, '');
                if (type === 'birch') return 'birch_foliage';
                if (type === 'spruce') return 'evergreen_foliage';
                return 'default_foliage';
            }
            if (identifier === 'leaves2') return 'default_foliage';
            if (VANILLA_UNTINTED_LEAVES.has(identifier)) return 'none';
            if (/_leaves$/.test(identifier)) return 'default_foliage';
            return 'none';
        }

        function vanillaTintMethod(blockName, states = {}, alias = '', variantPath = '', face = '') {
            const identifier = String(blockName).replace(/^.*:/, '').toLowerCase();
            const textureKey = `${alias || ''} ${variantPath || ''}`.toLowerCase();

            if (/(^|_)water($|_)/.test(identifier) || /still_water|flowing_water/.test(textureKey)) {
                return 'water';
            }

            // Grass block: top is fully tinted. Sides use the same grass tint but
            // are composed with grass_side_carried underneath by our alpha-masked
            // layered path. Bottom dirt is intentionally not tinted.
            if (identifier === 'grass_block' || identifier === 'grass') {
                if (face === 'down' || alias === 'grass_bottom' || /(?:^|\/)dirt(?:\.|$)/.test(variantPath)) return 'none';
                if (face === 'up' || alias === 'grass_top' || alias === 'grass_side' || /grass_(?:top|side)/.test(textureKey)) {
                    return 'grass';
                }
            }

            // Current + historical in-world grass/fern blocks. Their terrain
            // entries generally point at grayscale alpha-tested textures and do
            // not need an overlay_color field to participate in biome tinting.
            if ([
                'short_grass', 'tall_grass', 'fern', 'large_fern', 'tallgrass', 'bush'
            ].includes(identifier)) return 'grass';
            if (identifier === 'double_plant') {
                const type = String(states.double_plant_type ?? states.double_plant_type_bit ?? '').toLowerCase();
                if (type === 'grass' || type === 'fern') return 'grass';
            }

            // Ordinary overworld vines use foliage tint. Nether/cave vines have
            // authored colors and therefore are deliberately excluded.
            if (identifier === 'vine') return 'default_foliage';

            const leafMethod = legacyLeafTintMethod(identifier, states);
            if (leafMethod !== 'none') return leafMethod;

            return 'none';
        }

        function foliageTintColor(method = 'default_foliage') {
            if (method === 'birch_foliage') {
                return sampleBiomeColorMap('birch', '#80A755');
            }
            if (method === 'evergreen_foliage') {
                return sampleBiomeColorMap('evergreen', '#619961');
            }
            if (method === 'dry_foliage') {
                return sampleBiomeColorMap('dry_foliage', '#A08856');
            }

            const spec = biomeAppearanceColorSpec('minecraft:foliage_appearance');
            if (spec.color) return spec.color;
            return sampleBiomeColorMap(spec.colorMap || 'foliage', grassTintColor());
        }

        function tintColorForMethod(method) {
            switch (method) {
                case 'grass': return grassTintColor();
                case 'default_foliage':
                case 'birch_foliage':
                case 'evergreen_foliage':
                case 'dry_foliage':
                    return foliageTintColor(method);
                case 'water': return biomeWaterAppearance().color;
                default: return '#ffffff';
            }
        }

        // --- Bedrock color atlas -------------------------------------------------
        // A block face appearance is resolved first (source texture, tint class,
        // overlays, opacity) and then baked into a shared atlas tile. The mesh
        // material itself always stays white. This mirrors how a terrain atlas is
        // consumed by the game and, importantly, removes the race where a tint is
        // multiplied against Blockbench's temporary/empty texture material.
        const ATLAS_SIZE = 1024;
        const ATLAS_PADDING = 2;
        let nextAtlasPageId = 1;

        const dirtyAtlasPages = new Set();
        let atlasUploadScheduled = false;
        function scheduleAtlasPageUpload(page) {
            if (!page?.map) return;
            dirtyAtlasPages.add(page);
            if (atlasUploadScheduled) return;
            atlasUploadScheduled = true;
            const flush = () => {
                atlasUploadScheduled = false;
                for (const dirtyPage of dirtyAtlasPages) {
                    dirtyPage.map.needsUpdate = true;
                    resolverDiagnostics.atlasUploads++;
                }
                dirtyAtlasPages.clear();
            };
            if (typeof requestAnimationFrame === 'function') requestAnimationFrame(flush);
            else setTimeout(flush, 0);
        }
        const imageDimensionCache = new Map();
        function imageDimensionsFromFile(filePath) {
            const normalized = pathModule.normalize(String(filePath || '')).toLowerCase();
            if (imageDimensionCache.has(normalized)) return imageDimensionCache.get(normalized);
            let descriptor = {width: 16, height: 16};
            let handle = null;
            try {
                const extension = pathModule.extname(filePath).toLowerCase();
                const headerLength = extension === '.tga' ? 18 : 24;
                const buffer = Buffer.allocUnsafe(headerLength);
                handle = fileSystem.openSync(filePath, 'r');
                const bytesRead = fileSystem.readSync(handle, buffer, 0, headerLength, 0);
                if (extension === '.png' && bytesRead >= 24
                    && buffer[0] === 0x89 && buffer[1] === 0x50 && buffer[2] === 0x4e && buffer[3] === 0x47) {
                    descriptor = {
                        width: Math.max(1, buffer.readUInt32BE(16)),
                        height: Math.max(1, buffer.readUInt32BE(20)),
                    };
                } else if (extension === '.tga' && bytesRead >= 18) {
                    descriptor = {
                        width: Math.max(1, buffer.readUInt16LE(12)),
                        height: Math.max(1, buffer.readUInt16LE(14)),
                    };
                }
            } catch {} finally {
                if (handle != null) try { fileSystem.closeSync(handle); } catch {}
            }
            imageDimensionCache.set(normalized, descriptor);
            return descriptor;
        }

        function atlasModeKey(mode) {
            return mode === 'blend' ? 'blend' : mode === 'alpha_test' ? 'alpha_test' : 'opaque';
        }

        function createAtlasPage(mode) {
            if (typeof document === 'undefined') return null;
            const canvas = document.createElement('canvas');
            canvas.width = canvas.height = ATLAS_SIZE;
            const ctx = canvas.getContext('2d');
            if (!ctx) return null;
            ctx.imageSmoothingEnabled = false;
            if (mode === 'opaque') {
                // Shader Architect profiles alpha over the complete texture, not
                // just the UV islands used by a chunk. A mostly-empty transparent
                // atlas page was therefore misclassified as cutout and the Render
                // bridge injected alphaTest=0.001 even for an opaque terrain page.
                // Keep unused pixels alpha-opaque; no geometry samples them.
                ctx.fillStyle = '#000000';
                ctx.fillRect(0, 0, ATLAS_SIZE, ATLAS_SIZE);
            } else {
                ctx.clearRect(0, 0, ATLAS_SIZE, ATLAS_SIZE);
            }

            const map = typeof THREE.CanvasTexture === 'function'
                ? new THREE.CanvasTexture(canvas)
                : new THREE.Texture(canvas);
            map.name = `Bedrock Atlas ${mode} ${nextAtlasPageId}`;
            map.wrapS = map.wrapT = THREE.ClampToEdgeWrapping;
            map.magFilter = map.minFilter = THREE.NearestFilter;
            map.generateMipmaps = false;
            if (THREE.sRGBEncoding != null) map.encoding = THREE.sRGBEncoding;
            map.needsUpdate = true;
            ownedDerivedTextures.add(map);

            // Color/tint is fully baked into atlas pixels. Use an unlit atlas
            // material in Edit mode so the texture cannot become black because a
            // scene/light/PBR path is unavailable. Lightflow's Render mode can
            // still consume the atlas texture independently.
            const material = new THREE.MeshBasicMaterial({
                map,
                color: 0xffffff,
                transparent: mode === 'blend',
                alphaTest: mode === 'alpha_test' ? 0.5 : 0,
                side: mode === 'alpha_test' ? THREE.DoubleSide : THREE.FrontSide,
            });
            material.toneMapped = false;
            material.name = `Bedrock Atlas:${mode}:${nextAtlasPageId}`;
            material.depthWrite = mode !== 'blend';
            material.userData ||= {};
            material.userData.bedrockAtlas = true;
            material.userData.bedrockAtlasMode = mode;
            installGreedyAtlasMaterialSupport(material);

            const page = {
                id: nextAtlasPageId++,
                key: `bedrock-atlas:${mode}:${nextAtlasPageId - 1}`,
                mode,
                canvas,
                ctx,
                map,
                material,
                cursorX: ATLAS_PADDING,
                cursorY: ATLAS_PADDING,
                rowHeight: 0,
                entries: 0,
            };
            material.userData.bedrockAtlasPage = page.id;
            atlasPages.add(page);
            if (!atlasPagesByMode.has(mode)) atlasPagesByMode.set(mode, []);
            atlasPagesByMode.get(mode).push(page);
            return page;
        }

        function allocateAtlasTile(mode, width, height) {
            mode = atlasModeKey(mode);
            width = Math.max(1, Math.ceil(Number(width) || 16));
            height = Math.max(1, Math.ceil(Number(height) || 16));
            if (width + ATLAS_PADDING * 2 > ATLAS_SIZE || height + ATLAS_PADDING * 2 > ATLAS_SIZE) return null;
            const pages = atlasPagesByMode.get(mode) || [];
            let page = pages[pages.length - 1] || createAtlasPage(mode);
            if (!page) return null;

            const reservedWidth = width + ATLAS_PADDING * 2;
            const reservedHeight = height + ATLAS_PADDING * 2;
            if (page.cursorX + reservedWidth > ATLAS_SIZE) {
                page.cursorX = ATLAS_PADDING;
                page.cursorY += page.rowHeight;
                page.rowHeight = 0;
            }
            if (page.cursorY + reservedHeight > ATLAS_SIZE) {
                page = createAtlasPage(mode);
                if (!page) return null;
            }

            const x = page.cursorX + ATLAS_PADDING;
            const y = page.cursorY + ATLAS_PADDING;
            page.cursorX += reservedWidth;
            page.rowHeight = Math.max(page.rowHeight, reservedHeight);
            page.entries++;
            return {
                page,
                x, y, width, height,
                uvRect: [
                    x / ATLAS_SIZE,
                    1 - (y + height) / ATLAS_SIZE,
                    (x + width) / ATLAS_SIZE,
                    1 - y / ATLAS_SIZE,
                ],
            };
        }

        function tintCanvasPixels(canvas, tint, opacity = 1) {
            const normalized = normalizeTintHex(tint);
            const ctx = canvas.getContext('2d', {willReadFrequently: true});
            const image = ctx?.getImageData(0, 0, canvas.width, canvas.height);
            if (!image) return canvas;
            const [tr, tg, tb] = normalized.rgb;
            const alphaScale = Math.max(0, Math.min(1, Number(opacity) || 0));
            for (let i = 0; i < image.data.length; i += 4) {
                image.data[i] = Math.round(image.data[i] * tr / 255);
                image.data[i + 1] = Math.round(image.data[i + 1] * tg / 255);
                image.data[i + 2] = Math.round(image.data[i + 2] * tb / 255);
                if (alphaScale !== 1) image.data[i + 3] = Math.round(image.data[i + 3] * alphaScale);
            }
            ctx.putImageData(image, 0, 0);
            return canvas;
        }

        function canvasFromSource(sourceCanvas, width, height, tint = '#ffffff', opacity = 1) {
            if (!sourceCanvas || typeof document === 'undefined') return null;
            const canvas = document.createElement('canvas');
            canvas.width = width;
            canvas.height = height;
            const ctx = canvas.getContext('2d', {willReadFrequently: true});
            if (!ctx) return null;
            ctx.imageSmoothingEnabled = false;
            ctx.clearRect(0, 0, width, height);
            ctx.drawImage(sourceCanvas, 0, 0, sourceCanvas.width, sourceCanvas.height, 0, 0, width, height);
            return tintCanvasPixels(canvas, tint, opacity);
        }

        function blitAtlasTile(entry, tileCanvas) {
            if (!entry?.page || !tileCanvas) return;
            const {page, x, y, width, height} = entry;
            const ctx = page.ctx;
            ctx.imageSmoothingEnabled = false;
            ctx.clearRect(x - ATLAS_PADDING, y - ATLAS_PADDING,
                width + ATLAS_PADDING * 2, height + ATLAS_PADDING * 2);
            ctx.drawImage(tileCanvas, 0, 0, tileCanvas.width, tileCanvas.height, x, y, width, height);

            // Duplicate edge texels into the padding. Even though the editor uses
            // nearest/no-mip filtering, this prevents seams when cameras land on a
            // tile boundary and leaves the atlas safe for future mip generation.
            ctx.drawImage(tileCanvas, 0, 0, 1, tileCanvas.height,
                x - ATLAS_PADDING, y, ATLAS_PADDING, height);
            ctx.drawImage(tileCanvas, tileCanvas.width - 1, 0, 1, tileCanvas.height,
                x + width, y, ATLAS_PADDING, height);
            ctx.drawImage(tileCanvas, 0, 0, tileCanvas.width, 1,
                x, y - ATLAS_PADDING, width, ATLAS_PADDING);
            ctx.drawImage(tileCanvas, 0, tileCanvas.height - 1, tileCanvas.width, 1,
                x, y + height, width, ATLAS_PADDING);
            ctx.drawImage(tileCanvas, 0, 0, 1, 1,
                x - ATLAS_PADDING, y - ATLAS_PADDING, ATLAS_PADDING, ATLAS_PADDING);
            ctx.drawImage(tileCanvas, tileCanvas.width - 1, 0, 1, 1,
                x + width, y - ATLAS_PADDING, ATLAS_PADDING, ATLAS_PADDING);
            ctx.drawImage(tileCanvas, 0, tileCanvas.height - 1, 1, 1,
                x - ATLAS_PADDING, y + height, ATLAS_PADDING, ATLAS_PADDING);
            ctx.drawImage(tileCanvas, tileCanvas.width - 1, tileCanvas.height - 1, 1, 1,
                x + width, y + height, ATLAS_PADDING, ATLAS_PADDING);
            scheduleAtlasPageUpload(page);
        }

        function paintAtlasAppearance(entry, options) {
            if (!entry || disposed) return false;
            const sourceCanvas = textureCanvas(options.texture);
            const baseCanvas = options.baseTexture ? textureCanvas(options.baseTexture) : null;
            if (!sourceCanvas || (options.baseTexture && !baseCanvas)) return false;

            let tile;
            if (options.layeredGrassSide && baseCanvas) {
                // EXACT grass side semantics:
                //   1) grass_side_carried underneath, untouched
                //   2) grass_side above, tint only this layer, preserve its alpha
                tile = canvasFromSource(baseCanvas, entry.width, entry.height, '#ffffff', 1);
                const overlay = canvasFromSource(sourceCanvas, entry.width, entry.height, options.tint, 1);
                const ctx = tile?.getContext('2d');
                if (ctx && overlay) {
                    ctx.imageSmoothingEnabled = false;
                    ctx.globalCompositeOperation = 'source-over';
                    ctx.drawImage(overlay, 0, 0);
                }
            } else {
                tile = canvasFromSource(sourceCanvas, entry.width, entry.height, options.tint, options.opacity);
            }
            if (!tile) return false;
            blitAtlasTile(entry, tile);
            entry.ready = true;
            return true;
        }

        function scheduleAtlasAppearance(entry, options) {
            const attempt = () => {
                if (disposed || entry.ready) return;
                paintAtlasAppearance(entry, options);
            };
            attempt();
            scheduleTextureReady(options.texture, attempt);
            if (options.baseTexture) scheduleTextureReady(options.baseTexture, attempt);
        }

        function atlasAppearance(options) {
            const mode = atlasModeKey(options.mode);
            const tint = normalizeTintHex(options.tint || '#ffffff').css;
            const opacity = Math.max(0, Math.min(1, Number(options.opacity ?? 1)));
            const key = [
                mode,
                pathModule.normalize(options.filePath || options.path || '').toLowerCase(),
                options.baseFilePath ? pathModule.normalize(options.baseFilePath).toLowerCase() : '',
                options.layeredGrassSide ? 'grass-layered' : 'single',
                tint,
                opacity.toFixed(4),
            ].join('|');
            if (atlasEntryCache.has(key)) return atlasEntryCache.get(key);

            const dimensions = imageDimensionsFromFile(options.filePath);
            const allocation = allocateAtlasTile(mode, dimensions.width, dimensions.height);
            if (!allocation) return null;
            const entry = {
                ...allocation,
                width: dimensions.width,
                height: dimensions.height,
                appearanceKey: key,
                ready: false,
                sourceTexture: options.texture,
            };
            atlasEntryCache.set(key, entry);

            // Use a visible non-black placeholder while asynchronous PNG/TGA
            // decoding completes. The tile is replaced in-place; UVs do not move.
            if (typeof document !== 'undefined') {
                const placeholder = document.createElement('canvas');
                placeholder.width = entry.width;
                placeholder.height = entry.height;
                const ctx = placeholder.getContext('2d');
                if (ctx) {
                    ctx.fillStyle = '#ff00ff';
                    ctx.fillRect(0, 0, placeholder.width, placeholder.height);
                    ctx.fillStyle = '#111111';
                    const halfW = Math.max(1, Math.floor(placeholder.width / 2));
                    const halfH = Math.max(1, Math.floor(placeholder.height / 2));
                    ctx.fillRect(0, 0, halfW, halfH);
                    ctx.fillRect(halfW, halfH, placeholder.width - halfW, placeholder.height - halfH);
                    blitAtlasTile(entry, placeholder);
                }
            }
            scheduleAtlasAppearance(entry, options);
            return entry;
        }

        function selectedVariant(alias, variants, states) {
            if (!variants.length) return null;
            if (/^rail_normal(?:$|_)/.test(String(alias || '').replace(/^.*\//, ''))) {
                const direction = railDirectionValue(states);
                return variants[direction >= 6 && variants.length > 1 ? 1 : 0] || variants[0];
            }
            if (alias === 'grass_side' || alias === 'grass_top' || alias === 'grass') {
                const index = Math.max(0, Math.min(
                    variants.length - 1,
                    Math.round(Number(Project?.mcstructure_biome_tint_index) || 0)
                ));
                return variants[index] || variants[0];
            }
            if (/leaves/.test(alias) && variants.length === 2) {
                return variants[Project?.mcstructure_fancy_leaves === false ? 1 : 0] || variants[0];
            }
            return variants[stateVariantIndex(states, variants.length)] || variants[0];
        }

        function customBlockContext(blockName, states = {}) {
            const identifier = String(blockName || '');
            const permutation = BedrockStructureParser.blockPermutationKey({name: identifier, states: states || {}});
            if (customBlockContextCache.has(permutation)) return customBlockContextCache.get(permutation);
            const indexed = customGeometryIndex.blockDefinitions.get(identifier);
            if (!indexed?.definition) {
                customBlockContextCache.set(permutation, null);
                return null;
            }
            const unsupported = new Set();
            const components = effectiveBedrockBlockComponents(indexed.definition, states, unsupported);
            const geometryComponent = components['minecraft:geometry'];
            const geometryIdentifier = typeof geometryComponent === 'string'
                ? geometryComponent
                : geometryComponent && typeof geometryComponent === 'object'
                    ? geometryComponent.identifier
                    : null;
            const context = {
                blockName: identifier,
                permutation,
                blockDefinition: indexed.definition,
                components,
                geometryComponent,
                geometryIdentifier: typeof geometryIdentifier === 'string' ? geometryIdentifier : null,
                materialInstances: components['minecraft:material_instances'] || null,
                transformation: components['minecraft:transformation'] || null,
                unsupported,
            };
            customBlockContextCache.set(permutation, context);
            return context;
        }

        function recordCustomGeometryDiagnostic(type, context, details = {}) {
            const diagnostic = {
                type: String(type || 'unknown'),
                block: context?.blockName || null,
                permutation: context?.permutation || null,
                geometry: context?.geometryIdentifier || null,
                ...details,
            };
            const key = [
                diagnostic.type,
                diagnostic.block || '',
                diagnostic.permutation || '',
                diagnostic.geometry || '',
                diagnostic.materialInstance || '',
                diagnostic.alias || '',
                diagnostic.target || '',
            ].join('|');
            if (!customGeometryDiagnostics.has(key)) customGeometryDiagnostics.set(key, diagnostic);
            return diagnostic;
        }

        function customGeometryDiagnosticSummary() {
            const counts = {};
            const details = Array.from(customGeometryDiagnostics.values());
            for (const diagnostic of details) {
                counts[diagnostic.type] = Number(counts[diagnostic.type] || 0) + 1;
            }
            return {
                total: details.length,
                counts,
                details: details.slice(0, 64),
                truncated: Math.max(0, details.length - 64),
            };
        }

        function customGeometryStatus(blockName, states = {}) {
            const context = customBlockContext(blockName, states);
            if (!context?.geometryIdentifier) {
                return {mapped: false, resolved: false, geometryIdentifier: null, diagnostic: null};
            }
            const indexed = customGeometryIndex.geometries.get(context.geometryIdentifier);
            if (!indexed?.geometry) {
                const diagnostic = recordCustomGeometryDiagnostic('missing_geometry', context, {
                    target: context.geometryIdentifier,
                });
                return {
                    mapped: true,
                    resolved: false,
                    geometryIdentifier: context.geometryIdentifier,
                    diagnostic,
                };
            }
            return {
                mapped: true,
                resolved: true,
                geometryIdentifier: context.geometryIdentifier,
                diagnostic: null,
            };
        }

        function resolveShape(blockName, states = {}) {
            const context = customBlockContext(blockName, states);
            if (!context?.geometryIdentifier) return null;
            if (customShapeCache.has(context.permutation)) return customShapeCache.get(context.permutation);
            const status = customGeometryStatus(blockName, states);
            if (!status.resolved) {
                customShapeCache.set(context.permutation, null);
                return null;
            }
            const indexed = customGeometryIndex.geometries.get(context.geometryIdentifier);
            const compiled = compileBedrockGeometryShape(indexed.geometry, {
                geometryIdentifier: context.geometryIdentifier,
                geometryComponent: context.geometryComponent,
                transformation: context.transformation,
                unsupported: context.unsupported,
            });
            if (compiled) {
                compiled.key = `${compiled.key}:${hashString(context.permutation).toString(16)}`;
                for (const feature of compiled.unsupported || []) {
                    customUnsupportedFeatures.add(feature);
                    warnOnce(
                        `resource-pack-geometry:${context.geometryIdentifier}:${feature}`,
                        new Error(`Custom Bedrock block geometry ${context.geometryIdentifier} uses unsupported ${feature}; rendering the supported cube subset conservatively.`)
                    );
                }
            }
            customShapeCache.set(context.permutation, compiled || null);
            return compiled || null;
        }

        function customMaterialDefinition(instances, token, context = null) {
            if (!instances || typeof instances !== 'object' || Array.isArray(instances)) return null;
            let key = Object.prototype.hasOwnProperty.call(instances, token) ? token : '*';
            let value = instances[key];
            const seen = new Set();
            while (typeof value === 'string') {
                if (seen.has(key)) {
                    customUnsupportedFeatures.add('material_alias_cycle');
                    recordCustomGeometryDiagnostic('material_alias_cycle', context, {
                        materialInstance: key,
                        alias: value,
                        target: value,
                    });
                    return null;
                }
                seen.add(key);
                if (!Object.prototype.hasOwnProperty.call(instances, value)) {
                    recordCustomGeometryDiagnostic('dangling_material_alias', context, {
                        materialInstance: key,
                        alias: value,
                        target: value,
                    });
                    return null;
                }
                key = value;
                value = instances[key];
            }
            return value && typeof value === 'object' && !Array.isArray(value)
                ? {key, definition: value}
                : null;
        }

        function customMaterialRenderMode(definition) {
            const renderMethod = String(definition?.render_method || 'opaque').toLowerCase();
            if (renderMethod === 'blend' || renderMethod === 'blend_to_opaque') return 'blend';
            if (renderMethod === 'alpha_test' || renderMethod === 'alpha_test_single_sided' || renderMethod === 'alpha_test_to_opaque') return 'alpha_test';
            return 'opaque';
        }

        function resolveMaterial(blockName, states, token, fallbackFace = 'north', position = [0,0,0]) {
            const context = customBlockContext(blockName, states);
            if (!context?.geometryIdentifier || !context.materialInstances) return null;
            const materialToken = String(token || fallbackFace || '*');
            const selected = customMaterialDefinition(context.materialInstances, materialToken, context)
                || customMaterialDefinition(context.materialInstances, fallbackFace, context)
                || customMaterialDefinition(context.materialInstances, '*', context);
            if (!selected?.definition) return null;
            const materialDefinition = selected.definition;
            const alias = typeof materialDefinition.texture === 'string' ? materialDefinition.texture : null;
            if (!alias) return null;
            const biomeKey = `${Project?.mcstructure_biome || 'minecraft:plains'}:${Number(Project?.mcstructure_biome_tint_index) || 0}`;
            const cacheKey = `${context.permutation}|${selected.key}|${materialToken}|${biomeKey}`;
            if (customMaterialDescriptorCache.has(cacheKey)) return customMaterialDescriptorCache.get(cacheKey);

            const variant = selectedVariant(alias, terrainVariants(alias), states);
            const filePath = variant?.path ? resolveFile(variant.path) : null;
            const texture = getTexture(filePath);
            if (!variant || !filePath || !texture) {
                customMaterialDescriptorCache.set(cacheKey, null);
                return null;
            }
            const renderMethod = String(materialDefinition.render_method || 'opaque').toLowerCase();
            const mode = customMaterialRenderMode(materialDefinition);
            const doubleSided = renderMethod === 'double_sided' || renderMethod === 'alpha_test';
            if (renderMethod.endsWith('_to_opaque')) customUnsupportedFeatures.add(renderMethod);
            if (materialDefinition.isotropic === true) customUnsupportedFeatures.add('material_isotropic');
            const tintMethod = typeof materialDefinition.tint_method === 'string' ? materialDefinition.tint_method : 'none';
            const tint = tintMethod !== 'none' ? tintColorForMethod(tintMethod) : (variant.overlayColor || '#ffffff');
            const flipbook = flipbookByAtlasTile.get(alias)
                || flipbookByPath.get(String(variant.path || '').replace(/\.(png|tga)$/i, ''));
            const atlasCompatibleSide = mode === 'alpha_test' ? doubleSided : !doubleSided;
            let descriptor = null;
            if (!flipbook && atlasCompatibleSide) {
                const atlas = atlasAppearance({texture, filePath, path: variant.path, mode, tint, opacity: 1});
                if (atlas?.page?.material) {
                    descriptor = {
                        key: atlas.page.key,
                        material: atlas.page.material,
                        texture,
                        tint,
                        path: variant.path,
                        alias,
                        mode,
                        uvQuarterTurns: 0,
                        uvRect: atlas.uvRect,
                        atlasPage: atlas.page.id,
                        atlasReady: atlas.ready,
                        customMaterialInstance: selected.key,
                    };
                }
            }
            if (!descriptor) {
                const material = materialFromTexture(texture, {
                    path: variant.path,
                    filePath,
                    alias,
                    blockName,
                    tint,
                    mode,
                    opacity: 1,
                    doubleSided,
                });
                descriptor = {
                    key: `pack-custom:${texture.uuid}:${selected.key}:${renderMethod}:${tint}`,
                    material,
                    texture,
                    tint,
                    path: variant.path,
                    alias,
                    mode,
                    uvQuarterTurns: 0,
                    customMaterialInstance: selected.key,
                    flipbookAnimation: material?.userData?.bedrockFlipbookAnimation || null,
                };
            }
            customMaterialDescriptorCache.set(cacheKey, descriptor);
            return descriptor;
        }

        function blockRenderMode(blockName) {
            const id = String(blockName).replace(/^.*:/, '').toLowerCase();
            if (/(water|lava)/.test(id)) return 'blend';
            if (/(glass|ice|portal)/.test(id) && !/(glass_pane_top)/.test(id)) return 'blend';
            if (/(leaves|sapling|flower|grass$|fern|vine|mushroom|crop|wheat|roots|bush|torch|rail|door|trapdoor|ladder|cobweb|lily_pad|seagrass|kelp|coral_fan)/.test(id)) return 'alpha_test';
            return 'opaque';
        }

        function biomeWaterAppearance() {
            const modern = currentClientBiomeComponents()?.['minecraft:water_appearance'] || {};
            const biomeId = Project?.mcstructure_biome || 'minecraft:plains';
            const legacy = biomesClient?.biomes?.[biomeId] || biomesClient?.biomes?.default || {};
            const opacity = modern.surface_opacity ?? legacy.water_surface_transparency;
            return {
                color: modern.surface_color || legacy.water_surface_color || '#44AFF5',
                transparency: Number.isFinite(Number(opacity)) ? Number(opacity) : 0.65,
            };
        }

        function materialFromTexture(texture, options) {
            const source = typeof texture?.getMaterial === 'function' ? texture.getMaterial() : texture?.material;
            const map = source?.map || source?.uniforms?.map?.value || null;
            const mode = options.mode || 'opaque';
            const tint = options.tint || '#ffffff';
            const opacity = options.opacity == null ? 1 : Number(options.opacity);
            const textureSet = options.filePath ? readTextureSetForFile(options.filePath) : null;
            const key = [
                texture?.uuid || options.path || 'missing',
                tint,
                mode,
                opacity,
                options.doubleSided ? '2' : '1',
                textureSet ? 'pbr' : 'flat',
            ].join('|');
            if (materialCache.has(key)) return materialCache.get(key);

            let material;
            if (source?.isMeshBasicMaterial) {
                material = source.clone();
                if (material.color) material.color.set(tint);
            } else {
                // The native Textured view is deliberately unlit. Lighting is
                // owned by Shader Architect after the optional Lightflow bridge
                // swaps this source material, so Lambert/Standard materials here
                // would apply a second, unrelated set of Blockbench lights.
                material = new THREE.MeshBasicMaterial({
                    map,
                    color: new THREE.Color(tint),
                });
            }
            material.name = `Bedrock:${options.path || texture?.name || 'texture'}`;
            material.transparent = mode === 'blend';
            material.opacity = Math.max(0, Math.min(1, opacity));
            material.alphaTest = mode === 'alpha_test' ? 0.5 : 0;
            material.depthWrite = mode !== 'blend' || !/water/.test(options.blockName || '');
            material.side = options.doubleSided ? THREE.DoubleSide : THREE.FrontSide;
            material.userData ||= {};
            material.userData.bedrockBlock = options.blockName;
            material.userData.bedrockTexture = options.path;
            material.userData.bedrockOverlayColor = options.tint || null;
            material.userData.bedrockRenderMode = mode;
            material.userData.bedrockAmbientOcclusionExponent = options.ambientOcclusionExponent ?? null;
            materialCache.set(key, material);
            if (textureSet) applyTextureSet(material, texture, options.filePath, textureSet);

            const flipbook = flipbookByAtlasTile.get(options.alias)
                || flipbookByPath.get(String(options.path || '').replace(/\.(png|tga)$/i, ''));
            if (flipbook && map) {
                material.userData.bedrockFlipbookAnimation = registerFlipbook(map, flipbook);
            }
            return material;
        }

        function registerFlipbook(map, definition) {
            if (!map) return null;
            map.userData ||= {};
            if (map.userData.bedrockFlipbookAnimation) return map.userData.bedrockFlipbookAnimation;
            map.userData.bedrockFlipbook = true;
            // Shader Architect samples vUv directly and therefore ignores a
            // Three texture's repeat/offset transform. Animate the UV ranges of
            // the geometry groups instead; this works in Textured, Lightflow,
            // shadows, and Studio Render with the same source texture.
            map.wrapS = map.wrapT = THREE.ClampToEdgeWrapping;
            const animation = {
                map,
                definition,
                start: typeof performance !== 'undefined' ? performance.now() : Date.now(),
                targets: new Set(),
                frame: -1,
                compiledKey: '',
                compiledFrames: null,
                totalTicks: 1,
                columns: 1,
                rows: 1,
                update(now, force = false) {
                    const image = map.image;
                    const width = Number(image?.naturalWidth || image?.videoWidth || image?.width || 0);
                    const height = Number(image?.naturalHeight || image?.videoHeight || image?.height || 0);
                    if (!width || !height) return false;
                    const compiledKey = `${width}x${height}`;
                    if (this.compiledKey !== compiledKey) {
                        const replicate = Math.max(1, Number(definition.replicate) || 1);
                        this.columns = 1;
                        this.rows = 1;
                        if (height >= width) this.rows = Math.max(1, Math.round(height / Math.max(1, width / replicate)));
                        else this.columns = Math.max(1, Math.round(width / Math.max(1, height / replicate)));
                        const count = Math.max(1, this.columns * this.rows);
                        const sourceFrames = Array.isArray(definition.frames) && definition.frames.length
                            ? definition.frames
                            : Array.from({length: count}, (_, index) => index);
                        this.compiledFrames = sourceFrames.map(entry => entry && typeof entry === 'object'
                            ? {index: Number(entry.index ?? entry.frame ?? entry.texture_index ?? 0) || 0, ticks: Math.max(1, Number(entry.time ?? entry.ticks ?? definition.ticks_per_frame) || 1)}
                            : {index: Number(entry) || 0, ticks: Math.max(1, Number(definition.ticks_per_frame) || 1)});
                        this.totalTicks = this.compiledFrames.reduce((sum, entry) => sum + entry.ticks, 0) || 1;
                        this.compiledKey = compiledKey;
                    }
                    const physicalFrames = Math.max(1, this.columns * this.rows);
                    let tick = Math.floor((now - this.start) / 50) % this.totalTicks;
                    let selected = this.compiledFrames[0];
                    for (const entry of this.compiledFrames) {
                        if (tick < entry.ticks) { selected = entry; break; }
                        tick -= entry.ticks;
                    }
                    const frame = ((selected.index % physicalFrames) + physicalFrames) % physicalFrames;
                    if (!force && frame === this.frame) return false;
                    this.frame = frame;
                    const column = frame % this.columns;
                    const row = Math.floor(frame / this.columns);
                    map.magFilter = THREE.NearestFilter;
                    map.minFilter = THREE.NearestFilter;
                    for (const target of Array.from(this.targets)) {
                        const uv = target.geometry?.attributes?.uv;
                        if (!uv || uv.count < target.start + target.count) {
                            this.targets.delete(target);
                            continue;
                        }
                        for (let vertex = 0; vertex < target.count; vertex++) {
                            const sourceOffset = vertex * 2;
                            const destinationOffset = (target.start + vertex) * 2;
                            uv.array[destinationOffset] = (target.baseUv[sourceOffset] + column) / this.columns;
                            uv.array[destinationOffset + 1] = (target.baseUv[sourceOffset + 1] + (this.rows - row - 1)) / this.rows;
                        }
                        uv.needsUpdate = true;
                    }
                    return true;
                },
            };
            map.userData.bedrockFlipbookAnimation = animation;
            animationEntries.add(animation);
            activeFlipbookAnimations.add(animation);
            ensureFlipbookAnimationTimer();
            return animation;
        }

        function resolveFaceUncached(blockName, states, face, position = [0,0,0]) {
            const definition = getBlockDefinition(blockName);
            const reference = faceReference(definition, face, states);
            let alias = typeof reference === 'string' ? reference : firstTextureReference(reference);
            let variants = terrainVariants(reference);
            if (!variants.length && alias) variants = terrainVariants(alias);
            let variant = selectedVariant(alias || '', variants, states);
            if (!variant || !resolveFile(variant.path)) {
                const identifier = String(blockName).replace(/^.*:/, '');
                const bases = [];
                const addBase = value => {
                    if (typeof value !== 'string' || !value || bases.includes(value)) return;
                    bases.push(value);
                    const legacy = legacyTextureNameMap[value];
                    if (legacy && !bases.includes(legacy)) bases.push(legacy);
                };
                // Alias references may already be file paths; only bare names can
                // be combined with the blocks/ prefix and face suffixes below.
                if (typeof alias === 'string' && alias && !/[\\/]/.test(alias)) addBase(alias);
                addBase(identifier.replace(/_block$/, ''));
                addBase(identifier);
                const candidates = [];
                for (const base of bases) {
                    for (const prefixed of [`blocks/${base}`, base]) {
                        candidates.push(prefixed);
                        if (face === 'up') candidates.push(`blocks/${base}_top`);
                        else if (face === 'down') candidates.push(`blocks/${base}_bottom`);
                        else {
                            candidates.push(`blocks/${base}_side`);
                            candidates.push(`blocks/${base}_front`);
                        }
                    }
                }
                for (const candidate of candidates) {
                    const filePath = resolveFile(candidate);
                    if (!filePath) continue;
                    variant = {path: candidate, overlayColor: null};
                    alias = candidate;
                    break;
                }
            }
            if (!variant) return null;

            const filePath = resolveFile(variant.path);
            if (!filePath) return null;
            const texture = getTexture(filePath);
            if (!texture) return null;

            const mode = blockRenderMode(blockName);
            const identifier = String(blockName).replace(/^.*:/, '');
            const isGrassBlock = identifier === 'grass_block' || identifier === 'grass';
            const isGrassTop = isGrassBlock && (alias === 'grass_top' || face === 'up');
            const isGrassSide = isGrassBlock
                && ['north', 'south', 'east', 'west'].includes(face)
                && (alias === 'grass_side' || /grass_side(?:\.|$)/.test(String(variant.path || '')));
            const tintMethod = vanillaTintMethod(blockName, states, alias || '', String(variant.path || ''), face);
            let tint = tintMethod !== 'none'
                ? tintColorForMethod(tintMethod)
                : (variant.overlayColor || '#ffffff');
            let opacity = 1;
            if (tintMethod === 'water' || /water/.test(identifier)) {
                const water = biomeWaterAppearance();
                tint = water.color;
                opacity = water.transparency;
            } else if (mode === 'blend' && /(ice|glass)/.test(identifier)) {
                opacity = 0.78;
            }
            const isotropic = definition?.isotropic;
            const isotropicFace = isotropic === true || isotropic?.[face] === true
                || (['north','south','east','west'].includes(face) && isotropic?.side === true);
            const uvQuarterTurns = /rail$/.test(identifier) && face === 'up'
                ? railUvQuarterTurns(states)
                : isotropicFace
                    ? (hashString(`${position.join(',')}:${face}:${blockName}`) & 3)
                    : 0;
            const flipbook = flipbookByAtlasTile.get(alias || '')
                || flipbookByPath.get(String(variant.path || '').replace(/\.(png|tga)$/i, ''));

            // Static block faces go through the shared atlas. Tint is baked into
            // pixels, never into material.color. Animated flipbooks retain their
            // dedicated material path because their UV window changes every tick.
            if (!flipbook) {
                let base = null;
                const layeredGrassSide = Boolean(
                    isGrassSide && !/grass_side_snowed/.test(String(variant.path || ''))
                );
                if (layeredGrassSide) base = grassSideBaseTexture();

                const atlas = atlasAppearance({
                    texture,
                    filePath,
                    path: variant.path,
                    mode,
                    tint,
                    opacity,
                    baseTexture: base?.texture || null,
                    baseFilePath: base?.filePath || null,
                    layeredGrassSide,
                });
                if (atlas?.page?.material) {
                    const material = atlas.page.material;
                    material.userData ||= {};
                    material.userData.bedrockTintMethods ||= new Set();
                    material.userData.bedrockTintMethods.add(tintMethod);
                    material.userData.bedrockAtlasEntries = atlas.page.entries;
                    return {
                        // One geometry buffer per atlas page rather than one per
                        // block texture: this is the actual chunk-atlas fast path.
                        key: atlas.page.key,
                        material,
                        texture,
                        tint,
                        path: variant.path,
                        alias,
                        mode,
                        uvQuarterTurns,
                        uvRect: atlas.uvRect,
                        atlasPage: atlas.page.id,
                        atlasReady: atlas.ready,
                        layeredGrass: layeredGrassSide,
                    };
                }
            }

            // Flipbook / oversized fallback. Keep this path isolated so static
            // terrain never regresses to per-face material tinting.
            const material = materialFromTexture(texture, {
                path: variant.path,
                filePath,
                alias: alias || '',
                blockName,
                tint,
                mode,
                opacity,
                doubleSided: mode === 'alpha_test',
                ambientOcclusionExponent: definition?.ambient_occlusion_exponent,
            });
            material.userData ||= {};
            material.userData.bedrockTintMethod = tintMethod;
            material.userData.bedrockTintColor = tint;
            material.userData.bedrockAlphaMaskedTint = Boolean(isGrassSide && tintMethod === 'grass');
            return {
                key: `pack:${texture.uuid}:${tint}:${mode}:${opacity}`,
                material,
                texture,
                tint,
                path: variant.path,
                alias,
                mode,
                uvQuarterTurns,
                flipbookAnimation: material.userData.bedrockFlipbookAnimation || null,
            };
        }

        function resolveFace(blockName, states, face, position = [0,0,0]) {
            const definition = getBlockDefinition(blockName);
            const isotropic = definition?.isotropic;
            const positionSensitive = isotropic === true || isotropic?.[face] === true
                || (['north','south','east','west'].includes(face) && isotropic?.side === true);
            // The permutation helper belongs to the parser closure. Always use
            // its public API here; an unqualified reference only works inside
            // that closure and made every resource-pack face resolution fail at
            // runtime with `blockPermutationKey is not defined`.
            const permutation = BedrockStructureParser.blockPermutationKey({
                name: String(blockName || 'minecraft:stone'),
                states: states || {},
            });
            const biomeKey = `${Project?.mcstructure_biome || 'minecraft:plains'}:${Number(Project?.mcstructure_biome_tint_index) || 0}:${Project?.mcstructure_fancy_leaves !== false}`;
            const cacheKey = `${permutation}|${face}|${biomeKey}${positionSensitive ? `|${position.join(',')}` : ''}`;
            if (faceDescriptorCache.has(cacheKey)) {
                resolverDiagnostics.faceCacheHits++;
                return faceDescriptorCache.get(cacheKey);
            }
            resolverDiagnostics.faceCacheMisses++;
            const descriptor = resolveFaceUncached(blockName, states, face, position);
            faceDescriptorCache.set(cacheKey, descriptor);
            return descriptor;
        }

        function resolveCube(blockName, states, position = [0,0,0]) {
            const result = {};
            for (const face of ['north','south','east','west','up','down']) {
                const descriptor = resolveFace(blockName, states, face, position);
                if (descriptor?.texture) result[face] = descriptor.texture;
            }
            return result;
        }

        let resolverApi = null;
        function dispose() {
            if (disposed) return;
            disposed = true;
            for (const animation of animationEntries) {
                activeFlipbookAnimations.delete(animation);
                animation.targets?.clear?.();
                if (animation.map?.userData?.bedrockFlipbookAnimation === animation) {
                    delete animation.map.userData.bedrockFlipbookAnimation;
                    delete animation.map.userData.bedrockFlipbook;
                }
            }
            animationEntries.clear();
            for (const material of materialCache.values()) material?.dispose?.();
            materialCache.clear();
            for (const page of atlasPages) page?.material?.dispose?.();
            atlasPages.clear();
            atlasPagesByMode.clear();
            atlasEntryCache.clear();
            faceDescriptorCache.clear();
            customMaterialDescriptorCache.clear();
            customShapeCache.clear();
            customBlockContextCache.clear();
            customGeometryDiagnostics.clear();
            resolvedFileCache.clear();
            blockDefinitionCache.clear();
            clientBiomeComponentsCache.clear();
            layeredTextureCache.clear();
            for (const texture of ownedDerivedTextures) texture?.dispose?.();
            ownedDerivedTextures.clear();
            textureCache.clear();
            textureSetCache.clear();
            for (const texture of heldTextures) {
                const remaining = Math.max(0, (resourcePackTextureReferences.get(texture) || 1) - 1);
                if (remaining) resourcePackTextureReferences.set(texture, remaining);
                else {
                    resourcePackTextureReferences.delete(texture);
                    if (texture.mcstructure_resource_pack_owned === true) {
                        try { texture.remove?.(); } catch {}
                    }
                }
            }
            heldTextures.clear();
            if (resolverApi) resourcePackResolverSet.delete(resolverApi);
        }

        resolverApi = {
            selectedPath,
            rootPath,
            terrain,
            blocks,
            flipbooks,
            biomesClient,
            customGeometryIndex,
            resolveFace,
            resolveCube,
            resolveShape,
            resolveMaterial,
            customGeometryStatus,
            atlasStats() {
                const entries = Array.from(atlasEntryCache.values());
                const ready = entries.reduce((sum, entry) => sum + (entry?.ready ? 1 : 0), 0);
                const geometryDiagnostics = customGeometryDiagnosticSummary();
                return {
                    pages: atlasPages.size,
                    entries: entries.length,
                    ready,
                    pending: Math.max(0, entries.length - ready),
                    byMode: Object.fromEntries(Array.from(atlasPagesByMode, ([mode, pages]) => [mode, pages.length])),
                    customGeometry: {
                        behaviorPack: customGeometryIndex.behaviorPackRoot || null,
                        blocks: customGeometryIndex.blockDefinitions.size,
                        geometries: customGeometryIndex.geometries.size,
                        unsupported: Array.from(customUnsupportedFeatures).sort(),
                        duplicateBlocks: customGeometryIndex.diagnostics.duplicateBlocks,
                        duplicateGeometries: customGeometryIndex.diagnostics.duplicateGeometries,
                        diagnostics: geometryDiagnostics,
                    },
                    cache: {...resolverDiagnostics},
                };
            },
            dispose,
        };
        resourcePackResolverSet.add(resolverApi);
        return resolverApi;
    }

    function applyTextureForBlock(element) {
        const resolver = isStructureProject() ? resourcePackResolvers.get(Project) : null;
        if (resolver) {
            try {
                if (isLegacyStructureCube(element)) {
                    const states = parseObjectJSON(element.mcstructure_states_json || '{}', 'Block states');
                    const textures = resolver.resolveCube(
                        element.mcstructure_block,
                        states,
                        getStructureGridPosition(element)
                    );
                    if (Object.keys(textures).length) applyTextureMapToCube(element, textures);
                } else {
                    element.preview_controller?.updateFaces?.(element);
                }
                return true;
            } catch (error) {
                warnOnce(`texture ${element.mcstructure_block}`, error);
            }
        }
        if (isLegacyStructureCube(element)) applyPreviewTexture(element);
        else element.preview_controller?.updateFaces?.(element);
        return false;
    }

    function applyTextureForCube(cube) {
        return applyTextureForBlock(cube);
    }

    function loadResourcePack(selectedPath, options = {}) {
        if (!isStructureProject()) return;
        const packLoadStarted = typeof performance !== 'undefined' ? performance.now() : Date.now();
        const project = Project;
        const previous = resourcePackResolvers.get(project);
        let resolver = null;
        try {
            // Build the replacement resolver first. The previous atlas remains
            // alive until the new baked meshes are ready, avoiding the black /
            // missing-texture frame that occurred when a pack reload disposed
            // materials still referenced by the current chunk meshes.
            resolver = createResourcePackResolver(selectedPath);
            resourcePackResolvers.set(project, resolver);
            shapeCache.clear();
            project.mcstructure_resource_pack_path = resolver.rootPath || selectedPath;
            if (options.persist !== false) rememberResourcePackPath(project.mcstructure_resource_pack_path);

            const permutations = new Map();
            for (const element of allStructureBlocks()) {
                const statesJson = String(element.mcstructure_states_json || '{}');
                const signature = `${element.mcstructure_block || 'minecraft:stone'}|${statesJson}`;
                const existing = permutations.get(signature);
                if (existing) existing.count += 1;
                else permutations.set(signature, {element, count: 1});
            }

            let applied = 0;
            const missing = new Set();
            for (const {element, count} of permutations.values()) {
                let states = {};
                try { states = parseObjectJSON(element.mcstructure_states_json || '{}', 'Block states'); } catch {}
                const position = getStructureGridPosition(element);
                let resolved = false;
                const customStatus = resolver.customGeometryStatus?.(element.mcstructure_block, states) || null;
                const customShape = resolver.resolveShape?.(element.mcstructure_block, states);
                if (customStatus?.mapped && !customStatus.resolved) {
                    resolved = false;
                } else if (customShape?.source === 'resource_pack_geometry' && Array.isArray(customShape.quads) && customShape.quads.length) {
                    const materialLookups = new Map();
                    resolved = customShape.quads.every(quad => {
                        const face = quad?.face || 'north';
                        const token = String(quad?.materialInstance || face);
                        const key = `${token}|${face}`;
                        if (!materialLookups.has(key)) {
                            materialLookups.set(key, resolver.resolveMaterial?.(
                                element.mcstructure_block,
                                states,
                                token,
                                face,
                                position
                            ) || null);
                        }
                        return Boolean(materialLookups.get(key));
                    });
                } else {
                    resolved = Boolean(
                        resolver.resolveFace(element.mcstructure_block, states, 'up', position)
                        || resolver.resolveFace(element.mcstructure_block, states, 'north', position)
                    );
                }
                if (resolved) applied += count;
                else missing.add(element.mcstructure_block);
            }

            // The baked renderer is the authoritative representation. Building
            // it also populates the shared atlas pages for every visible face;
            // there is deliberately no per-block Texture/preview update pass.
            buildOptimizedPreview();
            previous?.dispose?.();

            if (options.markDirty !== false) project.saved = false;
            const atlas = resolver.atlasStats?.() || {pages: 0, entries: 0};
            recordStructurePerformance('resource_pack', packLoadStarted, {
                applied,
                missing: missing.size,
                permutations: permutations.size,
                atlasPages: Number(atlas.pages || 0),
                atlasEntries: Number(atlas.entries || 0),
            });
            if (!options.silent) {
                Blockbench.showMessageBox({
                    title: tr('bedrock_structure.action.resource_pack', 'Load Bedrock Resource Pack'),
                    message:
                        `Loaded ${resolver.rootPath}.\n\n`
                        + `Resolved ${applied.toLocaleString()} block records across ${permutations.size.toLocaleString()} distinct block/state permutations; `
                        + `${missing.size.toLocaleString()} block type(s) still use fallback previews.\n`
                        + `Static atlas: ${Number(atlas.pages || 0).toLocaleString()} page(s), ${Number(atlas.entries || 0).toLocaleString()} texture tile(s).\n\n`
                        + 'Static full cubes, cross blocks, and other compatible static faces share atlas pages. '
                        + 'Animated flipbooks keep a dedicated animated material path.',
                    icon: missing.size ? 'warning' : 'check_circle',
                });
            }
            return {
                applied,
                missing: missing.size,
                permutations: permutations.size,
                rootPath: resolver.rootPath,
                atlas,
            };
        } catch (error) {
            // If replacement failed, restore the prior resolver and keep its
            // already-rendered materials alive.
            if (resolver && resourcePackResolvers.get(project) === resolver) {
                resolver.dispose?.();
                if (previous) resourcePackResolvers.set(project, previous);
                else resourcePackResolvers.delete(project);
                try {
                    shapeCache.clear();
                    if (previous && isStructureProject(project)) buildOptimizedPreview();
                    else if (!previous) buildOptimizedPreview();
                } catch (restoreError) {
                    warnOnce('resource pack rollback preview', restoreError);
                }
            }
            if (options.silent) warnOnce('restore resource pack', error);
            else showError('load resource pack', error);
        }
    }

    function chooseResourcePack() {
        if (!isStructureProject()) return;
        if (typeof Blockbench.pickDirectory !== 'function') {
            Blockbench.showMessageBox({
                title: tr('bedrock_structure.action.resource_pack', 'Load Bedrock Resource Pack'),
                message: tr(
                    'bedrock_structure.message.pack_desktop',
                    'Resource-pack folder loading is available in Blockbench Desktop.'
                ),
                icon: 'info',
            });
            return;
        }
        const rootPath = Blockbench.pickDirectory({
            resource_id: 'bedrock_structure_resource_pack',
            startpath: Project.mcstructure_resource_pack_path || rememberedResourcePackPath() || undefined,
        });
        if (rootPath) loadResourcePack(rootPath);
    }

    function showStructureSettings() {
        if (!isStructureProject()) return;
        const origin = Project.mcstructure_world_origin || [0, 0, 0];
        new Dialog({
            id: 'bedrock_structure_settings',
            title: 'bedrock_structure.dialog.settings',
            width: 580,
            form: {
                origin_x: {label: 'bedrock_structure.field.origin_x', type: 'number', value: origin[0], step: 1},
                origin_y: {label: 'bedrock_structure.field.origin_y', type: 'number', value: origin[1], step: 1},
                origin_z: {label: 'bedrock_structure.field.origin_z', type: 'number', value: origin[2], step: 1},
                default_block: {
                    label: 'bedrock_structure.field.default_block',
                    type: 'text',
                    value: Project.mcstructure_default_block,
                },
                version: {
                    label: 'bedrock_structure.field.version',
                    type: 'number',
                    value: Project.mcstructure_default_version,
                    step: 1,
                },
                fit_bounds: {
                    label: 'bedrock_structure.field.fit_bounds',
                    type: 'checkbox',
                    value: Project.mcstructure_fit_bounds,
                },
                compact: {
                    label: 'bedrock_structure.field.compact',
                    type: 'checkbox',
                    value: Project.mcstructure_compact_palette,
                },
                secondary_visible: {
                    label: 'bedrock_structure.field.secondary_visible',
                    type: 'checkbox',
                    value: Project.mcstructure_secondary_visible,
                },
                biome: {
                    label: 'Preview biome',
                    description: '.mcstructure files do not store biome data. This controls Bedrock grass/water tint preview.',
                    type: 'text',
                    value: Project.mcstructure_biome || 'minecraft:plains',
                },
                biome_tint_index: {
                    label: 'Grass tint variant',
                    description: 'Bedrock terrain_texture grass variant index. 0 is the vanilla plains-style default.',
                    type: 'number',
                    value: Number(Project.mcstructure_biome_tint_index) || 0,
                    min: 0,
                    max: 16,
                    step: 1,
                },
                fancy_leaves: {
                    label: 'Fancy leaves',
                    description: 'Use the transparent vanilla leaves texture variant instead of the opaque fallback.',
                    type: 'checkbox',
                    value: Project.mcstructure_fancy_leaves !== false,
                },
            },
            onConfirm(result) {
                try {
                    const nextOrigin = [result.origin_x, result.origin_y, result.origin_z].map(Number);
                    if (!nextOrigin.every(Number.isSafeInteger)) {
                        throw new TypeError('World origin values must be safe integers.');
                    }
                    if (!nextOrigin.every(value => value >= NBT_INT_MIN && value <= NBT_INT_MAX)) {
                        throw new RangeError('World origin values must fit in signed 32-bit NBT integers.');
                    }
                    const version = Number(result.version);
                    if (!Number.isInteger(version)) throw new TypeError('Block version must be an integer.');
                    const defaultBlock = String(result.default_block).trim();
                    if (!defaultBlock) throw new TypeError('Default block identifier cannot be empty.');
                    const updated = runLogicalUndo(
                        tr('bedrock_structure.undo.edit_settings', 'Edit structure settings'),
                        () => {
                            Project.mcstructure_world_origin = nextOrigin;
                            Project.mcstructure_default_block = defaultBlock.includes(':')
                                ? defaultBlock
                                : `minecraft:${defaultBlock}`;
                            Project.mcstructure_default_version = version;
                            Project.mcstructure_fit_bounds = Boolean(result.fit_bounds);
                            Project.mcstructure_compact_palette = Boolean(result.compact);
                            setSecondaryLayerVisible(Boolean(result.secondary_visible), {rebuild: false, undo: false});
                            Project.mcstructure_biome = String(result.biome || 'minecraft:plains').trim() || 'minecraft:plains';
                            Project.mcstructure_biome_tint_index = Math.max(0, Math.min(16, Math.round(Number(result.biome_tint_index) || 0)));
                            Project.mcstructure_fancy_leaves = result.fancy_leaves !== false;
                            buildOptimizedPreview();
                            Project.saved = false;
                            return true;
                        },
                        {targets: {ids: [], keys: [], positionData: false, selection: false}}
                    );
                    if (!updated) return;
                    this.hide();
                } catch (error) {
                    showError('structure settings', error);
                }
            },
        }).show();
    }

    function requiredTextureFacesForShape(shape) {
        const faces = new Set();
        // Every box can expose any of its six boundary faces depending on its
        // neighbors. A resource pack is only fully resolved for that shape if all
        // six renderer face lookups succeed; checking only top/north produced
        // false positives for blocks with a valid top texture but missing sides.
        if (Array.isArray(shape?.boxes) && shape.boxes.length) {
            for (const face of SHAPE_FACE_NAMES) faces.add(face);
        }
        // Custom quads use their declared face token verbatim in
        // faceTextureMaterial(), including renderer-specific values such as
        // `cross`, so mirror that lookup here rather than guessing a side face.
        for (const quad of shape?.quads || []) faces.add(quad?.materialInstance || quad?.face || 'north');
        if (!faces.size) faces.add('north');
        return Array.from(faces);
    }

    function analyzeStructureCompatibility() {
        const runtime = ensureLogicalRuntime();
        const report = {
            records: 0,
            permutations: 0,
            shapes: {exact: 0, derived: 0, approximate: 0, genericFull: 0},
            shapePermutations: {exact: 0, derived: 0, approximate: 0, genericFull: 0},
            textures: {packLoaded: false, resolved: 0, missing: 0, missingBlocks: [], missingFaces: {}},
            customGeometry: {
                diagnostics: {total: 0, counts: {}, details: [], truncated: 0},
            },
            positionData: {coordinates: 0, blockEntities: 0, scheduledTickCoordinates: 0, unknownTagCoordinates: 0},
        };
        if (!runtime) return report;

        const permutations = new Map();
        for (const record of runtime.records || []) {
            if (record.export === false) continue;
            report.records++;
            const states = cachedParsedBlockStates(record);
            const override = record.mcstructure_shape_override || 'auto';
            const signature = blockShapeCacheKey(record.mcstructure_block, states, override);
            const existing = permutations.get(signature);
            if (existing) existing.count++;
            else permutations.set(signature, {record, states, override, count: 1});
        }
        report.permutations = permutations.size;

        const resolver = isStructureProject() ? resourcePackResolvers.get(Project) : null;
        report.textures.packLoaded = Boolean(resolver);
        const missingBlocks = new Set();
        const recordMap = optimizedPreview?.recordMap || null;
        for (const {record, states, override, count} of permutations.values()) {
            const view = {
                element: record,
                block: record.mcstructure_block,
                layer: Number(record.mcstructure_layer || 0),
                position: getStructureGridPosition(record),
            };
            const renderStates = deriveConnectedBlockStates(view, recordMap, states);
            const derived = !logicalStatesEqual(states, renderStates);
            const shape = resolveBlockShape(record.mcstructure_block, renderStates, override);
            const category = shape.approximate
                ? 'approximate'
                : shape.source === 'fallback_full'
                    ? 'genericFull'
                    : derived
                        ? 'derived'
                        : 'exact';
            report.shapes[category] += count;
            report.shapePermutations[category]++;

            if (resolver) {
                const missingFaces = [];
                const customStatus = resolver.customGeometryStatus?.(record.mcstructure_block, renderStates) || null;
                if (customStatus?.mapped && !customStatus.resolved) {
                    missingFaces.push(`geometry:${customStatus.geometryIdentifier || 'missing'}`);
                } else {
                    for (const face of requiredTextureFacesForShape(shape)) {
                        let descriptor = null;
                        try {
                            descriptor = shape.source === 'resource_pack_geometry' && typeof resolver.resolveMaterial === 'function'
                                ? resolver.resolveMaterial(record.mcstructure_block, renderStates, face, face, view.position)
                                : resolver.resolveFace(record.mcstructure_block, renderStates, face, view.position);
                        } catch {}
                        // The baked renderer accepts a resource-pack face only when it
                        // supplied an actual material; otherwise it intentionally uses
                        // the generated fallback atlas. Report the same distinction.
                        if (!descriptor?.material) missingFaces.push(face);
                    }
                }
                if (!missingFaces.length) report.textures.resolved += count;
                else {
                    report.textures.missing += count;
                    missingBlocks.add(record.mcstructure_block);
                    const key = record.mcstructure_block;
                    const aggregate = new Set(report.textures.missingFaces[key] || []);
                    missingFaces.forEach(face => aggregate.add(face));
                    report.textures.missingFaces[key] = Array.from(aggregate).sort();
                }
            }
        }
        report.textures.missingBlocks = Array.from(missingBlocks).sort();
        if (resolver) {
            report.customGeometry = resolver.atlasStats?.().customGeometry || report.customGeometry;
        }

        runtime.positionData ||= new Map();
        report.positionData.coordinates = runtime.positionData.size;
        for (const raw of runtime.positionData.values()) {
            try {
                const node = parseTypedNBT(raw, 'Position data');
                if (!node || node.type !== BedrockStructureParser.NBT_TAG.Compound) continue;
                const keys = Object.keys(node.value || {});
                if (getCompoundChild(node, 'block_entity_data')) report.positionData.blockEntities++;
                if (getCompoundChild(node, 'tick_queue_data')) report.positionData.scheduledTickCoordinates++;
                if (keys.some(key => key !== 'block_entity_data' && key !== 'tick_queue_data')) {
                    report.positionData.unknownTagCoordinates++;
                }
            } catch {}
        }
        return report;
    }

    function currentStructureValidationToken(project = Project, runtime = ensureLogicalRuntime()) {
        if (!project || !runtime) return '';
        const entityParts = [];
        if (typeof Locator !== 'undefined' && Array.isArray(Locator.all)) {
            for (const locator of Locator.all) {
                if (!locator?.mcstructure_entity) continue;
                entityParts.push([
                    locator.uuid || locator.name || '',
                    locator.mcstructure_entity_nbt_json || '',
                    Array.isArray(locator.from) ? locator.from.join(',') : '',
                    Array.isArray(locator.rotation) ? locator.rotation.join(',') : '',
                ].join('|'));
            }
        }
        return JSON.stringify({
            revision: Number(runtime.revision || 0),
            origin: Array.isArray(project.mcstructure_world_origin) ? project.mcstructure_world_origin.slice(0, 3) : [0,0,0],
            boundsMinimum: Array.isArray(project.mcstructure_bounds_min) ? project.mcstructure_bounds_min.slice(0, 3) : [0,0,0],
            size: Array.isArray(project.mcstructure_size) ? project.mcstructure_size.slice(0, 3) : [1,1,1],
            defaultBlock: project.mcstructure_default_block || 'minecraft:stone',
            defaultVersion: Number(project.mcstructure_default_version) || 18168865,
            fitBounds: project.mcstructure_fit_bounds === true,
            compactPalette: project.mcstructure_compact_palette === true,
            entities: entityParts,
        });
    }

    function collectLiveStructureSummary(project = Project, runtime = ensureLogicalRuntime()) {
        if (!project || !runtime) return null;
        const baseMinimum = Array.isArray(project.mcstructure_bounds_min)
            ? project.mcstructure_bounds_min.slice(0, 3).map(value => Math.round(Number(value) || 0))
            : [0,0,0];
        const baseSize = Array.isArray(project.mcstructure_size)
            ? project.mcstructure_size.slice(0, 3).map(value => Math.max(1, Math.round(Number(value) || 1)))
            : [1,1,1];
        let minimum = project.mcstructure_fit_bounds === true
            ? [Infinity, Infinity, Infinity]
            : baseMinimum.slice();
        let maximum = project.mcstructure_fit_bounds === true
            ? [-Infinity, -Infinity, -Infinity]
            : baseMinimum.map((value, axis) => value + baseSize[axis] - 1);
        let primaryCount = 0;
        let secondaryCount = 0;
        const usedPermutations = new Set();
        for (const record of runtime.records) {
            if (!record || record.export === false) continue;
            const position = getStructureGridPosition(record);
            for (let axis = 0; axis < 3; axis++) {
                minimum[axis] = Math.min(minimum[axis], position[axis]);
                maximum[axis] = Math.max(maximum[axis], position[axis]);
            }
            if (Number(record.mcstructure_layer || 0) === 1) secondaryCount += 1;
            else primaryCount += 1;
            usedPermutations.add(BedrockStructureParser.blockPermutationKey({
                name: record.mcstructure_block,
                states: cachedParsedBlockStates(record),
                version: record.mcstructure_version,
            }));
        }
        if (!minimum.every(Number.isFinite)) {
            minimum = [0,0,0];
            maximum = [0,0,0];
        }
        const size = minimum.map((value, axis) => maximum[axis] - value + 1);
        const volume = size.reduce((product, value) => product * value, 1);
        const projectOrigin = Array.isArray(project.mcstructure_world_origin)
            ? project.mcstructure_world_origin.slice(0, 3).map(value => Number(value) || 0)
            : [0,0,0];
        const worldOrigin = projectOrigin.map((value, axis) => value + minimum[axis]);
        const entityCount = typeof Locator !== 'undefined' && Array.isArray(Locator.all)
            ? Locator.all.reduce((count, locator) => count + (locator?.mcstructure_entity ? 1 : 0), 0)
            : 0;
        return {
            minimum,
            maximum,
            size,
            volume,
            worldOrigin,
            primaryCount,
            secondaryCount,
            primaryVoid: Math.max(0, volume - primaryCount),
            secondaryVoid: Math.max(0, volume - secondaryCount),
            usedPermutations: usedPermutations.size,
            paletteEntries: Math.max(runtime.palettePermutations?.length || 0, usedPermutations.size),
            positionDataCount: runtime.positionData?.size || 0,
            entityCount,
        };
    }

    function validateStructureExportNBT(options = {}) {
        if (!isStructureProject()) return false;
        Blockbench.setProgress?.(0.08);
        Blockbench.setStatusBarText?.(tr('bedrock_structure.status.validating', 'Validating export NBT…'));
        try {
            const runtime = ensureLogicalRuntime();
            compileStructureSnapshot(collectProjectSnapshot());
            Blockbench.setProgress?.(0.96);
            if (runtime) runtime.lastValidationToken = currentStructureValidationToken(Project, runtime);
            if (options.silent !== true) {
                Blockbench.showQuickMessage(
                    tr('bedrock_structure.message.valid', 'The exported NBT passed strict round-trip validation.'),
                    3200
                );
            }
            return true;
        } catch (error) {
            showError('validate structure export', error);
            return false;
        } finally {
            Blockbench.setProgress?.();
            Blockbench.setStatusBarText?.();
        }
    }

    function showStructureInfo() {
        if (!isStructureProject()) return;
        try {
            const runtime = ensureLogicalRuntime();
            const summary = collectLiveStructureSummary(Project, runtime);
            if (!summary) return;
            const compatibility = analyzeStructureCompatibility();
            const validationCurrent = Boolean(
                runtime?.lastValidationToken
                && runtime.lastValidationToken === currentStructureValidationToken(Project, runtime)
            );
            const textureLine = compatibility.textures.packLoaded
                ? `Resource-pack textures: ${compatibility.textures.resolved.toLocaleString()} resolved records · ${compatibility.textures.missing.toLocaleString()} fallback records`
                : 'Resource-pack textures: no pack loaded · generated previews are in use';
            const missingPreview = compatibility.textures.missingBlocks.slice(0, 8);
            const missingLine = missingPreview.length
                ? `Missing texture block types: ${missingPreview.map(name => `\`${name}\``).join(', ')}${compatibility.textures.missingBlocks.length > missingPreview.length ? ` +${compatibility.textures.missingBlocks.length - missingPreview.length} more` : ''}`
                : '';
            const customDiagnostics = compatibility.customGeometry?.diagnostics || {total: 0, counts: {}, details: [], truncated: 0};
            const customDiagnosticLine = customDiagnostics.total
                ? `Custom geometry diagnostics: ${Number(customDiagnostics.counts?.missing_geometry || 0).toLocaleString()} missing geometry · ${Number(customDiagnostics.counts?.dangling_material_alias || 0).toLocaleString()} dangling material alias · ${Number(customDiagnostics.counts?.material_alias_cycle || 0).toLocaleString()} alias cycle`
                : '';
            const customDiagnosticPreview = (customDiagnostics.details || []).slice(0, 6).map(diagnostic => {
                const subject = diagnostic.block || diagnostic.geometry || 'custom block';
                const target = diagnostic.target || diagnostic.alias || diagnostic.geometry || '';
                const material = diagnostic.materialInstance ? ` material \`${diagnostic.materialInstance}\`` : '';
                return `\`${diagnostic.type}\`: \`${subject}\`${material}${target ? ` → \`${target}\`` : ''}`;
            });
            const customDiagnosticDetails = customDiagnosticPreview.length
                ? `Custom geometry details: ${customDiagnosticPreview.join(' · ')}${customDiagnostics.total > customDiagnosticPreview.length ? ` · +${customDiagnostics.total - customDiagnosticPreview.length} more` : ''}`
                : '';
            const message = [
                `**${summary.size[0]} × ${summary.size[1]} × ${summary.size[2]}** (${summary.volume.toLocaleString()} cells)`,
                `World origin: \`${summary.worldOrigin.join(', ')}\``,
                `Palette: \`${Project.mcstructure_palette_name || 'default'}\` · ${summary.paletteEntries.toLocaleString()} entries · ${summary.usedPermutations.toLocaleString()} used permutations`,
                `Primary void: ${summary.primaryVoid.toLocaleString()} · Secondary void: ${summary.secondaryVoid.toLocaleString()}`,
                `Block position data: ${summary.positionDataCount.toLocaleString()} · Entities: ${summary.entityCount.toLocaleString()}`,
                `Position NBT: ${compatibility.positionData.blockEntities.toLocaleString()} block entities · ${compatibility.positionData.scheduledTickCoordinates.toLocaleString()} tick queues · ${compatibility.positionData.unknownTagCoordinates.toLocaleString()} coordinate(s) with extension tags`,
                '',
                '**Preview compatibility**',
                `Exact shapes: ${compatibility.shapes.exact.toLocaleString()} · Topology-derived: ${compatibility.shapes.derived.toLocaleString()} · Approximate: ${compatibility.shapes.approximate.toLocaleString()} · Generic full-cube: ${compatibility.shapes.genericFull.toLocaleString()}`,
                `Distinct rendered permutations: ${compatibility.permutations.toLocaleString()} (${compatibility.shapePermutations.approximate.toLocaleString()} approximate · ${compatibility.shapePermutations.genericFull.toLocaleString()} generic full-cube)`,
                textureLine,
                missingLine,
                customDiagnosticLine,
                customDiagnosticDetails,
                compatibility.shapes.genericFull
                    ? 'Generic full-cube resolution is not automatically an error: ordinary solid blocks use it efficiently, while unknown/custom partial geometry should be reviewed or given a preview-shape override.'
                    : '',
                '',
                validationCurrent
                    ? tr('bedrock_structure.message.validation_current', 'Export NBT validation is current for this project revision.')
                    : tr('bedrock_structure.message.validation_stale', 'Export NBT has not been validated since the latest edit. Structure statistics below are live and do not require a compile.'),
            ].filter(Boolean).join('\n\n');
            Blockbench.showMessageBox({
                title: tr('bedrock_structure.dialog.info', 'Bedrock Structure Information'),
                message,
                icon: 'fact_check',
                width: 700,
                commands: {
                    validate_export: {
                        text: tr('bedrock_structure.action.validate_now', 'Validate Export NBT'),
                        icon: 'verified',
                        description: tr(
                            'bedrock_structure.action.validate_now.desc',
                            'Compile and strictly round-trip validate the current .mcstructure export on demand.'
                        ),
                    },
                },
                buttons: ['dialog.close'],
            }, result => {
                if (result !== 'validate_export') return;
                if (validateStructureExportNBT()) showStructureInfo();
            });
        } catch (error) {
            showError('structure information', error);
        }
    }

    function openStructureFile(file) {
        try {
            // Let Codec.parse consume the original bytes once. Pre-parsing here
            // forced a second serialization merely to preserve the source blob.
            codec.load(file.content, file);
        } catch (error) {
            showError('open structure', error);
        }
    }

    /**
     * Run the stock Codec.load flow with verified binary input so
     * setupProject, project naming, export path bookkeeping, and recent
     * projects stay native while parse() receives intact NBT bytes.
     */
    function loadStructureBytes(bytes, file, args, targetCodec) {
        const usable = bytes instanceof BedrockStructureParser.MinecraftBedrockStructure
            || bytes instanceof ArrayBuffer
            || ArrayBuffer.isView(bytes);
        if (!usable) {
            showError('open structure', new Error(
                'The .mcstructure content could not be recovered as binary NBT. '
                + 'Use the Bedrock Structure open action instead.'
            ));
            return;
        }
        try {
            Codec.prototype.load.call(targetCodec, bytes, file, args);
        } catch (error) {
            showError('open structure', error);
        }
    }

    function openStructureDialog() {
        Blockbench.import({
            resource_id: 'model',
            type: tr('bedrock_structure.format.name', 'Minecraft Bedrock Structure'),
            extensions: ['mcstructure'],
            readtype: 'buffer',
            multiple: false,
        }, files => {
            if (files && files[0]) openStructureFile(files[0]);
        });
    }

    function openOrCreateStructure() {
        Blockbench.showMessageBox({
            title: tr('bedrock_structure.format.name', 'Minecraft Bedrock Structure'),
            message: 'Open an existing .mcstructure directly, or create a blank Bedrock structure project.',
            icon: 'view_in_ar',
            commands: {
                open_structure: {
                    text: 'Open .mcstructure',
                    icon: 'file_open',
                    description: 'Open a Bedrock structure as a new Blockbench project.',
                },
                new_structure: {
                    text: 'Create blank structure',
                    icon: 'note_add',
                    description: 'Create an empty structure with custom size and world origin.',
                },
            },
            buttons: ['dialog.cancel'],
        }, result => {
            if (result === 'open_structure') openStructureDialog();
            else if (result === 'new_structure') createNewStructure();
        });
        return true;
    }

    function createNewStructure() {
        new Dialog({
            id: 'bedrock_structure_new',
            title: 'bedrock_structure.dialog.new',
            width: 560,
            form: {
                size_x: {label: 'bedrock_structure.field.size_x', type: 'number', value: 16, min: 1, step: 1},
                size_y: {label: 'bedrock_structure.field.size_y', type: 'number', value: 16, min: 1, step: 1},
                size_z: {label: 'bedrock_structure.field.size_z', type: 'number', value: 16, min: 1, step: 1},
                origin_x: {label: 'bedrock_structure.field.origin_x', type: 'number', value: 0, step: 1},
                origin_y: {label: 'bedrock_structure.field.origin_y', type: 'number', value: 0, step: 1},
                origin_z: {label: 'bedrock_structure.field.origin_z', type: 'number', value: 0, step: 1},
                version: {
                    label: 'bedrock_structure.field.version',
                    type: 'number',
                    value: 18168865,
                    step: 1,
                },
            },
            onConfirm(result) {
                try {
                    const size = [result.size_x, result.size_y, result.size_z].map(Number);
                    const origin = [result.origin_x, result.origin_y, result.origin_z].map(Number);
                    const version = Number(result.version);
                    if (!size.every(value => Number.isInteger(value) && value > 0)) {
                        throw new TypeError('Structure dimensions must be positive integers.');
                    }
                    if (!origin.every(Number.isSafeInteger)) throw new TypeError('World origin values must be safe integers.');
                    if (!origin.every(value => value >= NBT_INT_MIN && value <= NBT_INT_MAX)) {
                        throw new RangeError('World origin values must fit in signed 32-bit NBT integers.');
                    }
                    if (!Number.isInteger(version)) throw new TypeError('Block version must be an integer.');
                    const editor = BedrockStructureParser.MinecraftBedrockStructureEditor.create({
                        size,
                        worldOrigin: origin,
                        blockVersion: version,
                        sourceName: 'structure.mcstructure',
                    });
                    const bytes = editor.toUint8Array();
                    setupProject(format);
                    Project.name = 'structure';
                    Project.export_codec = CODEC_ID;
                    buildProjectFromStructure(editor.build(), bytes);
                    this.hide();
                } catch (error) {
                    showError('create structure', error);
                }
            },
        }).show();
        return true;
    }

    function registerProperty(target, type, name, options = {}) {
        const property = new Property(target, type, name, options);
        properties.push(property);
        return property;
    }


    function structureHotbarCanvasRect() {
        if (typeof Preview === 'undefined' || !Array.isArray(Preview.all)) return null;
        let best = null;
        for (const preview of Preview.all) {
            const canvas = preview?.canvas || preview?.node?.querySelector?.('canvas');
            const rect = canvas?.getBoundingClientRect?.();
            if (!rect || rect.width < 80 || rect.height < 80) continue;
            if (!best || rect.width * rect.height > best.width * best.height) best = rect;
        }
        return best;
    }

    function updateStructureHotbarPosition(placementOverride = null) {
        if (!structureHotbarRoot) return;
        const visible = isStructureProject() && isStructureModeSelected();
        structureHotbarRoot.classList.toggle('is-visible', visible);
        structureHotbarRoot.setAttribute('aria-hidden', visible ? 'false' : 'true');
        if (!visible) return;
        const rect = structureHotbarCanvasRect();
        if (!rect) return;
        const placement = placementOverride || structureHotbarDragState?.placement || structureHotbarPlacementPreference();
        const mode = placement.mode || 'bottom';
        let x = Number(placement.x);
        let y = Number(placement.y);
        if (!Number.isFinite(x)) x = rect.left + rect.width / 2;
        if (!Number.isFinite(y)) y = rect.bottom - 52;
        if (mode === 'bottom') {
            x = rect.left + rect.width / 2;
            y = rect.bottom - 52;
        } else if (mode === 'left') {
            x = rect.left + 48;
            y = Math.max(rect.top + 110, Math.min(rect.bottom - 110, y));
        } else if (mode === 'right') {
            x = rect.right - 48;
            y = Math.max(rect.top + 110, Math.min(rect.bottom - 110, y));
        }
        const vertical = mode === 'left' || mode === 'right';
        const namePosition = placement.namePosition || (y > rect.top + rect.height / 2 ? 'above' : 'below');
        structureHotbarRoot.classList.toggle('is-vertical', vertical);
        structureHotbarRoot.dataset.dock = mode;
        structureHotbarRoot.dataset.namePosition = namePosition;
        const barRect = structureHotbarRoot.getBoundingClientRect?.();
        const halfWidth = Math.max(28, Number(barRect?.width || 84) / 2);
        const halfHeight = Math.max(28, Number(barRect?.height || 84) / 2);
        if (mode === 'left') x = rect.left + halfWidth + 8;
        else if (mode === 'right') x = rect.right - halfWidth - 8;
        else x = Math.max(rect.left + halfWidth, Math.min(rect.right - halfWidth, x));
        y = Math.max(rect.top + halfHeight + 8, Math.min(rect.bottom - halfHeight - 8, y));
        structureHotbarRoot.style.left = `${Math.round(x)}px`;
        structureHotbarRoot.style.top = `${Math.round(y)}px`;
        structureHotbarRoot.style.bottom = 'auto';
    }

    function updateStructureHotbarDrag(event) {
        const drag = structureHotbarDragState;
        if (!drag || drag.pointerId !== event.pointerId) return;
        const rect = structureHotbarCanvasRect();
        if (!rect) return;
        const edgeZone = Math.max(72, Math.min(130, rect.width * 0.12));
        let mode = 'free';
        if (event.clientX <= rect.left + edgeZone) mode = 'left';
        else if (event.clientX >= rect.right - edgeZone) mode = 'right';
        drag.placement = {
            mode,
            x: event.clientX,
            y: event.clientY,
            namePosition: event.clientY > rect.top + rect.height / 2 ? 'above' : 'below',
        };
        updateStructureHotbarPosition(drag.placement);
        event.preventDefault?.();
        event.stopPropagation?.();
    }

    function finishStructureHotbarDrag(event) {
        const drag = structureHotbarDragState;
        if (!drag || (event && drag.pointerId !== event.pointerId)) return false;
        structureHotbarDragState = null;
        if (drag.placement) persistStructureHotbarPlacement(drag.placement);
        if (typeof document !== 'undefined') {
            if (structureHotbarDragMoveHandler) document.removeEventListener('pointermove', structureHotbarDragMoveHandler, true);
            if (structureHotbarDragEndHandler) {
                document.removeEventListener('pointerup', structureHotbarDragEndHandler, true);
                document.removeEventListener('pointercancel', structureHotbarDragEndHandler, true);
            }
        }
        structureHotbarDragMoveHandler = null;
        structureHotbarDragEndHandler = null;
        updateStructureHotbarPosition();
        event?.preventDefault?.();
        event?.stopPropagation?.();
        return true;
    }

    function beginStructureHotbarDrag(event) {
        if (event.button !== 0 || typeof document === 'undefined') return;
        const placement = structureHotbarPlacementPreference();
        structureHotbarDragState = {pointerId: event.pointerId, placement};
        structureHotbarDragMoveHandler = updateStructureHotbarDrag;
        structureHotbarDragEndHandler = finishStructureHotbarDrag;
        document.addEventListener('pointermove', structureHotbarDragMoveHandler, true);
        document.addEventListener('pointerup', structureHotbarDragEndHandler, true);
        document.addEventListener('pointercancel', structureHotbarDragEndHandler, true);
        updateStructureHotbarDrag(event);
    }

    function makeStructureHotbarIcon(slot) {
        const thumbnail = structureBlockThumbnail(slot.block, slot.statesJson);
        if (thumbnail) {
            const image = document.createElement('img');
            image.className = 'bedrock-structure-hotbar-thumb';
            image.src = thumbnail;
            image.alt = '';
            image.draggable = false;
            return image;
        }
        const icon = document.createElement('i');
        icon.className = 'material-icons bedrock-structure-hotbar-fallback';
        icon.textContent = slot.block === 'minecraft:air' ? 'blur_on' : 'deployed_code';
        icon.setAttribute('aria-hidden', 'true');
        return icon;
    }

    function refreshStructureHotbar() {
        if (!structureHotbarRoot) return;
        ensureStructureHotbarState();
        const slotsHost = structureHotbarRoot.querySelector('.bedrock-structure-hotbar-slots');
        if (!slotsHost) return;
        slotsHost.replaceChildren();
        structureHotbarSlots.forEach((slot, index) => {
            const button = document.createElement('button');
            button.type = 'button';
            button.className = 'bedrock-structure-hotbar-slot';
            if (index === structureActiveHotbarSlot) button.classList.add('is-active');
            button.dataset.slot = String(index);
            const displayName = structureBlockDisplayName(slot.block);
            button.title = `${index + 1} · ${displayName}\n${slot.block}`;
            button.setAttribute('aria-label', `${index + 1}. ${displayName}`);

            const number = document.createElement('span');
            number.className = 'bedrock-structure-hotbar-number';
            number.textContent = String(index + 1);
            button.append(number, makeStructureHotbarIcon(slot));

            const layer = document.createElement('span');
            layer.className = 'bedrock-structure-hotbar-layer';
            layer.textContent = trf('bedrock_structure.ui.layer_short', 'L{0}', [slot.layer + 1]);
            button.appendChild(layer);
            slotsHost.appendChild(button);
        });
        const brush = activeStructureBrushDescriptor();
        const label = structureHotbarRoot.querySelector('.bedrock-structure-hotbar-current');
        if (label) label.textContent = structureBlockDisplayName(brush.block);
        const layerButton = structureHotbarRoot.querySelector('.bedrock-structure-hotbar-layer-toggle');
        if (layerButton) {
            layerButton.textContent = trf('bedrock_structure.ui.layer_short', 'L{0}', [brush.layer + 1]);
            layerButton.title = brush.layer === 0
                ? tr('bedrock_structure.field.layer_primary', 'Primary')
                : tr('bedrock_structure.field.layer_secondary', 'Secondary');
        }
        structureHotbarRoot.dataset.tool = structureToolKind();
        updateStructureHotbarPosition();
    }

    function showStructureInventory(slotIndex = structureActiveHotbarSlot) {
        if (!isStructureProject()) return null;
        ensureStructureHotbarState();
        const targetSlot = Math.max(0, Math.min(STRUCTURE_HOTBAR_SIZE - 1, Number(slotIndex) || 0));
        const items = structureInventoryCatalog();
        structureInventoryDialog?.hide?.();
        const dialog = new Dialog({
            id: 'bedrock_structure_inventory',
            title: 'bedrock_structure.ui.inventory',
            width: 820,
            buttons: ['dialog.close'],
            component: {
                data() {
                    return {
                        query: '',
                        items,
                        targetSlot,
                        selectedBlock: structureHotbarSlots[targetSlot]?.block || '',
                    };
                },
                computed: {
                    filteredItems() {
                        const query = String(this.query || '').trim().toLowerCase();
                        if (!query) return this.items;
                        return this.items.filter(item => item.block.toLowerCase().includes(query) || item.name.toLowerCase().includes(query));
                    },
                    slotLabel() {
                        return trf('bedrock_structure.ui.inventory.slot', 'Assign to hotbar slot {0}', [this.targetSlot + 1]);
                    },
                },
                methods: {
                    t(key, fallback) { return tr(key, fallback); },
                    choose(item) {
                        const current = activeStructureBrushDescriptor();
                        setStructureHotbarSlot(this.targetSlot, {
                            block: item.block,
                            statesJson: '{}',
                            version: Number(Project?.mcstructure_default_version) || current.version,
                            layer: current.layer,
                        });
                        selectStructureTool(STRUCTURE_TOOL_IDS.place);
                        this.selectedBlock = item.block;
                        structureInventoryDialog?.hide?.();
                    },
                    sourceLabel(source) {
                        if (source === 'structure') return this.t('bedrock_structure.ui.inventory.used', 'Used in this structure');
                        if (source === 'resource_pack') return this.t('bedrock_structure.ui.inventory.pack', 'Resource pack');
                        return this.t('bedrock_structure.ui.inventory.builtin', 'Common blocks');
                    },
                },
                template: `
                    <div class="bedrock-structure-inventory">
                        <div class="bedrock-structure-inventory-head">
                            <div class="bedrock-structure-inventory-slot"><i class="material-icons">view_in_ar</i><span>{{ slotLabel }}</span></div>
                            <label class="bedrock-structure-inventory-search">
                                <i class="material-icons">search</i>
                                <input v-model="query" type="search" :placeholder="t('bedrock_structure.ui.inventory.search', 'Search blocks…')" autofocus>
                            </label>
                        </div>
                        <div v-if="filteredItems.length" class="bedrock-structure-inventory-grid">
                            <button
                                v-for="item in filteredItems"
                                :key="item.block"
                                type="button"
                                class="bedrock-structure-inventory-card"
                                :class="{'is-selected': item.block === selectedBlock}"
                                :title="item.block"
                                @click="choose(item)"
                            >
                                <span class="bedrock-structure-inventory-icon">
                                    <img v-if="item.thumbnail" :src="item.thumbnail" alt="">
                                    <i v-else class="material-icons">{{ item.block === 'minecraft:air' ? 'blur_on' : 'deployed_code' }}</i>
                                </span>
                                <span class="bedrock-structure-inventory-name">{{ item.name }}</span>
                                <small>{{ sourceLabel(item.source) }}<template v-if="item.count"> · {{ item.count }}</template></small>
                            </button>
                        </div>
                        <div v-else class="bedrock-structure-inventory-empty">
                            <i class="material-icons">search_off</i>
                            <span>{{ t('bedrock_structure.ui.inventory.empty', 'No blocks match this search.') }}</span>
                        </div>
                    </div>
                `,
            },
            onCancel() {
                structureInventoryDialog = null;
            },
        });
        structureInventoryDialog = dialog;
        dialog.show();
        return dialog;
    }

    function createStructureHotbar() {
        if (structureHotbarRoot || typeof document === 'undefined') return structureHotbarRoot;
        ensureStructureHotbarState();
        const root = document.createElement('div');
        root.id = 'bedrock_structure_hotbar';
        root.className = 'bedrock-structure-hotbar';
        root.setAttribute('role', 'toolbar');
        root.setAttribute('aria-label', tr('bedrock_structure.ui.hotbar', 'Structure hotbar'));
        root.innerHTML = `
            <button type="button" class="bedrock-structure-hotbar-grip" data-action="drag" title="${tr('bedrock_structure.ui.hotbar_drag', 'Drag hotbar · move to a side to dock vertically')}"><i class="material-icons">drag_indicator</i></button>
            <button type="button" class="bedrock-structure-hotbar-inventory" data-action="inventory" title="${tr('bedrock_structure.action.inventory', 'Open Block Inventory')}"><i class="material-icons">apps</i></button>
            <div class="bedrock-structure-hotbar-slots"></div>
            <button type="button" class="bedrock-structure-hotbar-layer-toggle" data-action="layer"></button>
            <span class="bedrock-structure-hotbar-current"></span>
        `;
        root.addEventListener('pointerdown', event => {
            const action = event.target?.closest?.('[data-action]')?.dataset?.action;
            if (action === 'drag') {
                beginStructureHotbarDrag(event);
                return;
            }
            event.stopPropagation();
        });
        root.addEventListener('click', event => {
            const slotButton = event.target?.closest?.('[data-slot]');
            if (slotButton) {
                selectStructureHotbarSlot(Number(slotButton.dataset.slot), {activatePlace: event.detail > 1});
                refreshStructureToolStatus();
                return;
            }
            const action = event.target?.closest?.('[data-action]')?.dataset?.action;
            if (action === 'drag') return;
            if (action === 'inventory') showStructureInventory();
            if (action === 'layer') {
                const current = activeStructureBrushDescriptor();
                setStructureHotbarSlot(structureActiveHotbarSlot, {...current, layer: current.layer === 1 ? 0 : 1});
            }
        });
        root.addEventListener('contextmenu', event => {
            const slotButton = event.target?.closest?.('[data-slot]');
            if (!slotButton) return;
            event.preventDefault();
            selectStructureHotbarSlot(Number(slotButton.dataset.slot));
            showStructureInventory(Number(slotButton.dataset.slot));
        });
        root.addEventListener('wheel', event => {
            event.preventDefault();
            cycleStructureHotbar(event.deltaY > 0 ? 1 : -1);
            refreshStructureToolStatus();
        }, {passive: false});
        document.body.appendChild(root);
        structureHotbarRoot = root;
        structureHotbarResizeHandler = () => updateStructureHotbarPosition();
        window.addEventListener('resize', structureHotbarResizeHandler);
        if (!structureHotbarStyle && Blockbench.addCSS) {
            structureHotbarStyle = Blockbench.addCSS(`
                #bedrock_structure_hotbar {
                    position: fixed;
                    z-index: 24;
                    left: 50%;
                    top: calc(100% - 70px);
                    transform: translate(-50%, -50%) scale(.98);
                    display: flex;
                    align-items: center;
                    gap: 5px;
                    max-width: min(92vw, 760px);
                    padding: 6px;
                    border: 1px solid color-mix(in srgb, var(--color-border) 78%, transparent);
                    border-radius: 10px;
                    background: color-mix(in srgb, var(--color-back) 90%, transparent);
                    box-shadow: 0 8px 24px #0007;
                    backdrop-filter: blur(12px);
                    opacity: 0;
                    pointer-events: none;
                    transition: opacity .12s ease, transform .12s ease;
                    touch-action: none;
                }
                #bedrock_structure_hotbar.is-visible {
                    opacity: 1;
                    pointer-events: auto;
                    transform: translate(-50%, -50%) scale(1);
                }
                #bedrock_structure_hotbar .bedrock-structure-hotbar-slots { display: flex; gap: 3px; }
                #bedrock_structure_hotbar.is-vertical,
                #bedrock_structure_hotbar.is-vertical .bedrock-structure-hotbar-slots {
                    flex-direction: column;
                }
                #bedrock_structure_hotbar.is-vertical {
                    max-height: min(86vh, 620px);
                }
                #bedrock_structure_hotbar button {
                    position: relative;
                    min-width: 34px;
                    height: 38px;
                    border: 1px solid var(--color-border);
                    border-radius: 6px;
                    background: var(--color-ui);
                    color: var(--color-text);
                    padding: 2px;
                    cursor: pointer;
                }
                #bedrock_structure_hotbar button:hover { background: var(--color-accent); color: var(--color-accent_text); }
                #bedrock_structure_hotbar .bedrock-structure-hotbar-slot.is-active {
                    border-color: var(--color-accent);
                    box-shadow: 0 0 0 2px color-mix(in srgb, var(--color-accent) 45%, transparent);
                    background: var(--color-selected);
                }
                .bedrock-structure-hotbar-thumb {
                    display: block;
                    width: 27px;
                    height: 27px;
                    margin: 3px auto 0;
                    object-fit: contain;
                    image-rendering: pixelated;
                }
                .bedrock-structure-hotbar-fallback { font-size: 24px; line-height: 31px; }
                .bedrock-structure-hotbar-number {
                    position: absolute; left: 3px; top: 1px; z-index: 2;
                    font-size: 9px; opacity: .75;
                }
                .bedrock-structure-hotbar-layer {
                    position: absolute; right: 2px; bottom: 1px; z-index: 2;
                    font-size: 8px; padding: 0 2px; border-radius: 3px;
                    background: color-mix(in srgb, var(--color-back) 80%, transparent);
                }
                #bedrock_structure_hotbar .bedrock-structure-hotbar-inventory,
                #bedrock_structure_hotbar .bedrock-structure-hotbar-layer-toggle,
                #bedrock_structure_hotbar .bedrock-structure-hotbar-grip { width: 36px; flex: 0 0 36px; }
                #bedrock_structure_hotbar .bedrock-structure-hotbar-grip {
                    cursor: grab;
                    color: var(--color-subtle_text);
                }
                #bedrock_structure_hotbar .bedrock-structure-hotbar-grip:active { cursor: grabbing; }
                #bedrock_structure_hotbar .bedrock-structure-hotbar-current {
                    position: absolute;
                    left: 50%;
                    bottom: calc(100% + 7px);
                    transform: translateX(-50%);
                    max-width: 220px;
                    overflow: hidden;
                    text-overflow: ellipsis;
                    white-space: nowrap;
                    font-size: 11px;
                    line-height: 20px;
                    opacity: .92;
                    padding: 0 8px;
                    border: 1px solid color-mix(in srgb, var(--color-border) 74%, transparent);
                    border-radius: 5px;
                    background: color-mix(in srgb, var(--color-back) 92%, transparent);
                    box-shadow: 0 3px 10px #0005;
                    pointer-events: none;
                }
                #bedrock_structure_hotbar[data-name-position="below"] .bedrock-structure-hotbar-current {
                    top: calc(100% + 7px);
                    bottom: auto;
                }
                #bedrock_structure_hotbar.is-vertical .bedrock-structure-hotbar-current {
                    max-width: 170px;
                }
                .bedrock-structure-inventory { min-height: 340px; display: flex; flex-direction: column; gap: 10px; }
                .bedrock-structure-inventory-head { display: flex; align-items: center; gap: 10px; }
                .bedrock-structure-inventory-slot { display: flex; align-items: center; gap: 6px; font-weight: 600; white-space: nowrap; }
                .bedrock-structure-inventory-search {
                    flex: 1; display: flex; align-items: center; gap: 6px; padding: 0 8px;
                    border: 1px solid var(--color-border); border-radius: 6px; background: var(--color-back);
                }
                .bedrock-structure-inventory-search:focus-within { border-color: var(--color-accent); }
                .bedrock-structure-inventory-search input {
                    flex: 1; min-width: 0; height: 32px; border: 0 !important; background: transparent !important; color: var(--color-text);
                }
                .bedrock-structure-inventory-grid {
                    display: grid; grid-template-columns: repeat(auto-fill, minmax(132px, 1fr));
                    gap: 7px; max-height: 56vh; overflow: auto; padding: 2px 4px 8px 2px;
                }
                .bedrock-structure-inventory-card {
                    min-height: 88px; display: grid; grid-template-columns: 42px 1fr; grid-template-rows: 1fr auto;
                    align-items: center; gap: 2px 8px; padding: 7px; text-align: left;
                    border: 1px solid var(--color-border); border-radius: 7px; background: var(--color-ui); color: var(--color-text);
                }
                .bedrock-structure-inventory-card:hover,
                .bedrock-structure-inventory-card.is-selected { border-color: var(--color-accent); background: var(--color-selected); }
                .bedrock-structure-inventory-icon { grid-row: 1 / 3; display: grid; place-items: center; width: 42px; height: 42px; }
                .bedrock-structure-inventory-icon img { width: 40px; height: 40px; object-fit: contain; image-rendering: pixelated; }
                .bedrock-structure-inventory-icon i { font-size: 32px; opacity: .78; }
                .bedrock-structure-inventory-name { font-weight: 600; line-height: 1.2; overflow-wrap: anywhere; }
                .bedrock-structure-inventory-card small { opacity: .68; line-height: 1.1; }
                .bedrock-structure-inventory-empty { flex: 1; min-height: 230px; display: grid; place-items: center; align-content: center; gap: 8px; opacity: .65; }
                .bedrock-structure-inventory-empty i { font-size: 40px; }
                @media (max-width: 900px) {
                    #bedrock_structure_hotbar { gap: 3px; padding: 4px; }
                    #bedrock_structure_hotbar button { min-width: 31px; width: 31px; }
                    .bedrock-structure-inventory-grid { grid-template-columns: repeat(auto-fill, minmax(112px, 1fr)); }
                }
            `);
        }
        refreshStructureHotbar();
        return root;
    }

    function disposeStructureHotbar() {
        structureInventoryDialog?.hide?.();
        structureInventoryDialog = null;
        if (structureHotbarDragState) finishStructureHotbarDrag(null);
        if (structureHotbarResizeHandler && typeof window !== 'undefined') window.removeEventListener('resize', structureHotbarResizeHandler);
        structureHotbarResizeHandler = null;
        structureHotbarRoot?.remove?.();
        structureHotbarRoot = null;
        structureHotbarStyle?.delete?.();
        structureHotbarStyle = null;
    }

    function structureInspectorForm() {
        const runtime = isStructureProject() ? ensureLogicalRuntime() : null;
        const selectedCount = Number(runtime?.selected?.size || 0);
        const cube = selectedCount === 1 ? runtime.selected.values().next().value : null;
        const selectedGeometryNode = isStructureProject()
            ? selectedStructureOutlinerNodes().find(item => item?.mcstructure_chunk_id || item?.mcstructure_baked_layer) || null
            : null;
        const shape = cube ? cachedBlockShape(cube, optimizedPreview?.recordMap || null) : null;
        const position = cube ? getStructureGridPosition(cube) : [0, 0, 0];
        const status = cube
            ? `${cube.mcstructure_block} · ${shape.key}${shape.approximate ? ` · ${tr('bedrock_structure.ui.approximate', 'approximate')}` : ''}`
            : selectedCount > 1
                ? trf('bedrock_structure.ui.selection_multiple', '{0} cells selected · bulk block data is available below', [selectedCount.toLocaleString()])
                : selectedGeometryNode
                    ? trf('bedrock_structure.ui.selection_geometry', '{0} · {1} selected', [
                        selectedGeometryNode.name,
                        selectedGeometryNode.mcstructure_chunk_id
                            ? tr('bedrock_structure.ui.selection_chunk', 'chunk')
                            : tr('bedrock_structure.ui.selection_render_layer', 'render layer')
                    ])
                    : tr('bedrock_structure.ui.inspector.empty', 'Select a logical cell in the viewport to inspect its block data.');

        return {
            inspector_status: {
                type: 'bar_display',
                icon: cube ? 'deployed_code' : selectedCount > 1 ? 'select_all' : selectedGeometryNode ? 'view_in_ar' : 'ads_click',
                value: status,
                paragraph: false,
                expand: true,
                color: cube ? 'var(--color-text)' : 'var(--color-subtle_text)'
            },
            grid_position: {
                type: 'custom_vector',
                label: 'bedrock_structure.ui.position',
                description: 'bedrock_structure.ui.position.desc',
                dimensions: 3,
                integer: true,
                step: 1,
                axis_labels: true,
                value: position,
                default: position,
                resettable: false,
                condition: () => Boolean(cube),
                onBefore: beginStructureInspectorGesture,
                onAfter: endStructureInspectorGesture
            },
            block_identifier: {
                type: 'compact_text',
                label: 'bedrock_structure.ui.block',
                description: 'bedrock_structure.ui.block.desc',
                value: cube?.mcstructure_block || '',
                icon: 'deployed_code',
                placeholder: 'minecraft:stone',
                condition: () => Boolean(cube),
            },
            shape_override: {
                type: 'compact_select',
                label: 'bedrock_structure.ui.shape',
                description: 'bedrock_structure.ui.shape.desc',
                value: cube?.mcstructure_shape_override || 'auto',
                show_value_text: true,
                background: 'transparent',
                options: {
                    auto: {name: tr('bedrock_structure.ui.shape.auto', 'Auto'), icon: 'auto_awesome'},
                    full: {name: tr('bedrock_structure.ui.shape.full', 'Full cube'), icon: 'check_box_outline_blank'},
                    slab: {name: tr('bedrock_structure.ui.shape.slab', 'Slab'), icon: 'horizontal_rule'},
                    stairs: {name: tr('bedrock_structure.ui.shape.stairs', 'Stairs'), icon: 'stairs'},
                    fence: {name: tr('bedrock_structure.ui.shape.fence', 'Fence'), icon: 'fence'},
                    wall: {name: tr('bedrock_structure.ui.shape.wall', 'Wall'), icon: 'view_week'},
                    cross: {name: tr('bedrock_structure.ui.shape.cross', 'Cross plant'), icon: 'grass'},
                    none: {name: tr('bedrock_structure.ui.shape.none', 'No geometry'), icon: 'visibility_off'}
                },
                condition: () => Boolean(cube),
            },
            block_layer: {
                type: 'horizontal_select',
                label: 'bedrock_structure.ui.layer',
                value: String(cube?.mcstructure_layer || 0),
                options: {
                    0: {name: tr('bedrock_structure.field.layer_primary', 'Primary'), icon: 'filter_1'},
                    1: {name: tr('bedrock_structure.field.layer_secondary', 'Secondary'), icon: 'filter_2'}
                },
                condition: () => Boolean(cube),
            },
        };
    }

    function structureWorkspaceForm() {
        const packPath = String(Project?.mcstructure_resource_pack_path || rememberedResourcePackPath() || '');
        const packName = packPath ? packPath.split(/[\\/]/).filter(Boolean).pop() : '';
        const packLoaded = isStructureProject() && resourcePackResolvers.has(Project);
        const packStats = packLoaded ? resourcePackResolvers.get(Project)?.atlasStats?.() || null : null;
        const customDiagnostics = packStats?.customGeometry?.diagnostics || {total: 0, counts: {}, details: []};
        const customDiagnosticTotal = Number(customDiagnostics.total || 0);
        const customDiagnosticSummary = customDiagnosticTotal
            ? trf('bedrock_structure.ui.workspace.custom_geometry_summary', 'Custom geometry: {0} missing geometry · {1} dangling material aliases.', [
                Number(customDiagnostics.counts?.missing_geometry || 0).toLocaleString(),
                Number(customDiagnostics.counts?.dangling_material_alias || 0).toLocaleString(),
            ])
            : '';
        const customDiagnosticPreview = (customDiagnostics.details || []).slice(0, 3).map(diagnostic => {
            const subject = diagnostic.block || diagnostic.geometry || 'custom block';
            const target = diagnostic.target || diagnostic.alias || diagnostic.geometry || '';
            return `${diagnostic.type}: ${subject}${target ? ` → ${target}` : ''}`;
        }).join(' · ');
        const layerCounts = Object.fromEntries(Object.keys(RENDER_LAYER_DEFINITIONS).map(id => [id, 0]));
        Object.assign(layerCounts, optimizedPreview?.stats?.blockLayers || {});
        const activeRenderLayer = Object.prototype.hasOwnProperty.call(layerCounts, structureRenderLayer)
            ? structureRenderLayer
            : '';
        const onTab = tab => result => String(result?.workspace_tab || structureWorkspaceTab) === tab;

        return {
            workspace_tab: {
                type: 'horizontal_select',
                variant: 'panel_tabs',
                value: structureWorkspaceTab,
                allow_empty: false,
                multi_select: false,
                expand: true,
                options: {
                    resource: {name: tr('bedrock_structure.ui.workspace.assets', 'Assets'), icon: 'folder_special'},
                    layers: {name: tr('bedrock_structure.ui.workspace.layers', 'Layer selection'), icon: 'layers'},
                    renderer: {name: tr('bedrock_structure.ui.workspace.preview', 'Preview'), icon: 'speed'}
                }
            },
            resource_pack_status: {
                type: 'bar_display',
                icon: packLoaded ? (customDiagnosticTotal ? 'warning' : 'folder_special') : packPath ? 'warning' : 'folder_off',
                value: packLoaded
                    ? customDiagnosticTotal
                        ? trf('bedrock_structure.ui.workspace.pack_loaded_diagnostics', '{0} · loaded and remembered · {1} custom geometry diagnostics', [packName, customDiagnosticTotal.toLocaleString()])
                        : trf('bedrock_structure.ui.workspace.pack_loaded', '{0} · loaded and remembered', [packName])
                    : packPath
                        ? trf('bedrock_structure.ui.workspace.pack_unavailable', '{0} · unavailable', [packName])
                        : tr('bedrock_structure.ui.workspace.generated_preview', 'Generated previews · choose a Bedrock resource pack for exact textures'),
                description: customDiagnosticTotal
                    ? `${customDiagnosticSummary}${customDiagnosticPreview ? ` ${customDiagnosticPreview}` : ''}`
                    : packPath || tr('bedrock_structure.ui.workspace.choose_pack_desc', 'Choose a Bedrock resource-pack folder. A successful path is remembered for future structures.'),
                paragraph: false,
                expand: true,
                color: packLoaded && !customDiagnosticTotal ? 'var(--color-text)' : 'var(--color-subtle_text)',
                condition: onTab('resource')
            },
            load_resource_pack: {
                type: 'action_button', icon: 'folder_open', text: packPath ? 'bedrock_structure.ui.change_pack' : 'bedrock_structure.ui.choose_pack', semantic_button: true, condition: onTab('resource'), click: chooseResourcePack
            },
            clear_resource_pack: {
                type: 'action_button', icon: 'link_off', text: 'bedrock_structure.ui.forget_pack', semantic_button: true, disable: !packPath, condition: onTab('resource'), click: clearRememberedResourcePack
            },
            render_layer_select: {
                type: 'horizontal_select',
                label: 'bedrock_structure.ui.render_layer',
                description: 'bedrock_structure.ui.render_layer.desc',
                value: activeRenderLayer,
                allow_empty: true,
                multi_select: false,
                condition: onTab('layers'),
                options: {
                    solid: {name: `${tr('bedrock_structure.ui.layer.solid', 'Solid')} · ${Number(layerCounts.solid || 0).toLocaleString()}`, icon: 'view_in_ar'},
                    vegetation: {name: `${tr('bedrock_structure.ui.layer.cross', 'Cross')} · ${Number(layerCounts.vegetation || 0).toLocaleString()}`, icon: 'grass'},
                    translucent: {name: `${tr('bedrock_structure.ui.layer.translucent', 'Translucent')} · ${Number(layerCounts.translucent || 0).toLocaleString()}`, icon: 'blur_on'},
                    animated: {name: `${tr('bedrock_structure.ui.layer.animated', 'Animated')} · ${Number(layerCounts.animated || 0).toLocaleString()}`, icon: 'animation'}
                }
            },
            bake_editable_mesh: {
                type: 'action_button',
                description: 'bedrock_structure.ui.workspace.bake_desc',
                icon: 'deployed_code',
                text: 'bedrock_structure.ui.bake',
                semantic_button: true,
                condition: onTab('layers'),
                click: bakeStructureToEditableMeshes
            },
            chunk_size: {
                type: 'compact_select',
                label: 'bedrock_structure.ui.chunk_size',
                description: 'bedrock_structure.ui.chunk_size.desc',
                value: String(Project?.mcstructure_chunk_size || 16),
                show_value_text: true,
                background: 'transparent',
                condition: onTab('renderer'),
                options: {
                    8: {name: tr('bedrock_structure.ui.chunk_size.editing', '8 × 8 · Editing'), icon: 'grid_4x4'},
                    16: {name: tr('bedrock_structure.ui.chunk_size.minecraft', '16 × 16 · Minecraft'), icon: 'grid_view'},
                    32: {name: tr('bedrock_structure.ui.chunk_size.large', '32 × 32 · Large'), icon: 'apps'},
                    64: {name: tr('bedrock_structure.ui.chunk_size.maximum', '64 × 64 · Maximum'), icon: 'select_all'}
                }
            },
            optimization_stats: {
                type: 'bar_display',
                icon: 'analytics',
                value: optimizedPreviewStatsText(),
                paragraph: false,
                expand: true,
                color: 'var(--color-subtle_text)',
                condition: onTab('renderer')
            },
            rebuild_preview: {
                type: 'action_button',
                description: 'bedrock_structure.ui.workspace.rebuild_desc',
                icon: 'refresh',
                text: 'bedrock_structure.ui.rebuild',
                semantic_button: true,
                condition: onTab('renderer'),
                click: () => {
                    buildOptimizedPreview();
                    updateLogicalSelectionHelpers();
                    syncStructurePanel();
                }
            }
        };
    }

    function applyStructurePanelLayouts() {
        const applyGroups = window.LightManagerUI?.applyFormGroups || window.applyIndestructibleFormGroups;
        if (typeof applyGroups !== 'function') return;

        if (structureWorkspacePanel?.form) {
            applyGroups(structureWorkspacePanel.form, [
                {
                    elements: ['resource_pack_status', '_', 'load_resource_pack', 'clear_resource_pack'],
                    gap: '6px',
                    flex: {resource_pack_status: '1 1 380px', load_resource_pack: '0 1 150px', clear_resource_pack: '0 1 120px'},
                    class_name: 'bedrock_structure_workspace_row',
                    aria_label: tr('bedrock_structure.ui.workspace.resource_controls', 'Resource pack controls')
                },
                {
                    elements: ['render_layer_select', '_', 'bake_editable_mesh'],
                    gap: '5px',
                    flex: {
                        render_layer_select: '1 1 520px',
                        bake_editable_mesh: '0 1 180px'
                    },
                    class_name: 'bedrock_structure_workspace_row',
                    aria_label: tr('bedrock_structure.ui.workspace.render_layer_controls', 'Render layer selection and bake controls')
                },
                {
                    elements: ['chunk_size', 'optimization_stats', '_', 'rebuild_preview'],
                    gap: '6px',
                    flex: {chunk_size: '0 1 280px', optimization_stats: '1 1 360px', rebuild_preview: '0 1 170px'},
                    class_name: 'bedrock_structure_workspace_row',
                    aria_label: tr('bedrock_structure.ui.workspace.renderer_controls', 'Renderer controls')
                }
            ]);
        }
    }

    function rebuildStructurePanelForm(panel, builder) {
        if (!panel?.form) return;
        panel.form.form_config = builder();
        panel.form.buildForm();
        // InputForm.buildForm does not re-run conditions. Re-evaluate once so
        // workspace tabs immediately hide inactive groups after every sync.
        panel.form.updateValues?.({cause: 'setup'});
        if (panel === structureInspectorPanel) {
            const status = panel.form.form_data?.inspector_status;
            status?.node?.setAttribute?.('role', 'status');
            status?.node?.setAttribute?.('aria-live', 'polite');
        }
    }

    function syncStructurePanel() {
        if (structurePanelSyncing || !isStructureProject()) return;
        structurePanelSyncing = true;
        try {
            rebuildStructurePanelForm(structureInspectorPanel, structureInspectorForm);
            rebuildStructurePanelForm(structureWorkspacePanel, structureWorkspaceForm);
        } finally {
            structurePanelSyncing = false;
        }
    }

    function refreshStructureStatusDisplays() {
        if (!isStructureProject()) return;
        try {
            const inspector = structureInspectorForm();
            structureInspectorPanel?.form?.form_data?.inspector_status?.setValue?.(inspector.inspector_status.value);
        } catch (error) {
            warnOnce('structure status refresh', error);
        }
    }

    function beginStructureInspectorGesture() {
        structureInspectorGestureDepth += 1;
        if (
            structureInspectorGestureDepth === 1 &&
            !structureInspectorUndoSession &&
            typeof Undo !== 'undefined' &&
            typeof Undo.initEdit === 'function' &&
            isStructureProject() &&
            !Undo.current_save
        ) {
            const selected = selectedStructureBlocks();
            const targets = {
                ids: selected.length === 1 ? [selected[0].mcstructure_runtime_id].filter(Boolean) : [],
                keys: [],
            };
            const aspects = {[LOGICAL_UNDO_ASPECT]: {full: false, targets}};
            structureInspectorUndoSession = {
                before: serializeLogicalRuntimeForUndo(Project, targets),
                aspects,
                targets,
            };
            Undo.initEdit(aspects);
        }
    }

    function rememberInspectorDirtyPositions(hints) {
        for (const hint of hints || []) {
            const position = hint?.position;
            if (!Array.isArray(position) || position.length < 3) continue;
            const layer = Number(hint?.layer || 0) === 1 ? 1 : 0;
            const normalized = position.slice(0, 3).map(value => Math.round(Number(value) || 0));
            structureInspectorPendingDirtyPositions.set(spatialRecordKey(normalized[0], normalized[1], normalized[2], layer), {position: normalized, layer});
        }
    }

    function endStructureInspectorGesture() {
        structureInspectorGestureDepth = Math.max(0, structureInspectorGestureDepth - 1);
        if (!structureInspectorGestureDepth && structureInspectorUndoSession) {
            const session = structureInspectorUndoSession;
            structureInspectorUndoSession = null;
            const after = serializeLogicalRuntimeForUndo(Project, session.targets);
            if (session.before === after) Undo.cancelEdit?.(false);
            else Undo.finishEdit(
                tr('bedrock_structure.undo.edit_block', 'Edit structure block data'),
                session.aspects
            );
        }
        if (!structureInspectorGestureDepth && structureInspectorPendingPreview) {
            structureInspectorPendingPreview = false;
            const dirty = Array.from(structureInspectorPendingDirtyPositions.values());
            structureInspectorPendingDirtyPositions.clear();
            scheduleOptimizedPreviewRebuild(0, dirty.length ? dirty : null);
        }
    }

    function requestStructureInspectorPreviewRebuild(dirtyPositions = null) {
        if (Array.isArray(dirtyPositions) && dirtyPositions.length) rememberInspectorDirtyPositions(dirtyPositions);
        if (structureInspectorGestureDepth > 0) {
            structureInspectorPendingPreview = true;
            return;
        }
        const dirty = Array.from(structureInspectorPendingDirtyPositions.values());
        structureInspectorPendingDirtyPositions.clear();
        scheduleOptimizedPreviewRebuild(35, dirty.length ? dirty : dirtyPositions);
    }

    function applyStructureInspectorChange(result) {
        if (structurePanelSyncing || !isStructureProject() || !result) return;
        const runtime = ensureLogicalRuntime();
        // Editing the first element of a multi-selection is surprising and was
        // one of the main sources of inspector ambiguity. Property editing is
        // deliberately single-selection; bulk transforms stay in the native toolbar.
        const cube = runtime?.selected?.size === 1 ? runtime.selected.values().next().value : null;
        let needsRebuild = false;
        let rebuildHints = null;
        if (cube && runtime) {
            const currentPosition = getStructureGridPosition(cube);
            const currentLayer = Number(cube.mcstructure_layer || 0);
            const nextPosition = Array.isArray(result.grid_position)
                ? result.grid_position.slice(0, 3).map(value => Math.round(Number(value) || 0))
                : currentPosition;
            const nextBlockRaw = String(result.block_identifier || cube.mcstructure_block || 'minecraft:stone').trim();
            const nextBlock = (nextBlockRaw || cube.mcstructure_block).includes(':')
                ? (nextBlockRaw || cube.mcstructure_block)
                : `minecraft:${nextBlockRaw || cube.mcstructure_block}`;
            const nextShape = String(result.shape_override || cube.mcstructure_shape_override || 'auto');
            const nextLayer = Number(result.block_layer ?? currentLayer);
            const positionChanged = currentPosition.some((value, axis) => value !== nextPosition[axis]);
            const changed = positionChanged
                || cube.mcstructure_block !== nextBlock
                || cube.mcstructure_shape_override !== nextShape
                || currentLayer !== nextLayer;
            if (changed && (nextLayer === 0 || nextLayer === 1)) {
                const nextKey = spatialRecordKey(nextPosition[0], nextPosition[1], nextPosition[2], nextLayer);
                const collision = runtime.byKey.get(nextKey);
                runtime.positionData ||= new Map();
                const currentPositionKey = logicalPositionKey(currentPosition);
                const nextPositionKey = logicalPositionKey(nextPosition);
                const sourcePositionData = positionChanged ? runtime.positionData.get(currentPositionKey) : null;
                const sourceOccupants = positionChanged ? logicalRecordsAtPosition(runtime, currentPosition) : [];
                const partialSourceMetadata = Boolean(
                    positionChanged
                    && sourcePositionData
                    && sourceOccupants.some(record => record !== cube)
                );
                const destinationMetadataCollision = Boolean(
                    positionChanged
                    && nextPositionKey !== currentPositionKey
                    && runtime.positionData.has(nextPositionKey)
                );
                if (partialSourceMetadata) {
                    Blockbench.showQuickMessage(positionDataSelectionConflictMessage('move', {
                        position: currentPosition,
                    }), 5200);
                    structureInspectorPanel?.form?.form_data?.grid_position?.setValue?.(currentPosition);
                } else if (destinationMetadataCollision) {
                    Blockbench.showQuickMessage(
                        `The destination (${nextPosition.join(', ')}) already contains block position data.`,
                        4200
                    );
                    structureInspectorPanel?.form?.form_data?.grid_position?.setValue?.(currentPosition);
                } else if (collision && collision !== cube) {
                    Blockbench.showQuickMessage('That cell is already occupied in this layer.', 2200);
                    structureInspectorPanel?.form?.form_data?.grid_position?.setValue?.(currentPosition);
                } else {
                    const applyChange = () => {
                        rebuildHints = [
                            {position: currentPosition.slice(), layer: currentLayer},
                            {position: nextPosition.slice(), layer: nextLayer},
                        ];
                        runtime.byKey.delete(spatialRecordKey(currentPosition[0], currentPosition[1], currentPosition[2], currentLayer));
                        cube.mcstructure_block = nextBlock;
                        cube.mcstructure_shape_override = nextShape;
                        cube.mcstructure_layer = nextLayer;
                        cube.mcstructure_grid_position = nextPosition;
                        cube.visibility = nextLayer === 0 || Boolean(Project.mcstructure_secondary_visible);
                        const states = (() => { try { return parseObjectJSON(cube.mcstructure_states_json || '{}', 'Block states'); } catch { return {}; } })();
                        cube.name = makeBlockLabel({name: cube.mcstructure_block, states, version: cube.mcstructure_version}, nextLayer);
                        runtime.byKey.set(logicalRecordKey(cube), cube);
                        if (positionChanged && sourcePositionData && nextPositionKey !== currentPositionKey) {
                            runtime.positionData.delete(currentPositionKey);
                            runtime.positionData.set(nextPositionKey, sourcePositionData);
                        }
                        touchLogicalRuntime(runtime, {rebuildIndex: false});
                        updateLogicalSelectionHelpers();
                        return true;
                    };
                    needsRebuild = Boolean(
                        structureInspectorUndoSession
                            ? applyChange()
                            : runLogicalUndo(
                                tr('bedrock_structure.undo.edit_block', 'Edit structure block data'),
                                applyChange,
                                {
                                    targets: {
                                        ids: [cube.mcstructure_runtime_id].filter(Boolean),
                                        keys: [],
                                        positionKeys: [currentPositionKey, nextPositionKey],
                                        selection: false,
                                    }
                                }
                            )
                    );
                }
            }
        }
        Project.mcstructure_optimized_preview = true;
        if (needsRebuild) requestStructureInspectorPreviewRebuild(rebuildHints);
        // Do not rebuild the inspector while NumSlider is dragging or a text field
        // is committing; that would steal focus. Refresh lightweight status text
        // in place and let the debounced preview rebuild perform the full sync.
        refreshStructureStatusDisplays();
    }

    function applyStructureWorkspaceChange(result) {
        if (structurePanelSyncing || !isStructureProject() || !result) return;
        const nextTab = String(result.workspace_tab || structureWorkspaceTab || 'layers');
        if (['resource', 'layers', 'renderer'].includes(nextTab)) structureWorkspaceTab = nextTab;

        const nextRenderLayer = String(result.render_layer || '');
        if (['solid', 'vegetation', 'translucent', 'animated'].includes(nextRenderLayer)
            && nextRenderLayer !== structureRenderLayer) {
            selectLogicalRenderLayer(nextRenderLayer);
        }

        const nextChunkSize = Math.max(4, Math.min(64, Math.round(Number(result.chunk_size) || Number(Project.mcstructure_chunk_size || 16))));
        if (nextChunkSize !== Number(Project.mcstructure_chunk_size || 16)) {
            runLogicalUndo(
                tr('bedrock_structure.undo.chunk_size', 'Change preview chunk size'),
                () => {
                    Project.mcstructure_chunk_size = nextChunkSize;
                    Project.saved = false;
                    scheduleOptimizedPreviewRebuild(0);
                    return true;
                },
                {targets: {ids: [], keys: [], positionData: false, selection: false}}
            );
        }
    }

    function addStructurePanelStyle(style) {
        if (style?.delete) structurePanelStyles.push(style);
        return style;
    }

    function createStructurePanel() {
        if (structureInspectorPanel || structureWorkspacePanel || typeof Panel === 'undefined') return;
        const condition = {formats: [FORMAT_ID], modes: [STRUCTURE_MODE_ID]};

        structureInspectorPanel = new Panel('bedrock_structure_inspector', {
            name: tr('bedrock_structure.ui.panel.inspector', 'Cell Inspector'),
            icon: 'deployed_code',
            growable: false,
            resizable: true,
            min_height: 250,
            condition,
            default_position: {
                slot: 'right_bar',
                float_position: [0, 0],
                float_size: [390, 480],
                height: 360,
                fixed_height: true,
                folded: false,
                attached_to: '',
                sidebar_index: 0
            },
            form: structureInspectorForm()
        });

        structureWorkspacePanel = new Panel('bedrock_structure_workspace', {
            name: tr('bedrock_structure.ui.panel.workspace', 'Structure Workspace'),
            icon: 'dashboard_customize',
            growable: false,
            resizable: true,
            min_height: 88,
            condition,
            default_position: {
                slot: 'bottom',
                float_position: [180, 520],
                float_size: [980, 210],
                height: 120,
                fixed_height: false,
                folded: true,
                attached_to: ''
            },
            form: structureWorkspaceForm()
        });

        structurePanelListeners.push(
            structureInspectorPanel.form.on('change', ({result}) => applyStructureInspectorChange(result)),
            structureWorkspacePanel.form.on('change', ({result}) => applyStructureWorkspaceChange(result))
        );
        applyStructurePanelLayouts();

        const ui = window.LightManagerUI;
        addStructurePanelStyle(ui?.addDesignedPanelStyles?.('bedrock_structure_inspector', {row_padding: '3px 4px', scrollbar_width: 4}));
        addStructurePanelStyle(ui?.addCompactPanelStyles?.('bedrock_structure_workspace'));
        addStructurePanelStyle(Blockbench.addCSS(`
            #panel_bedrock_structure_inspector,
            #panel_bedrock_structure_workspace {
                box-sizing: border-box;
                min-width: 0;
                background: var(--color-ui);
            }

            #panel_bedrock_structure_inspector .form {
                padding: 4px !important;
                scrollbar-gutter: stable;
            }
            #panel_bedrock_structure_inspector .dialog_bar,
            #panel_bedrock_structure_inspector .full_width_dialog_bar {
                min-width: 0;
            }
            #panel_bedrock_structure_inspector .light_manager_horizontal_select {
                min-width: 0 !important;
                width: 100% !important;
            }
            #panel_bedrock_structure_inspector .light_manager_horizontal_select .horizontal_select_btn {
                min-width: 0 !important;
                padding: 0 4px !important;
                overflow: hidden;
                gap: 3px;
            }
            #panel_bedrock_structure_inspector .light_manager_horizontal_select .horizontal_select_btn:not(.icon_only) .horizontal_select_icon {
                margin-right: 0 !important;
                flex: 0 0 auto;
            }
            #panel_bedrock_structure_inspector .light_manager_horizontal_select .horizontal_select_label {
                min-width: 0;
                max-width: 100%;
                overflow: hidden;
                text-overflow: ellipsis;
                white-space: nowrap;
                font-size: 11px;
                line-height: 1.1;
            }
            @media (max-width: 1450px) {
                #panel_bedrock_structure_inspector .light_manager_horizontal_select .horizontal_select_btn {
                    padding: 0 3px !important;
                }
                #panel_bedrock_structure_inspector .light_manager_horizontal_select .horizontal_select_label {
                    font-size: 10px;
                }
            }

            #panel_bedrock_structure_workspace .form {
                box-sizing: border-box;
                padding: 4px 6px !important;
                overflow-y: auto !important;
                overflow-x: hidden !important;
            }
            #panel_bedrock_structure_workspace .light_manager_form_variant_panel_tabs {
                margin: 0 0 4px 0 !important;
                padding: 0 !important;
            }
            #panel_bedrock_structure_workspace .bedrock_structure_workspace_row {
                min-width: 0;
                min-height: 34px;
                flex-wrap: wrap;
                padding: 0 !important;
            }

            #panel_bedrock_structure_inspector .bar_display_content,
            #panel_bedrock_structure_workspace .bar_display_content {
                min-width: 0;
                overflow: hidden;
                text-overflow: ellipsis;
                white-space: nowrap;
            }
            #panel_bedrock_structure_inspector .dialog_form_description,
            #panel_bedrock_structure_workspace .dialog_form_description {
                display: none !important;
            }

            #panel_bedrock_structure_inspector .light_manager_action_button,
            #panel_bedrock_structure_workspace .light_manager_action_button {
                min-height: 30px;
                box-sizing: border-box;
                border: 1px solid var(--color-border) !important;
                border-radius: 3px !important;
                background: var(--color-button) !important;
                font: inherit;
                text-align: center;
                transition: background-color 120ms ease, border-color 120ms ease, transform 80ms ease !important;
            }
            #panel_bedrock_structure_inspector .light_manager_action_button:hover,
            #panel_bedrock_structure_workspace .light_manager_action_button:hover {
                border-color: color-mix(in srgb, var(--color-accent) 45%, var(--color-border)) !important;
                background: color-mix(in srgb, var(--color-button) 82%, var(--color-text) 18%) !important;
            }
            #panel_bedrock_structure_inspector .light_manager_action_button:focus-visible,
            #panel_bedrock_structure_workspace .light_manager_action_button:focus-visible {
                outline: 2px solid var(--color-accent) !important;
                outline-offset: -2px;
            }
            #panel_bedrock_structure_inspector .light_manager_action_button:active,
            #panel_bedrock_structure_workspace .light_manager_action_button:active {
                transform: translateY(1px);
            }

            #panel_bedrock_structure_workspace .light_manager_form_variant_panel_tabs button,
            #panel_bedrock_structure_workspace .light_manager_form_variant_panel_tabs [role="button"] {
                min-height: 32px;
            }

            @media (prefers-reduced-motion: reduce) {
                #panel_bedrock_structure_inspector *,
                #panel_bedrock_structure_workspace * {
                    transition-duration: 0.001ms !important;
                    animation-duration: 0.001ms !important;
                    animation-iteration-count: 1 !important;
                }
                #panel_bedrock_structure_inspector .light_manager_action_button:active,
                #panel_bedrock_structure_workspace .light_manager_action_button:active {
                    transform: none !important;
                }
            }

            body[mode="${STRUCTURE_MODE_ID}"] #panel_transform,
            body[mode="${STRUCTURE_MODE_ID}"] #panel_element { display: none !important; }
        `));

        // Plugin reloads can happen while a structure project is already in the
        // Structure mode, in which case Mode.onSelect will not fire again.
        setTimeout(() => { if (isStructureModeSelected()) applyStructureWorkspaceDefaults(); }, 0);
    }

    function destroyStructurePanel() {
        for (const listener of structurePanelListeners.splice(0).reverse()) listener?.delete?.();
        structureWorkspacePanel?.delete?.();
        structureInspectorPanel?.delete?.();
        structureWorkspacePanel = null;
        structureInspectorPanel = null;
        structureInspectorGestureDepth = 0;
        structureInspectorPendingPreview = false;
        for (const style of structurePanelStyles.splice(0).reverse()) style?.delete?.();
    }

    function exposePanelInStructureMode(panelId, defaultPosition = null) {
        const panel = window.Panels?.[panelId];
        if (!panel) return;
        const modes = panel.condition?.modes;
        if (Array.isArray(modes) && !modes.includes(STRUCTURE_MODE_ID)) {
            modes.push(STRUCTURE_MODE_ID);
            structureModePanelOwnership.push({panel, modes});
        }
        if (defaultPosition) {
            panel.default_configuration ||= {};
            panel.default_configuration.mode_positions ||= {};
            if (!panel.default_configuration.mode_positions[STRUCTURE_MODE_ID]) {
                panel.default_configuration.mode_positions[STRUCTURE_MODE_ID] = defaultPosition;
                structureModePanelOwnership.push({panel, position: true});
            }
        }
    }

    function removePanelFromStructureMode(panelId) {
        const panel = window.Panels?.[panelId];
        const modes = panel?.condition?.modes;
        if (!Array.isArray(modes)) return;
        let index;
        while ((index = modes.indexOf(STRUCTURE_MODE_ID)) >= 0) modes.splice(index, 1);
    }

    function applyStructureWorkspaceDefaults() {
        if (
            !isStructureModeSelected() ||
            !structureInspectorPanel ||
            !structureWorkspacePanel ||
            !window.Panels?.outliner
        ) return false;
        let alreadyMigrated = false;
        try { alreadyMigrated = localStorage.getItem(WORKSPACE_LAYOUT_STORAGE_KEY) === '1'; } catch {}
        if (alreadyMigrated) return false;
        try {
            const viewportHeight = Math.max(640, Number(window.innerHeight || 900));
            const inspectorHeight = Math.max(300, Math.min(420, Math.round(viewportHeight * 0.40)));
            const workspaceHeight = Math.max(100, Math.min(140, Math.round(viewportHeight * 0.13)));

            Panels.outliner.customizePosition?.({
                slot: 'right_bar', attached_to: '', sidebar_index: 1,
                height: 260, fixed_height: true, folded: false,
            });
            structureInspectorPanel.customizePosition?.({
                slot: 'right_bar', attached_to: '', sidebar_index: 0,
                height: inspectorHeight, fixed_height: true, folded: false,
            });
            structureWorkspacePanel.customizePosition?.({
                slot: 'bottom', attached_to: '', height: workspaceHeight,
                fixed_height: false, folded: true,
            });

            Panels.outliner.updateSlot?.();
            structureInspectorPanel.updateSlot?.();
            structureWorkspacePanel.updateSlot?.();
            window.updateInterfacePanels?.();
            try { localStorage.setItem(WORKSPACE_LAYOUT_STORAGE_KEY, '1'); } catch {}
            return true;
        } catch (error) {
            warnOnce('structure workspace layout', error);
            return false;
        }
    }

    function registerStructureMode() {
        if (structureMode || typeof Mode === 'undefined') return;
        if (typeof Tool !== 'undefined') {
            const toolSelected = () => {
                structureToolHoverHit = null;
                const runtime = isStructureProject() ? ensureLogicalRuntime() : null;
                if (runtime) runtime.hovered = null;
                updateLogicalSelectionHelpers();
                updateStructureToolPreview();
                refreshStructureHotbar();
                refreshStructureToolStatus();
            };
            structureSelectTool = new Tool(STRUCTURE_TOOL_IDS.select, {
                name: 'bedrock_structure.ui.select_tool',
                description: 'bedrock_structure.ui.select_tool.desc',
                icon: 'ads_click',
                category: 'tools',
                modes: [STRUCTURE_MODE_ID],
                selectElements: true,
                onSelect: toolSelected,
            });
            structureRegionTool = new Tool(STRUCTURE_TOOL_IDS.region, {
                name: tr('bedrock_structure.ui.region_tool', 'Region Select'),
                description: tr('bedrock_structure.ui.region_tool.desc', 'Drag from one structure block to another to select the whole cuboid. Hold Shift to add it to the current selection.'),
                icon: 'select_all',
                category: 'tools',
                modes: [STRUCTURE_MODE_ID],
                selectElements: false,
                keybind: typeof Keybind !== 'undefined' ? new Keybind({key: 'r'}) : undefined,
                onSelect: toolSelected,
            });
            structurePlaceTool = new Tool(STRUCTURE_TOOL_IDS.place, {
                name: 'bedrock_structure.ui.place_tool',
                description: 'bedrock_structure.ui.place_tool.desc',
                icon: 'add_box',
                category: 'tools',
                modes: [STRUCTURE_MODE_ID],
                selectElements: false,
                keybind: typeof Keybind !== 'undefined' ? new Keybind({key: 'b'}) : undefined,
                onSelect: toolSelected,
            });
            structureEraseTool = new Tool(STRUCTURE_TOOL_IDS.erase, {
                name: 'bedrock_structure.ui.erase_tool',
                description: 'bedrock_structure.ui.erase_tool.desc',
                icon: 'ink_eraser',
                category: 'tools',
                modes: [STRUCTURE_MODE_ID],
                selectElements: false,
                keybind: typeof Keybind !== 'undefined' ? new Keybind({key: 'x'}) : undefined,
                onSelect: toolSelected,
            });
            structurePickTool = new Tool(STRUCTURE_TOOL_IDS.pick, {
                name: 'bedrock_structure.ui.pick_tool',
                description: 'bedrock_structure.ui.pick_tool.desc',
                icon: 'colorize',
                category: 'tools',
                modes: [STRUCTURE_MODE_ID],
                selectElements: false,
                keybind: typeof Keybind !== 'undefined' ? new Keybind({key: 'p'}) : undefined,
                onSelect: toolSelected,
            });
        }
        structureMode = new Mode(STRUCTURE_MODE_ID, {
            name: tr('bedrock_structure.ui.mode', 'Structure'),
            icon: 'account_tree',
            category: 'navigate',
            default_tool: structureSelectTool?.id || 'move_tool',
            selectElements: true,
            condition: {formats: [FORMAT_ID]},
            onSelect() {
                ensureStructureOutlinerHierarchy();
                updateLogicalSelectionHelpers();
                syncStructurePanel();
                createStructureHotbar();
                refreshStructureHotbar();
                refreshStructureToolStatus();
                setTimeout(applyStructureWorkspaceDefaults, 0);
            },
            onUnselect() {
                if (hoverHelper) hoverHelper.visible = false;
                if (structureToolPreviewHelper) structureToolPreviewHelper.visible = false;
                if (structureSelectionBoundsHelper) structureSelectionBoundsHelper.visible = false;
                structureHotbarRoot?.classList?.remove('is-visible');
                Blockbench.setStatusBarText?.();
            },
        });
        // Structure has no UV or texture editing surface. The redesigned workspace
        // keeps single-cell inspection above the hierarchy on the right, frequent
        // editing actions in native Blockbench toolbars, and infrequent pack/layer/
        // renderer controls in a folded bottom workspace.
        removePanelFromStructureMode('textures');
        removePanelFromStructureMode('uv');
        exposePanelInStructureMode('outliner', {slot: 'right_bar', sidebar_index: 1, height: 260, fixed_height: true});
    }

    function isStructureModeSelected() {
        return typeof Modes !== 'undefined' && Modes.selected?.id === STRUCTURE_MODE_ID;
    }

    function unregisterStructureMode() {
        structureSelectTool?.delete?.();
        structureRegionTool?.delete?.();
        structurePlaceTool?.delete?.();
        structureEraseTool?.delete?.();
        structurePickTool?.delete?.();
        structureSelectTool = null;
        structureRegionTool = null;
        structurePlaceTool = null;
        structureEraseTool = null;
        structurePickTool = null;
        structureMode?.delete?.();
        structureMode = null;
        for (const ownership of structureModePanelOwnership.splice(0).reverse()) {
            if (ownership.position) {
                delete ownership.panel.default_configuration?.mode_positions?.[STRUCTURE_MODE_ID];
                continue;
            }
            const index = ownership.modes?.indexOf(STRUCTURE_MODE_ID) ?? -1;
            if (index >= 0) ownership.modes.splice(index, 1);
        }
    }

    function addAction(action, menuPath) {
        actions.push(action);
        if (action?.id?.startsWith('bedrock_structure_')) structureActionItems.set(action.id, action);
        MenuBar.addAction(action, menuPath);
        return action;
    }

